/**
 * Every capability the game has a word for, from its own dispatch-order form.
 *
 * NOTHING IS MATCHED AGAINST THIS. A requirement is still only ever answered by
 * a flag some vehicle in the table actually carries, because a rule that picks
 * a vehicle nothing in range can be is a rule that picks nothing.
 *
 * What it is for is the difference between two silences that read identically:
 * a key the game HAS a word for, where nothing in range carries it — go and
 * buy one — and a key YMCA has never heard of, which is a gap in this tool. The
 * first is the player's answer to give; the second is ours.
 */
const MM_GAME_FLAGS = new Set(["air_tanker","any_rtw","any_traffic_car","arff","boot","brush_truck","brush_truck_1","brush_truck_2","brush_truck_3","brush_truck_4","brush_truck_5","brush_vehicle","car_carrier","coastal_boat","crew_carrier","dlk","dozer_trailer","elw","elw2","fbi_bomb_tech","fbi_drone","fbi_investigation_unit","fbi_mobile_command","fbi_unit","fire","fire_aviation","fire_investigation","fireboat","flood_equipment","fly_car","foam","foam_amount","fustw","fustw_or_police_motorcycle","fwk","gkw","grtw","gwa","gwgefahrgut","gwl2wasser","gwl2wasser_only","heavy_air_tanker","hems","k9","kdow_orgl","ktw","mountain_lift","mountain_lift_2","police_drone","police_motorcycle","polizeihubschrauber","rescueboat","riot_police","rtw","rw","search_and_rescue","sheriff_unit","swat","swat_armored_vehicle","swat_suv","technical_rescue","wasser_amount","water_damage_pump","water_damage_pump_value","water_drop_helicopter"]);

/** Is this requirement key a capability the game itself names? */
function mmGameKnowsFlag(key) {
    if (MM_GAME_FLAGS.has(key)) return key;
    const squashed = key.replace(/_/g, '');
    for (const f of MM_GAME_FLAGS) if (f.replace(/_/g, '') === squashed) return f;
    return null;
}

function mmKnownTypes() {
    let learnt = {};
    try {
        learnt = JSON.parse(localStorage.getItem(MM_TYPES_KEY)) || {};
    } catch (e) { /* nothing learnt yet */ }
    const known = {};
    /* A shipped entry may carry a name and nothing else: the buy pages name every
     * type the game sells, but they do not say what a vehicle covers. An entry
     * without capabilities stays unknown here, so a vehicle already at the mission
     * is left alone rather than judged to cover nothing. */
    for (const [id, t] of Object.entries(MM_SHIPPED_TYPES)) {
        /* MEASURED FIRST, DERIVED BESIDE IT. `capabilities` came off a
         * checkbox; `namedBy` was derived from the dispatch-order editor
         * labelling its own capability boxes with the vehicle's name. Both are
         * the game's words, so both count towards what a vehicle at a mission
         * covers — but a measured set that is thin is filled out by the
         * derivation rather than replaced by it, which is why they are unioned
         * rather than one winning. */
        const both = [...new Set([
            ...(Array.isArray(t.capabilities) ? t.capabilities : []),
            ...(Array.isArray(t.namedBy) ? t.namedBy : []),
        ])];
        if (both.length) known[id] = both;
    }
    /* What this game taught wins: the player's own server is the truth here.
     *
     * An empty set is not an answer. It used to mean the vehicle carried none
     * of the handful of flags a requirement named, which is how a HazMat came
     * back with no capabilities at all; the whole set is read now, so an empty
     * one means the checkbox was read before the game had written to it.
     * Either way, storing it as "covers nothing" would let Cancel Unused send a
     * HazMat home from a HazMat call. Unknown is the safe reading, and leaving
     * the vehicle alone is what unknown already does. */
    for (const [id, t] of Object.entries(learnt)) {
        const caps = Array.isArray(t) ? t : (t.caps || []);
        if (caps.length) known[id] = caps;
    }
    return known;
}

const MM_TANKS_KEY = 'ymca-missionmagician-tanks';

/**
 * How much a type carries, learnt the same way its flags are.
 *
 * WATER ALREADY ON THE WAY COUNTED FOR NOTHING. The amount lines were written
 * with `onScene: 0` because the tally beside them counts vehicles by flag and
 * a tank is not a flag — so a call with two Water Tankers and eight Pumper
 * Tankers already driving to it was asked for the full 20,000 gallons again,
 * and the panel sent the fleet twice.
 *
 * A row at the mission carries a type id and nothing else, so what it holds
 * has to be looked up — and the selection table states it on every checkbox as
 * `wasser_amount` and `foam_amount_display`. So the tank is read off the
 * player's own game exactly as the flags are, and a type nobody has seen in a
 * selection list yet stays unknown rather than being counted as empty.
 *
 * A zero is stored as a zero. Knowing a patrol car carries nothing is an
 * answer; not knowing what a tanker carries is not, and the panel says which
 * of the two it is.
 */
function mmStoredTanks() {
    try {
        return JSON.parse(localStorage.getItem(MM_TANKS_KEY)) || {};
    } catch (e) {
        return {};
    }
}

/**
 * THE REPO IS THE HEAD START, THIS GAME IS THE TRUTH.
 *
 * Capabilities were shipped and tanks were not, so every install began blind on
 * water however many reports had come back — a figure that arrives once and is
 * not written down has to be asked for again. Shipped first, what this game
 * taught laid over the top, and the writer keeps to its own store so a repo
 * figure is never frozen into somebody's browser.
 */
function mmKnownTanks() {
    const tanks = {};
    for (const [id, t] of Object.entries(MM_SHIPPED_TYPES)) {
        if (t.tank && typeof t.tank === 'object') {
            tanks[id] = { water: t.tank.water || 0, foam: t.tank.foam || 0,
                bonus: t.tank.bonus || 0 };
        }
    }
    return { ...tanks, ...mmStoredTanks() };
}

function mmLearnTanks(vehicles) {
    const tanks = mmStoredTanks();
    let changed = false;
    for (const v of vehicles) {
        if (!v.typeId) continue;
        const had = tanks[v.typeId];
        if (had && had.water === v.water && had.foam === v.foam
            && had.bonus === (v.waterBonus || 0)) continue;
        tanks[v.typeId] = { water: v.water || 0, foam: v.foam || 0, bonus: v.waterBonus || 0 };
        changed = true;
    }
    if (changed) {
        try { localStorage.setItem(MM_TANKS_KEY, JSON.stringify(tanks)); } catch (e) { /* private */ }
    }
    /* What was just learnt over what the repo shipped: a type this game has
     * never put in a selection table still answers from the file. */
    return mmKnownTanks();
}

function mmLearnTypes(vehicles) {
    let learnt = {};
    try {
        learnt = JSON.parse(localStorage.getItem(MM_TYPES_KEY)) || {};
    } catch (e) { /* nothing learnt yet */ }

    let changed = false;
    for (const v of vehicles) {
        if (!v.typeId) continue;
        const had = learnt[v.typeId];
        const caps = v.flags;
        // Older stores kept a bare array of flags; keep reading those.
        const before = Array.isArray(had) ? { caps: had, name: null } : had;
        if (before && before.name && before.caps.join('|') === caps.join('|')) continue;
        learnt[v.typeId] = { caps, name: v.typeName || before?.name || null };
        changed = true;
    }
    if (changed) {
        try { localStorage.setItem(MM_TYPES_KEY, JSON.stringify(learnt)); } catch (e) { /* private window */ }
    }
    return mmKnownTypes();
}

/** What has been learnt, with its names, for handing back. */
function mmLearntTypes() {
    try {
        const raw = JSON.parse(localStorage.getItem(MM_TYPES_KEY)) || {};
        return Object.fromEntries(Object.entries(raw).map(([id, t]) =>
            [id, Array.isArray(t) ? { caps: t, name: null } : t]));
    } catch (e) {
        return {};
    }
}


/* ------------------------------------- the crew, now that the game states it */

/**
 * COUNTING THE CREW WAS TRIED, WITHDRAWN — AND THE GAME HAS SINCE STATED IT.
 *
 * What was withdrawn was counting `Max. Crew` off the buy page: that is a cap
 * somebody set, so seats are not people, and the conclusion written down here
 * was that "nothing in a mission window says who is aboard". That is no longer
 * true, and the correction matters more than the original reading:
 *
 *   - the at-mission and driving tables carry a **Crew** column, stated per
 *     vehicle — `<td sortvalue="3">3</td>` against a row whose link carries
 *     `vehicle_type_id="5"`, which is the two facts meeting in one row;
 *   - the window states the shortfall itself, as
 *     `<div data-requirement-type="personnel"><b>Missing Personnel:</b>
 *     14 Firefighters</div>`.
 *
 * So crew is measured now, not asked for and not inferred: a type is learnt the
 * first time one of its vehicles is seen at a mission, exactly as tanks are.
 *
 * WHICH CELL IS THE CREW IS ASKED OF THE HEADER, not counted to. The heading is
 * an icon — `icons8-groups_dark.svg` — and the game's own asset name is the
 * same in every language it is played in, where the tooltip beside it is not.
 */
const MM_CREW_SEEN_KEY = 'ymca-missionmagician-crew-seen';

function mmCrewColumn(table) {
    const cell = table?.querySelector('thead img[src*="group"]')?.closest('th, td');
    return cell ? cell.cellIndex : -1;
}

function mmStoredCrew() {
    try {
        return JSON.parse(localStorage.getItem(MM_CREW_SEEN_KEY)) || {};
    } catch (e) { return {}; }
}

/** Shipped seats first, what this game stated over the top. See mmKnownTanks. */
function mmKnownCrew() {
    const crew = {};
    for (const [id, t] of Object.entries(MM_SHIPPED_TYPES)) {
        if (t.crewSeen > 0) crew[id] = t.crewSeen;
    }
    return { ...crew, ...mmStoredCrew() };
}

function mmWriteCrew(crew) {
    try { localStorage.setItem(MM_CREW_SEEN_KEY, JSON.stringify(crew)); } catch (e) { /* private */ }
}

/**
 * How many more the game says it wants, and what it calls them.
 *
 * `Missing Personnel: 14 Firefighters` is a SHORTFALL, the way the missing
 * vehicles line is: the game has already taken off whoever is at the mission
 * and whoever is on the way. So nothing here is subtracted a second time.
 */
function mmPersonnelWanted() {
    const el = document.querySelector('[data-requirement-type="personnel"]');
    if (!el) return null;
    const said = (el.textContent || '').replace(/\s+/g, ' ').trim();
    const m = /(\d+)/.exec(said);
    if (!m) return null;
    const after = said.slice(said.indexOf(m[0]) + m[0].length).trim();
    return { wanted: Number(m[1]), label: after || 'crew' };
}

/**
 * Vehicles already at the mission or on their way to it.
 *
 * They meet a requirement just as much as one you are about to send, so not
 * subtracting them was the difference between "needs 4 engines" and "needs 4
 * more engines" — and only the second is true once anything has been sent.
 */
function mmOnScene(known, countDriving = true) {
    /* AT THE MISSION AND ON THE WAY ARE COUNTED SEPARATELY, because they are
     * not equally certain. One that has arrived is there; one that is driving
     * can still be recalled — the game puts a backalarm button on its very row
     * — and on an alliance call it may not even be yours. Both meet the
     * requirement, so both count by default, and the panel says which is which
     * so "why does it want one fewer than I do" has an answer on screen. */
    /* A ROW WITH NO READABLE TYPE USED TO VANISH. `continue` came before the
     * counting, so a vehicle whose row does not carry `vehicle_type_id` was not
     * at the mission, not unknown, and not mentioned — it simply was not there,
     * and the panel asked for one more than it needed to. It is counted as
     * present and unreadable now, and said on screen.
     *
     * The rows are taken by the id prefix OR by carrying a type id, because
     * which of the two a row answers to is the game's business, not ours. */
    const rowsIn = (id) => {
        const table = document.getElementById(id);
        if (!table) return [];
        return [...table.querySelectorAll('tbody tr')].filter((tr) =>
            /^vehicle_row/.test(tr.id || '') || tr.querySelector('[vehicle_type_id]'));
    };
    const at = rowsIn('mission_vehicle_at_mission');
    const driving = rowsIn('mission_vehicle_driving');

    const counts = {};
    const vehicles = [];
    const typeIds = [];
    /* THE ROW STATES ITS OWN CREW, so the people already committed to this call
     * are a reading rather than a lookup. Kept per vehicle with its flags, so a
     * training can be asked of the vehicle carrying them. */
    const onScene = [];
    let unknown = 0;
    let unreadable = 0;
    let total = 0;
    /* The crew column is per table, so it is asked once per table rather than
     * once per row. A table that does not carry one simply teaches nothing. */
    const crewColumn = new Map();
    const crew = mmKnownCrew();
    /* What this game has stated, kept apart from what the repo shipped: only
     * the first is written back, so a repo figure is never frozen into a
     * browser where a later read could not correct it. */
    const crewSeenHere = mmStoredCrew();
    let learntCrew = false;
    /* WHICH TABLE A ROW IS IN IS ITS STATUS. The game puts a vehicle that has
     * arrived in `mission_vehicle_at_mission` and one still driving in
     * `mission_vehicle_driving`, and says the same on the row itself —
     * `building_list_fms_4` against `building_list_fms_3`. The two are not
     * interchangeable where crew is concerned, which is the whole of the fix
     * in the personnel line. */
    const take = (rows, arrived) => {
        for (const row of rows) {
            total += 1;
            const typeId = row.querySelector('[vehicle_type_id]')?.getAttribute('vehicle_type_id');
            if (!typeId) { unreadable += 1; unknown += 1; continue; }
            /* THE ROW IS WHERE THE TYPE AND THE CREW MEET. Nowhere else states
             * both, which is why this is the only place a type's crew can be
             * measured rather than guessed at. */
            const table = row.closest('table');
            if (table && !crewColumn.has(table)) crewColumn.set(table, mmCrewColumn(table));
            const at = table ? crewColumn.get(table) : -1;
            let seats = 0;
            if (at >= 0) {
                const said = Number((row.cells[at]?.textContent || '').trim());
                if (Number.isFinite(said) && said > 0) {
                    seats = said;
                    if (crewSeenHere[typeId] !== said) {
                        crew[typeId] = said;
                        crewSeenHere[typeId] = said;
                        learntCrew = true;
                    }
                }
            }
            typeIds.push(Number(typeId));
            const flags = known[typeId];
            /* Counted as present whatever else is unknown: the seats are on the
             * row, and a type nothing has flags for still carries its people. */
            onScene.push({ typeId, seats: seats || crew[typeId] || 0, flags: flags || [], arrived });
            if (!flags) { unknown += 1; continue; }
            vehicles.push(flags);
            for (const flag of flags) counts[flag] = (counts[flag] || 0) + 1;
        }
        return rows.length;
    };
    const atCount = take(at, true);
    const drivingCount = countDriving ? take(driving, false) : 0;
    /* Counted or not, how many are on the way is worth saying. */
    const drivingSeen = driving.length;
    if (learntCrew) mmWriteCrew(crewSeenHere);
    return {
        counts, vehicles, unknown, unreadable, total, typeIds, onScene,
        atCount, drivingCount, drivingSeen, countDriving, crew,
    };
}

/**
 * Read a mission's requirements off the game's own requirements page.
 *
 * `/einsaetze.json` only lists missions this player can generate. An alliance
 * mission started from somebody else's building is not in it, and neither is
 * anything the account has not unlocked — so the catalogue answered "unknown"
 * for exactly the missions worth helping with.
 *
 * Every mission window links to the answer itself: `#mission_help` points at
 * /einsaetze/<type>, which is a plain table of "Required Firetrucks | 5". The
 * labels turn into the keys /einsaetze.json already uses by lowercasing and
 * joining with underscores — "Required Platform Trucks" is `platform_trucks` —
 * so this is the same vocabulary read from a second place, not a second
 * vocabulary. A label that does not turn into a key YMCA knows is carried into
 * the report rather than dropped.
 */
async function mmMissionHelp(typeId, href) {
    const url = href || `/einsaetze/${encodeURIComponent(typeId)}`;
    const res = await fetch(url, { credentials: 'same-origin' });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const doc = new DOMParser().parseFromString(await res.text(), 'text/html');

    const requirements = {};
    const unread = [];
    let name = null;
    let credits = null;
    let patients = 0;

    const heading = doc.querySelector('h1, h2, .page-header');
    if (heading) name = heading.textContent.trim().split('\n')[0].trim() || null;

    for (const row of doc.querySelectorAll('table tr')) {
        const cells = row.querySelectorAll('td, th');
        if (cells.length < 2) continue;
        const label = cells[0].textContent.trim();
        const value = Number(cells[1].textContent.replace(/[^\d-]/g, ''));
        if (!label || !Number.isFinite(value)) continue;

        if (/^average credits$/i.test(label)) { credits = value; continue; }
        if (/^max\.?\s*patients$/i.test(label)) { patients = value; continue; }

        /* Only the vehicle lines. "Required Fire Stations" is a prerequisite for
         * generating the mission, not something to send, and the two read alike
         * — so stations are named out rather than filtered by guesswork. */
        const m = /^required\s+(.+)$/i.exec(label);
        if (!m) continue;
        const key = m[1].trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/_+$/, '');
        if (/_stations?$/.test(key) || key === 'foam_extensions') continue;
        if (MM_REQUIREMENTS[key]) requirements[key] = value;
        else { requirements[key] = value; unread.push(key); }
    }

    return { name, requirements, average_credits: credits, patients, unread, fromHelpPage: true };
}

/** Only what the panel reads, so the stored catalogue is a fraction of the original. */
function mmShrinkCatalogue(data) {
    const list = Array.isArray(data) ? data : Object.values(data);
    const byId = {};
    for (const m of list) {
        byId[String(m.id)] = {
            name: m.name,
            requirements: m.requirements || {},
            average_credits: m.average_credits || null,
            /* Two things live under `additional` rather than in `requirements`:
             * the patients, and the English names for the crew training the
             * requirement asks for in the game's internal spelling. */
            additional: (m.additional?.possible_patient || m.additional?.personnel_educations)
                ? {
                    possible_patient: m.additional.possible_patient,
                    personnel_educations: m.additional.personnel_educations,
                }
                : undefined,
        };
    }
    return byId;
}


YMCA.register({
    id: 'missionmagician',
    title: 'MissionMagician',
    tagline: 'Pick the right vehicles',
    /* Switchable from ElementFriend, and on until somebody says otherwise: it
     * shipped before the switchboard existed. */
    optional: true,

    description: 'Reads what a mission needs and ticks the vehicles that match. '
        + 'It never dispatches — you press the game\'s own button.',

    /* ElementFriend opens this: the crew numbers the game cannot be read for. */
    settings: mmSettings,

    async mount(el, ctx) {
        const cfg = ctx.store.read('cfg', { fastestFirst: true });
        const page = mmReadMissionPage();

        if (!page.onMissionPage) {
            el.innerHTML = mmOffMissionHtml();
            mmWireCapture(el, ctx);
            return;
        }

        const plan = await mmPlan(page, ctx, cfg);
        el.innerHTML = mmPlanHtml(plan, page, cfg, ctx);

        el.addEventListener('change', (e) => {
            const key = e.target.dataset.cfg;
            if (!key) return;
            cfg[key] = e.target.checked;
            ctx.store.write('cfg', cfg);
            ctx.open('missionmagician');
        });

        el.addEventListener('click', (e) => {
            if (e.target.closest('[data-do="select"]')) {
                const n = mmSelect(plan.pick);
                ctx.status(`Ticked ${n} vehicles — now press the game's own Dispatch.`);
                ctx.log.info('ticked vehicles', `${n} for mission type ${page.missionType}`);
                el.querySelector('#mm-done').hidden = false;
            } else if (e.target.closest('[data-do="clear"]')) {
                const n = mmClear();
                ctx.status(`Unticked ${n}.`);
                el.querySelector('#mm-done').hidden = true;
            }
        });
    },
});

/* ---------------------------------------------------------- reading the page */

/** What this page is and what it offers, without reading a word of its text. */
function mmReadMissionPage(withFollowUp) {
    const info = document.getElementById('mission_general_info');
    const form = document.getElementById('mission-form');
    const body = document.getElementById('vehicle_show_table_body_all');
    const rows = body ? [...body.querySelectorAll('.vehicle_select_table_tr')] : [];

    /* Follow-up holds vehicles that are already out on another mission and can
     * be redirected to this one. The game loads that tab only when it is
     * opened, so opening it is what makes the rows exist — and it is the game's
     * own tab doing the game's own fetch, not a request built here. */
    let followUp = [];
    if (withFollowUp) {
        followUp = [...document.querySelectorAll(
            '#vehicle_show_table_body_occupied .vehicle_select_table_tr, '
            + '#occupied .vehicle_select_table_tr')];
        if (!followUp.length) document.querySelector('#tabs a[tabload="occupied"]')?.click();
    }

    return {
        onMissionPage: !!(info && form && body),
        inFrame: window.top !== window.self,
        // The type id, which is the key into /einsaetze.json. Not the title.
        missionType: info?.getAttribute('data-mission-type') || null,
        helpHref: document.getElementById('mission_help')?.getAttribute('href')
            || document.getElementById('mission-type-helper-mobile')?.getAttribute('href') || null,
        rows,
        followUpRows: followUp,
        followUpOffered: !!document.querySelector('#tabs a[tabload="occupied"]'),
    };
}

/** A vehicle, described by the attributes the game put on its own checkbox. */
function mmVehicle(row) {
    const box = row.querySelector('.vehicle_checkbox');
    if (!box) return null;
    const num = (name) => {
        const v = box.getAttribute(name);
        return v === null || v === '' ? 0 : Number(v) || 0;
    };
    /* THE TYPE ID IS READ AS THE GAME WROTE IT, NEVER AS A NUMBER, because
     * `Type 1 fire engine` is type **0** and zero is falsy. Read as a number it
     * was indistinguishable from "this row states no type", so every guard
     * spelled `if (!v.typeId) continue` threw the commonest engine in the game
     * away: its flags were never learnt from a selection table, its tank was
     * never learnt, and a vehicle of that type at a mission stayed an unknown
     * type for ever, however many times one was in range.
     *
     * A string keeps the two apart: `'0'` is a type and `null` is no type. It
     * indexes every store exactly as it did, because an object key is a string
     * either way. */
    const attr = (name) => {
        const v = box.getAttribute(name);
        return v === null || v === '' ? null : v;
    };
    /* The travel time, not the distance. The game prints it into the fourth cell
     * as `timevalue` in seconds once it has worked the route out, and it is the
     * only honest ordering: a vehicle whose dot sits closer on the map can still
     * arrive later, which is exactly what "fastest vehicle" got wrong. Until the
     * game has filled it in the row falls back to distance, and the panel says
     * when it is doing that. */
    const timed = row.querySelector('[timevalue]');
    const seconds = timed ? Number(timed.getAttribute('timevalue')) : NaN;
    return {
        box,
        id: box.value,
        typeId: attr('vehicle_type_id'),
        /* The row says what the type is called and the checkbox says which id it
         * is, on the same row — the only place in the game the two appear
         * together. Everything else has to be told. */
        typeName: row.getAttribute('vehicle_type') || null,
        seconds: Number.isFinite(seconds) ? seconds : null,
        distance: Number(row.getAttribute('data-distance')) || 0,
        water: num('wasser_amount'),
        foam: num('foam_amount_display'),
        /* A TANKER MULTIPLIES WHAT IS THERE, AND THE GAME SAYS BY HOW MUCH.
         * `water_modifier_raw` sits on the same checkbox as `wasser_amount` —
         * 25 on a Water Tanker and on a Pumper Tanker — and the game's own
         * `calculateWaterBar` sums it across the ticked boxes into
         * `water_total_modifier` beside the plain total. So the bonus is read,
         * not a number anybody here worked out. */
        waterBonus: num('water_modifier_raw') || num('water_modifier'),
        /* Everything the game flagged, so a requirement nothing here maps can
         * still be answered from the page's own vocabulary. */
        flags: mmFlagsOn(box),
        has: (flag) => box.getAttribute(flag) === '1',
    };
}

/** Seconds where the game has them, distance as a stand-in where it has not. */
function mmOrder(a, b) {
    if (a.seconds !== null && b.seconds !== null) return a.seconds - b.seconds;
    if (a.seconds !== null) return -1;
    if (b.seconds !== null) return 1;
    return a.distance - b.distance;
}

/* -------------------------------------------------------------- the planning */

/**
 * What this mission needs, and which of the vehicles on screen meet it.
 *
 * The need comes from /einsaetze.json — the game's own list — so the window
 * only has to answer "what is available", which is the one thing the list
 * cannot know.
 */
/**
 * Choose the fewest vehicles that cover everything, without spending the
 * versatile ones on work an ordinary vehicle could do.
 *
 * A Quint is flagged `fire` and `dlk`, a Rescue Engine `fire` and `rw`. Both
 * are worth two requirements at once, and both are scarce; an ordinary pumper
 * is worth one and there are plenty. Filling requirements one at a time in any
 * order gets this wrong in one direction or the other — nearest-first sends
 * Quints as plain engines and empties the ladders, scarcest-first stops as soon
 * as each line is met without asking whether a different vehicle would have
 * done.
 *
 * So the choice is made per vehicle rather than per requirement, and the
 * ordering of the reasons is the whole design:
 *
 *  1. **How much it still covers.** A vehicle answering two outstanding
 *     requirements beats one answering a single requirement, which is what
 *     keeps the total down.
 *  2. **How little else it could have done**, judged on everything it can do
 *     rather than on what this mission asks — a Quint is worth keeping back on
 *     a mission with no ladder line at all, because the next one has one.
 *  3. **How many of its kind are left**, recounted every round, and then **how
 *     often that kind has already been drawn on**. Between two equally useful
 *     kinds these two take turns rather than emptying one of them.
 *  4. **How fast it gets there.** Only once nothing above separates them —
 *     which is why a nearer Quint still stays behind a further pumper.
 */
function mmAllocate(needs, vehicles) {
    const outstanding = new Map(needs.map((n) => [n.key, Math.max(0, n.wanted - n.onScene)]));
    const coversOf = new Map(vehicles.map((v) =>
        [v.id, needs.filter((n) => mmMeets(v, n.rule)).map((n) => n.key)]));
    /* What a vehicle can do in general, not only what this mission happens to
     * ask for. A Quint is worth keeping back even on a mission with no ladder
     * line at all, because the next one will have one. Judging versatility
     * against this mission's needs alone makes a Quint and a pumper look
     * identical, and then the nearer Quint goes.
     *
     * Judged on the flags a requirement can ask for — the ones named above plus
     * whatever this mission's own requirements turned out to want. Not every
     * attribute on the checkbox: the game also writes composites like
     * `road_rescue_or_fire_engine`, and counting those would rank a vehicle by
     * how many ways the game has of describing it. */
    const judged = new Set([...MM_NAMED_FLAGS,
        ...needs.flatMap((n) => n.rule.anyOf || [n.rule.flag])]);
    const capsOf = new Map(vehicles.map((v) =>
        [v.id, [...judged].filter((f) => v.has(f))]));
    const kindOf = (v) => capsOf.get(v.id).join('|');

    const picked = [];
    const taken = new Set();
    const takenOfKind = new Map();

    while ([...outstanding.values()].some((n) => n > 0)) {
        /* Recounted each round: what is left of each kind decides the balance,
         * not what there was to begin with. */
        const left = new Map();
        for (const v of vehicles) {
            if (taken.has(v.id)) continue;
            left.set(kindOf(v), (left.get(kindOf(v)) || 0) + 1);
        }

        let best = null;
        for (const v of vehicles) {
            if (taken.has(v.id)) continue;
            const covers = coversOf.get(v.id);
            const gain = covers.filter((k) => outstanding.get(k) > 0).length;
            if (!gain) continue;
            const score = [
                -gain,                                  // most outstanding work first
                capsOf.get(v.id).length,                // least able to do anything else
                -(left.get(kindOf(v)) || 0),            // commonest kind of those left
                takenOfKind.get(kindOf(v)) || 0,        // then the kind least drawn on so far
                v.seconds === null ? Infinity : v.seconds,
            ];
            if (!best || mmLess(score, best.score)) best = { v, covers, score };
        }
        if (!best) break;                                // nothing left that helps

        taken.add(best.v.id);
        takenOfKind.set(kindOf(best.v), (takenOfKind.get(kindOf(best.v)) || 0) + 1);
        picked.push(best.v);
        for (const k of best.covers) outstanding.set(k, Math.max(0, outstanding.get(k) - 1));
    }
    return picked;
}

/** First difference wins, so the reasons above are strictly in order. */
function mmLess(a, b) {
    for (let i = 0; i < a.length; i += 1) {
        if (a[i] !== b[i]) return a[i] < b[i];
    }
    return false;
}

async function mmPlan(page, ctx, cfg) {
    let requirements = null;
    let name = null;
    let record = null;
    try {
        /* Kept across page loads. Every mission window is its own load, so the
         * whole catalogue was being refetched each time one opened. */
        const byId = await ctx.gameCached('/einsaetze.json', MM_CATALOGUE_MS, mmShrinkCatalogue);
        record = byId[String(page.missionType)] || null;
        if (record) {
            requirements = record.requirements || {};
            name = record.name;
        }
    } catch (err) {
        ctx.log.warn('could not read the mission list', err.message);
    }

    /* Not in the catalogue: an alliance mission from somebody else's building,
     * or one this account cannot generate. The window links to the answer, so
     * ask it. Kept per type, because it is the same answer every time. */
    if (!record && page.missionType) {
        const key = `mm-help-${page.missionType}`;
        record = ctx.store.read(key, null);
        if (!record) {
            try {
                record = await mmMissionHelp(page.missionType, page.helpHref);
                ctx.store.write(key, record);
                ctx.log.info('read requirements from the mission help page',
                    `type ${page.missionType}${record.unread.length
                        ? `, ${record.unread.length} labels unrecognised` : ''}`);
            } catch (err) {
                ctx.log.warn('mission help page unreadable', err.message);
            }
        }
        if (record) {
            requirements = record.requirements || {};
            name = record.name;
            if (record.unread) for (const k of record.unread) mmRememberUnmatched(k, page.missionType);
        }
    }

    /* The window names the mission itself — `missionH<id>` in its own header —
     * which is the only name there is for a mission the catalogue has not got
     * and whose help page would not load. */
    if (!name) {
        name = document.querySelector('[id^="missionH"]')?.textContent
            .replace(/\s+/g, ' ').trim() || null;
    }

    const free = page.rows.map(mmVehicle).filter(Boolean);
    /* A follow-up vehicle is already committed somewhere else, so it goes behind
     * every free one however fast it is — taking it costs another mission. */
    const busy = page.followUpRows.map(mmVehicle).filter(Boolean).map((v) =>
        Object.assign(v, { followUp: true }));
    if (cfg.fastestFirst !== false) { free.sort(mmOrder); busy.sort(mmOrder); }
    const vehicles = free.concat(busy);
    const untimed = vehicles.filter((v) => v.seconds === null).length;
    mmFromWindow.clear();
    mmAddedHere.clear();
    const scene = mmOnScene(mmLearnTypes(vehicles), cfg.countDriving !== false);
    const tanks = mmLearnTanks(vehicles);
    /* What is already at the mission or on its way is carrying water too. */
    const sceneCarries = (which) => scene.typeIds
        .reduce((n, id) => n + (tanks[id] ? tanks[id][which] : 0), 0);
    scene.unknownTank = scene.typeIds.filter((id) => !tanks[id]).length;
    const patients = mmPatients(record);

    const picked = new Map();
    const lines = [];
    let plannedCrewUnknown = 0;
    let plannedCrewUntrained = false;

    if (requirements) {
        /* A requirement whose value is not a number is not a count of vehicles.
         * `personnel_educations: { gw_gefahrgut: 8 }` asks for eight trained
         * crew at the mission — carried by whatever is sent, not sent itself —
         * and as a row it read "Personnel educations, wanted [object Object]". */
        const wants = Object.entries(requirements)
            .filter(([key, n]) => !MM_AMOUNTS[key] && typeof n === 'number')
            // [key, how many, is that a shortfall rather than a total]
            .map(([key, n]) => [key, n, false]);
        /* Patients are not a requirement key. They want ambulances, so they are
         * counted into the ambulance line rather than shown beside it — one each
         * unless told otherwise. An `ambulances` requirement and the patients
         * are the same ambulances, so the larger of the two stands. */
        if (patients && patients.measured) {
            const perPatient = cfg.ambulancePerPatient === false ? 1 : patients.count;
            const existing = wants.find(([key]) => key === 'ambulances');
            if (existing) existing[1] = Math.max(existing[1], perPatient);
            else wants.push(['patients', perPatient, patients.total === false]);
        }

        /* What the game's own words can answer. Every flag on every checkbox in
         * this table, and every flag learnt from any table before it: a HazMat
         * out of range today still taught `hazmat` the day it was in one, and a
         * requirement is no less real for the vehicle being busy. */
        const vocab = new Set(vehicles.flatMap((v) => v.flags));
        for (const caps of Object.values(mmKnownTypes())) for (const f of caps) vocab.add(f);

        /* And whatever the window says is still missing that the catalogue
         * never mentioned — a skateboard accident wants an ambulance, lists
         * none and produces no patient. What the game is asking for out loud
         * is not something to argue with. */
        for (const { key, wanted } of mmMissingFromWindow()) {
            const found = mmRuleFor(key, vocab);
            if (!found) continue;
            if (wants.some(([k]) => k === found.key)) continue;
            if (found.key === 'patients' || MM_AMOUNTS[found.key]) continue;
            wants.push([found.key, wanted, true]);
            mmFromWindow.add(found.key);
        }

        /* And the one thing no page of the game states at all. It is added only
         * where nothing has already asked for it, so a game that starts listing
         * it — or a patient that finally spawns — makes this a no-op rather than
         * a second ambulance. */
        for (const add of mmAddedFor(name, page.missionType)) {
            if (wants.some(([k]) => k === add.key)) continue;
            if (add.key === 'ambulances' && wants.some(([k]) => k === 'patients')) continue;
            wants.push([add.key, add.wanted, false]);
            mmAddedHere.set(add.key, add.source);
        }

        const needs = [];
        for (const [key, wanted, isShortfall] of wants) {
            let rule = MM_REQUIREMENTS[key];
            if (!rule) {
                const found = mmDeriveRule(key, vocab);
                if (found) {
                    const label = mmPretty(key);
                    rule = {
                        ...found, label, icon: mmIconFor(key, label),
                        source: `the game flags ${found.derived} on the vehicles that answer it`,
                    };
                }
            }
            if (!rule) {
                /* Two silences that used to read the same. The game naming
                 * the capability means the fleet is short of one, not that
                 * YMCA is short of a rule. */
                const known = mmGameKnowsFlag(key);
                lines.push({
                    key, label: mmPretty(key), wanted, found: null, unmatched: true,
                    gameFlag: known,
                });
                mmRememberUnmatched(key, page.missionType);
                mmPublishMappedFlags();
                continue;
            }
            const onScene = mmSceneCount(scene, rule);
            /* A shortfall is counted on top of what is there; a total has what
             * is there counted against it. */
            needs.push({ key, rule, wanted: isShortfall ? wanted + onScene : wanted, onScene });
        }

        for (const v of mmAllocate(needs, vehicles)) picked.set(v.id, v);

        /* `found` starts at what is committed — at the mission or on the way.
         * What the plan *would* send covers nothing; it counts once the boxes
         * are ticked, and mmRecount takes it from there. */
        for (const n of needs) {
            lines.push({
                key: n.key, label: n.rule.label, icon: n.rule.icon, wanted: n.wanted,
                rule: n.rule, onScene: n.onScene, found: n.onScene,
                derived: n.rule.derived || null,
                fromWindow: mmFromWindow.has(n.key),
                addedHere: mmAddedHere.get(n.key) || null,
            });
        }

        /* Water and foam are totals, so they are filled by adding vehicles until
         * the figure is reached — the ones already picked may carry some. */
        for (const [key, rule] of Object.entries(MM_AMOUNTS)) {
            const wanted = requirements[key];
            if (!wanted) continue;
            const which = key === 'water_needed' ? 'water' : 'foam';
            const carried = (v) => v[which];

            /* A TANKER MULTIPLIES WHAT IS THERE, AND ADDING THE LOADS UP IGNORED
             * IT — which is why the panel sent three times the water asked for.
             *
             * The game writes `water_modifier_raw` on a tanker's own checkbox —
             * 25 on a Water Tanker and on a Pumper Tanker, absent on a Quint —
             * and its own `calculateWaterBar` sums those across the ticked boxes
             * into `water_total_modifier` beside the plain total. So the bonus
             * is the game's own field, applied the way the game's own code adds
             * it up: the loads are totalled and the percentages raise the lot.
             *
             * That is why WATER TANKERS FILL A FIRE FIRST without being named:
             * a tanker carries a big load *and* lifts everything already there,
             * so its gain outgrows any engine's the moment anything is on
             * scene. Foam carries no such field, so foam is a plain sum.
             *
             * THE GAME'S OWN BAR IS NOT THE MEASURE. It counts what is actually
             * available, not what the call is short of, so nothing here is
             * calibrated against it. */
            const bonusOf = (v) => (which === 'water' ? v.waterBonus || 0 : 0);
            const sceneBonus = which === 'water'
                ? scene.typeIds.reduce((n, id) => n + (tanks[id]?.bonus || 0), 0) : 0;
            const onScene = sceneCarries(which);

            let base = onScene;
            let bonus = sceneBonus;
            for (const v of picked.values()) { base += carried(v); bonus += bonusOf(v); }
            const effective = (b, m) => Math.round(b * (1 + m / 100));
            /* What adding this one would really be worth, at this moment: its
             * own load raised by every percentage already committed, plus its
             * own percentage raising everything already there. */
            const gain = (v) => effective(base + carried(v), bonus + bonusOf(v))
                - effective(base, bonus);

            /* THE BIGGEST THAT STILL FITS — WHILE IT IS ACTUALLY FILLING THE
             * GAP — AND OTHERWISE THE SMALLEST THAT FINISHES IT.
             *
             * Four wrong answers got here. Filling in arrival order sent
             * whatever happened to be close, and what is close is engines.
             * Biggest-first overshot the other way — a fire wanting 20,000 took
             * the one tanker carrying 30,000. So: how little is wasted, not how
             * few are sent.
             *
             * Then "the smallest" turned out to mean the smallest of the whole
             * pool rather than the smallest that finishes, which dribbled
             * fifty-gallon brush trucks in one at a time.
             *
             * AND A VEHICLE THAT FITS IS NOT THEREFORE WORTH SENDING. Once the
             * tankers are on, what is left is small and every engine in the
             * fleet fits it — five of them went where one more tanker would
             * have done, which is the nine-appliance send that was complained
             * about. A vehicle covering less than half of what is left is not
             * filling the gap, so where one vehicle can finish the job instead,
             * that one goes. Not at any price: a finisher worth more than twice
             * what is left is its own kind of waste, and then the fitting one
             * goes after all. */
            const pool = vehicles.filter((v) => carried(v) && !picked.has(v.id));
            while (effective(base, bonus) < wanted && pool.length) {
                const remaining = wanted - effective(base, bonus);
                const scored = pool.map((v) => ({ v, gain: gain(v) }))
                    .filter((g) => g.gain > 0);
                if (!scored.length) break;
                const fits = scored.filter((g) => g.gain <= remaining)
                    .sort((a, b) => b.gain - a.gain || mmOrder(a.v, b.v))[0];
                const finishes = scored.filter((g) => g.gain >= remaining)
                    .sort((a, b) => a.gain - b.gain || mmOrder(a.v, b.v))[0];
                let choice;
                if (fits && fits.gain >= remaining / 2) choice = fits;
                else if (finishes && finishes.gain <= remaining * 2) choice = finishes;
                else choice = fits || finishes
                    || scored.sort((a, b) => b.gain - a.gain || mmOrder(a.v, b.v))[0];
                const next = choice.v;
                pool.splice(pool.indexOf(next), 1);
                picked.set(next.id, next);
                base += carried(next);
                bonus += bonusOf(next);
            }
            lines.push({
                key, label: rule.label, icon: rule.icon, wanted,
                found: effective(onScene, sceneBonus), unit: rule.unit, carries: key,
                onScene: effective(onScene, sceneBonus),
                sceneBase: onScene, sceneBonus,
            });
        }

        /* CREW IS A TOTAL FILLED BY ADDING VEHICLES, exactly as water is — the
         * people arrive on whatever is sent, so the only way to cover a
         * shortfall of fourteen is to keep sending until fourteen seats have
         * gone. The figure per type is measured off the game's own Crew column
         * the first time one is seen at a mission.
         *
         * IT IS A SHORTFALL, and it was read as a bigger one than it is. The
         * note here used to say the game had already taken off whoever was at
         * the mission and whoever was driving, so `onScene` was nought on
         * purpose. A real window disproved it — see the count below.
         *
         * A type whose crew has never been seen carries nothing here rather
         * than a guess, and the panel says how many of those it picked. */
        const personnel = mmPersonnelWanted();
        if (personnel) {
            const crew = scene.crew || mmKnownCrew();
            /* A TRAINING IS NOT SEATS, and filling it with seats was wrong.
             *
             * `Missing Personnel` on a HazMat call is a shortfall of people who
             * hold that training, and the mission names which one:
             * `personnel_educations: { gw_gefahrgut: 1 }`. Any vehicle with a
             * seat in it will satisfy a count of seats, which is how an
             * ambulance got sent to a call that wanted a HazMat crew.
             *
             * So where the mission names a training, only the vehicles the game
             * flags for that training are candidates. The flag is derived from
             * the key against the vocabulary the page itself carries —
             * `gw_gefahrgut` finds `gwgefahrgut` — so nothing is invented.
             *
             * WHAT IS STILL NOT CLAIMED is that the people aboard a HazMat hold
             * the HazMat training. No page says that. What is claimed is the
             * other way round: a vehicle the game does not flag for the
             * training cannot be the one that brings it, so it is not picked.
             * Where nothing in range carries the flag, **nothing is picked** and
             * the panel says so — sending the wrong vehicle is worse than
             * sending none. */
            const trainings = Object.keys(record?.requirements?.personnel_educations || {});
            let trained = null;
            for (const key of trainings) {
                const found = mmRuleFor(key, vocab);
                if (found) { trained = found.rule; break; }
            }
            const fits = (v) => !trained || mmMeets(v, trained);
            const carried = (v) => (fits(v) ? crew[v.typeId] || 0 : 0);

            /* THE BANNER IS WHAT IS MISSING, AND MISSING IS NET OF WHO ARRIVED.
             *
             * Two readings got here and both were wrong, in opposite
             * directions. The first counted nobody already committed, so a call
             * with three HazMats — one there, two driving — asked for a fourth
             * for ever. The second counted everybody committed, which took the
             * crew *at the mission* off a figure the game had already taken
             * them off, and then asked for too few.
             *
             * The player's own formula settles it, and it is the game's
             * arithmetic rather than anything worked out here:
             *
             *     total wanted = the banner + the trained crew that has arrived
             *     covered      = arrived + on the way
             *     still to send = the banner − on the way
             *
             * `Missing Personnel` counts against what has **arrived** and
             * nothing else — a vehicle in status 3 changes it only once it
             * becomes status 4. So the arrived crew is added back to make the
             * total honest on screen, and only the crew on the way comes off
             * what is still to send.
             *
             * Only crew on a vehicle the game flags for the training counts
             * either way. That is the player's reading of their own game: only
             * somebody holding the training can board the vehicle that needs
             * it, so the nine seats on an ambulance beside a HazMat are not
             * the people this call is short of. */
            const seatsOn = (arrived) => (scene.onScene || []).reduce(
                (n, v) => (v.arrived === arrived
                    && fits({ has: (f) => v.flags.includes(f) }) ? n + v.seats : n), 0);
            const arrivedCrew = seatsOn(true);
            const committed = arrivedCrew + seatsOn(false);
            const wantedTotal = personnel.wanted + arrivedCrew;
            let have = committed
                + [...picked.values()].reduce((n, v) => n + carried(v), 0);
            const bySmallest = (a, b) => carried(a) - carried(b) || mmOrder(a, b);
            const byBiggest = (a, b) => carried(b) - carried(a) || mmOrder(a, b);
            const pool = vehicles.filter((v) => carried(v) && !picked.has(v.id));
            /* Nothing in range that could bring the training. Said plainly,
             * rather than filled with whatever had a seat. */
            plannedCrewUntrained = !!trained && !pool.length && have < wantedTotal;
            while (have < wantedTotal && pool.length) {
                const left = wantedTotal - have;
                const fits = pool.filter((v) => carried(v) <= left);
                const next = fits.length
                    ? fits.sort(byBiggest)[0]
                    : pool.slice().sort(bySmallest)[0];
                pool.splice(pool.indexOf(next), 1);
                picked.set(next.id, next);
                have += carried(next);
            }
            const named = (mmCrewTraining(record) || [])[0];
            lines.push({
                key: 'personnel',
                label: `Crew \u2014 ${trained && named ? named.label : personnel.label}`,
                icon: 'star',
                wanted: wantedTotal,
                found: 0,
                unit: 'crew',
                carries: 'personnel',
                onScene: committed,
                fromWindow: true,
            });
            /* How many of the picked vehicles have never had their crew stated,
             * so a line that cannot fill says why rather than looking stuck. */
            plannedCrewUnknown = [...picked.values()].filter((v) => v.typeId && !crew[v.typeId]).length;
        }

        // Counts first, then the totals, so the table reads the way the game states it.
        lines.sort((a, b) => Number(!!a.unit) - Number(!!b.unit));
    }

    return {
        crewUnknown: plannedCrewUnknown,
        crewUntrained: plannedCrewUntrained,
        name,
        requirements,
        /* Training the crew has to bring, in the game's own English: the
         * requirement names it `gw_gefahrgut`, `additional` names the same
         * thing `HazMat`, and the pair is stated side by side. */
        crewTraining: mmCrewTraining(record),
        /* What the game says this kind of call is worth on average. It is in
         * the catalogue the `#mission_help` link points at, so it costs
         * nothing to show and it is the game's own figure, not a measurement. */
        listedCredits: record?.average_credits || null,
        lines,
        pick: [...picked.values()],
        fromHelpPage: !!record?.fromHelpPage,
        available: free.length,
        followUp: busy.length,
        followUpOffered: page.followUpOffered,
        untimed,
        scene,
        patients,
        missionType: page.missionType,
    };
}


/**
 * Keep a note of a requirement nothing could be matched to.
 *
 * It rides out in the one report rather than waiting for somebody to notice the
 * warning in the panel and mention it. Key and mission type only — both are the
 * game's own names for things.
 */
/* Which flags a requirement here already asks for, written where Diagnostics
 * can read it: the report names the flags nothing asks for yet, and whatever
 * answers an unmatched requirement is among them. Diagnostics reads stored
 * state rather than reaching into this module, so it is published rather than
 * imported. */
function mmPublishMappedFlags() {
    try {
        localStorage.setItem('ymca-missionmagician-mappedFlags',
            JSON.stringify(MM_NAMED_FLAGS));
    } catch (e) { /* private window */ }
}

function mmRememberUnmatched(key, missionType) {
    const store = 'ymca-missionmagician-unmatched';
    try {
        const seen = JSON.parse(localStorage.getItem(store)) || [];
        if (seen.some((e) => e.key === key)) return;
        seen.push({ key, firstSeenOnMissionType: Number(missionType) || missionType });
        localStorage.setItem(store, JSON.stringify(seen.slice(-40)));
    } catch (e) { /* private window: the panel still says it */ }
}

/** firetrucks -> Firetrucks, for a requirement with no entry in the map. */
/**
 * How many trained crew the mission wants, and what the training is called.
 *
 * This is not a vehicle line — the crew arrive on whatever is sent — but it is
 * why a call sits unfinished with every box green, so it is worth a sentence.
 * The English name comes from `additional.personnel_educations`, which lists
 * the same trainings in the same order as `requirements.personnel_educations`.
 */
function mmCrewTraining(record) {
    const want = record?.requirements?.personnel_educations;
    if (!want || typeof want !== 'object') return null;
    const english = record?.additional?.personnel_educations || {};
    const names = Object.keys(english);
    return Object.entries(want).map(([key, n], i) => ({
        // The keys line up one for one; fall back to the game's own key.
        label: names[i] && english[names[i]] === n ? names[i] : mmPretty(key),
        key,
        count: n,
    }));
}

/* ------------------------------------------------ the game refusing a send */

/**
 * The game saying, out loud, that too few trained crew were sent.
 *
 * NOTHING ON ANY PAGE COUNTS PEOPLE, and that has not changed — this is not a
 * count. It is a refusal, and a refusal is the one moment the game states the
 * thing it otherwise keeps to itself. So it is read where it is unambiguous
 * and nowhere else: the mission asks for a training in `personnel_educations`,
 * and a danger alert on the page names that very training in the game's own
 * words. An alert naming nothing this mission asks for is left alone rather
 * than guessed at, which is what "only in the personnel case" means.
 *
 * `.alert-missing-vehicles` is the game's own line for the other shortfall, so
 * it is skipped by its class rather than by its wording.
 *
 * WHY IT IS REMEMBERED. A refused dispatch hands back the mission window with
 * the alert on it and every box unticked, so the panel would tick the same set,
 * find it green and send exactly what was just refused — the loop this exists
 * to stop. Once the game has refused a mission for want of crew, this panel
 * does not call that mission green again. The game's own Dispatch button is
 * untouched, so the player who has since moved crew about presses it and goes.
 */
const MM_REFUSED_KEY = 'ymca-mm-crew-refused';

const mmMissionId = () => (/\/missions\/(\d+)/.exec(
    document.getElementById('mission-form')?.getAttribute('action') || location.pathname,
) || [])[1] || '';

/** Squash a training name to letters, so `gw_gefahrgut`, `GW Gefahrgut` and
 * `HazMat` all compare as one word however the page spells them. */
const mmWord = (s2) => String(s2 || '').toLowerCase().replace(/[^a-z]+/g, '');

function mmRefusalRead() {
    try {
        return JSON.parse(sessionStorage.getItem(MM_REFUSED_KEY)) || null;
    } catch (e) { return null; }
}

function mmRefusalWrite(refusal) {
    try {
        sessionStorage.setItem(MM_REFUSED_KEY, JSON.stringify(refusal));
    } catch (e) { /* private window: it still holds for this draw */ }
}

function mmCrewRefusal(trainings) {
    if (!trainings || !trainings.length) return null;
    const mission = mmMissionId();

    for (const alert of document.querySelectorAll('.alert-danger')) {
        if (alert.classList.contains('alert-missing-vehicles')) continue;
        const said = mmWord(alert.textContent);
        if (!said) continue;
        const hit = trainings.find((t) => [t.label, t.key, String(t.key).replace(/^gw_/, '')]
            .map(mmWord).filter((w) => w.length >= 4).some((w) => said.includes(w)));
        if (hit) {
            const refusal = { mission, label: hit.label, fresh: true };
            mmRefusalWrite(refusal);
            return refusal;
        }
    }

    const held = mmRefusalRead();
    if (held && held.mission === mission) return { ...held, fresh: false };
    return null;
}

/* COUNTING THE CREW WAS TRIED AND WITHDRAWN.
 *
 * The buy page states `Max. Crew: 3`, and that read like the answer: count the
 * seats on every vehicle carrying the training and stop when the mission's
 * figure is reached. It is not the answer. `Max. Crew` is a cap the player sets
 * per vehicle — the same HazMat can ride with fewer or more — so seats are not
 * people, and a number built on them looks measured while being a guess.
 *
 * Nothing in a mission window says who is aboard. The requirement is stated,
 * and stated as the game states it, until there is something real to count. */

/* ...AND THEN THE PLAYER WAS ASKED.
 *
 * `Max. Crew` is a cap somebody set, which is exactly why the game cannot be
 * read for this — and exactly why the person who set it can. Crew numbers are
 * typed in ElementFriend -> MissionMagician, they are that player's own figure
 * for their own vehicles, and they are labelled as theirs everywhere they
 * show. A number the player states is not a number YMCA inferred.
 *
 * It counts SEATS TICKED, not trained crew. Whether the people aboard a HazMat
 * hold the HazMat training is still not something any page says, so it is
 * still not claimed. The sentence beside it stays the game's own. */
const MM_CREW_KEY = 'ymca-missionmagician-crew';
const MM_KEYS_KEY = 'ymca-missionmagician-keys';

/**
 * The keys that tick and untick.
 *
 * `d` was written into the handler, which is fine until somebody's keyboard
 * layout, their browser or the game itself already wants it. They are one
 * letter each, set in ElementFriend, and **empty is a real answer**: a player
 * who does not want a hotkey at all should not have to find one nobody uses.
 *
 * Letters only. A digit or a punctuation mark is something the game's own
 * dispatch orders are on, and a modifier chord is a browser shortcut.
 */
function mmKeys() {
    let held = {};
    try {
        held = JSON.parse(localStorage.getItem(MM_KEYS_KEY)) || {};
    } catch (e) { /* nothing set */ }
    const letter = (v, fallback) => {
        if (typeof v !== 'string') return fallback;
        const one = v.trim().slice(0, 1).toLowerCase();
        return /^[a-z]$/.test(one) ? one : '';
    };
    return {
        tick: letter(held.tick, 'd'),
        clear: letter(held.clear, ''),
    };
}

function mmCrewOnBoard() {
    try {
        return JSON.parse(localStorage.getItem(MM_CREW_KEY)) || {};
    } catch (e) {
        return {};
    }
}

/** Seats on what is ticked right now, and how many of them are unstated. */
function mmTickedSeats() {
    const crew = mmCrewOnBoard();
    let seats = 0;
    let unstated = 0;
    for (const box of document.querySelectorAll('.vehicle_checkbox:checked')) {
        const n = Number(crew[box.getAttribute('vehicle_type_id')]);
        if (n > 0) seats += n; else unstated += 1;
    }
    return { seats, unstated, anyStated: Object.keys(crew).length > 0 };
}

/** The sentence that goes beside the training line. */
function mmSeatSentence() {
    const { seats, unstated, anyStated } = mmTickedSeats();
    if (!anyStated) {
        return 'How many are aboard is not something this window says \u2014 set your own crew '
            + 'numbers in ElementFriend \u2192 MissionMagician and this will add up what you tick.';
    }
    const tail = unstated
        ? `, and ${unstated} whose crew you have not stated`
        : '';
    return `Ticked so far: <b>${seats}</b> seats by your own crew numbers${tail}. Whether the `
        + 'people aboard hold that training is not something the game says.';
}

/* ---------------------------------------------------- the crew numbers page */

/**
 * ElementFriend -> MissionMagician. One row per type in the fleet, because a
 * type nobody owns has no crew to state.
 *
 * `Max. Crew` from the buy page is shown as a hint and never as the value: it
 * is the cap, and the point of this page is that the cap is not the count.
 */
async function mmSettings(el, ctx) {
    el.innerHTML = '<p class="ymca-dim">Reading your fleet\u2026</p>';
    let vehicles;
    try {
        vehicles = await ctx.game('/api/vehicles');
    } catch (err) {
        el.innerHTML = `<div class="ymca-note bad">Your fleet could not be read
      (${ctx.esc(err.message)}), so there is nothing to list yet.</div>`;
        return;
    }

    const owned = new Map();
    for (const v of vehicles || []) {
        const id = String(v.vehicle_type ?? '');
        if (!id) continue;
        owned.set(id, (owned.get(id) || 0) + 1);
    }
    const learnt = mmLearntTypes();
    const nameOf = (id) => learnt[id]?.name || MM_SHIPPED_TYPES[id]?.name || `Type ${id}`;
    const crew = mmCrewOnBoard();

    const rows = [...owned.keys()]
        .sort((a, b) => nameOf(a).localeCompare(nameOf(b)))
        .map((id) => {
            const cap = MM_SHIPPED_TYPES[id]?.crew;
            return `<tr>
          <td>${ctx.esc(nameOf(id))} <small>#${ctx.esc(id)}</small></td>
          <td class="ymca-num">${owned.get(id)}</td>
          <td class="ymca-dim ymca-num">${cap ? ctx.esc(String(cap)) : '\u2014'}</td>
          <td><input type="number" min="0" max="99" style="width:72px" data-crew="${ctx.esc(id)}"
            value="${crew[id] > 0 ? ctx.esc(String(crew[id])) : ''}" placeholder="\u2014"></td>
        </tr>`;
        }).join('');

    const keys = mmKeys();
    el.innerHTML = `
    <div class="ymca-card">
      <b>Keys</b>
      <p class="ymca-dim" style="margin:4px 0 9px;font-size:12px">One letter each, and
        <b>empty is a real answer</b> &mdash; a key nobody wants is a key that gets in the way of
        something the game or the browser already uses. Letters only; a chord is a browser
        shortcut and a digit is one of the game&rsquo;s own dispatch orders.</p>
      <div class="ymca-row">
        <label>Tick the plan<br><input maxlength="1" size="2" data-key="tick"
          value="${ctx.esc(keys.tick)}" placeholder="\u2014" style="width:52px"></label>
        <label>Untick everything<br><input maxlength="1" size="2" data-key="clear"
          value="${ctx.esc(keys.clear)}" placeholder="\u2014" style="width:52px"></label>
      </div>
    </div>

    <div class="ymca-note">A mission can ask for trained crew &mdash; eight with HazMat, say
      &mdash; and they ride on whatever you send. Nothing in the game says how many people are
      on a vehicle: <b>Max. Crew</b> on the buy page is the cap you set, not the count. So this
      is <b>your</b> number, and MissionMagician says so wherever it uses it.</div>

    ${rows ? `<div class="ymca-card">
      <table>
        <thead><tr><th>Vehicle type</th><th class="text-right">You own</th>
          <th>Max. crew</th><th>Crew on board</th></tr></thead>
        <tbody>${rows}</tbody>
      </table>
    </div>
    <div class="ymca-row">
      <button class="ymca-btn" data-do="clear">Clear them all</button>
      <span class="ymca-dim" style="font-size:12px">Saved as you type.</span>
    </div>`
        : '<div class="ymca-note warn">No vehicles yet, so there is nothing to state.</div>'}`;

    el.addEventListener('input', (e) => {
        const key = e.target.closest('[data-key]');
        if (key) {
            const one = key.value.trim().slice(0, 1).toLowerCase();
            key.value = /^[a-z]$/.test(one) ? one : '';
            const held = mmKeys();
            held[key.dataset.key] = key.value;
            ctx.store.write('keys', held);
            ctx.status(key.value ? `${key.dataset.key} is ${key.value}.` : 'No key for that.');
            return;
        }
        const box = e.target.closest('[data-crew]');
        if (!box) return;
        const held = mmCrewOnBoard();
        const n = Number(box.value);
        if (n > 0) held[box.dataset.crew] = Math.min(99, Math.round(n));
        else delete held[box.dataset.crew];
        ctx.store.write('crew', held);
        ctx.status('Crew numbers saved.');
    });
    el.addEventListener('click', (e) => {
        if (!e.target.closest('[data-do="clear"]')) return;
        ctx.store.write('crew', {});
        el.querySelectorAll('[data-crew]').forEach((box) => { box.value = ''; });
        ctx.status('Crew numbers cleared.');
    });
}

function mmPretty(key) {
    return key.replace(/_/g, ' ').replace(/^./, (c) => c.toUpperCase());
}

/* ------------------------------------------------------------- the selecting */

/**
 * Tick the game's own checkboxes.
 *
 * A native change event is dispatched because the game listens for one —
 * `$("body").on("change", ".vehicle_checkbox", …)` keeps its counter, its water
 * bar and its AAO state up to date from it. Setting `checked` alone would leave
 * the page showing the player something different from what it would send.
 */
function mmSelect(pick) {
    let n = 0;
    for (const v of pick) {
        if (v.box.checked) continue;
        v.box.checked = true;
        v.box.dispatchEvent(new Event('change', { bubbles: true }));
        n += 1;
    }
    return n;
}

/**
 * Clear the selection the way the game does.
 *
 * Every dispatch order list carries a Reset entry — `.aao[reset="true"]` — and
 * clicking it is the game's own way of putting the selection back, counters,
 * water bar and all. Unticking each box by hand is only the fallback for a
 * window with no dispatch orders on it.
 */
function mmClear() {
    const reset = document.querySelector('.aao[reset="true"]');
    if (reset) {
        reset.click();
        return -1;
    }
    let n = 0;
    for (const box of document.querySelectorAll('.vehicle_checkbox:checked')) {
        box.checked = false;
        box.dispatchEvent(new Event('change', { bubbles: true }));
        n += 1;
    }
    return n;
}

/* ---------------------------------------------------------------- the panels */

function mmPlanHtml(plan, page, cfg, ctx) {
    const rows = plan.lines.map((l) => {
        const enough = l.found !== null && l.found >= l.wanted;
        const state = l.unmatched
            ? '<span class="ymca-warn">not matched yet</span>'
            : `<span class="${enough ? 'ymca-accent' : 'ymca-bad'}">${ctx.fmt(l.found)}${l.unit ? ` ${l.unit}` : ''}</span>`;
        return `<tr>
      <td class="ymca-num" style="width:1%;white-space:nowrap">${ctx.fmt(l.wanted)}${l.unit ? ` ${l.unit}` : ''}</td>
      <td class="ymca-num" style="width:1%">${l.onScene || '<span class="ymca-dim">&ndash;</span>'}</td>
      <td class="ymca-num" style="width:1%;padding-right:10px">${state}</td>
      <td>${ctx.esc(l.label)}${mmIcon(l.icon)}</td></tr>`;
    }).join('');

    const unmatched = plan.lines.filter((l) => l.unmatched);
    const short = plan.lines.filter((l) => !l.unmatched && l.found < l.wanted);

    return `
      <div class="ymca-note"><b>This is also in the mission window itself</b>, at the top of its
        right-hand column.</div>

      <div class="ymca-note"><b>It picks. It does not dispatch.</b> It ticks the game's own
        checkboxes and stops. You press Dispatch.</div>

      <div class="ymca-card">
        <b>${plan.name ? ctx.esc(plan.name) : `Mission type ${ctx.esc(String(page.missionType))}`}</b>
        <p class="ymca-sub" style="margin:4px 0 8px">What this needs, against the
          ${plan.available} vehicles in range.</p>
        ${plan.requirements ? `<table style="margin-top:4px" id="mm-needs">
          <thead><tr><th class="ymca-num">Wanted</th><th class="ymca-num">There</th>
            <th class="ymca-num" style="padding-right:10px">Covered</th><th>Needs</th></tr></thead>
          <tbody>${rows}</tbody></table>`
        : '<p class="ymca-bad">This mission type is not in the game\'s list, so nothing can be planned.</p>'}
      </div>

      ${short.length ? `<div class="ymca-note warn"><b>Not enough on screen.</b>
        ${short.map((l) => ctx.esc(l.label)).join(', ')} — this window is not offering enough of
        them. Widen the range with the game's own km buttons and reopen this.</div>` : ''}

      ${unmatched.length ? `<div class="ymca-note warn"><b>${unmatched.length} requirement${
        unmatched.length > 1 ? 's are' : ' is'} not matched yet:</b>
        ${unmatched.map((l) => ctx.esc(l.label)).join(', ')}. Which checkbox attribute means these
        has not been established, and a guess would tick the wrong vehicle — so they are named here
        and left alone. Send a problem report from a mission needing one and it can be added.</div>` : ''}

      <div class="ymca-card">
        <b>Pick them</b>
        <label style="display:block;margin:4px 0"><input type="checkbox" data-cfg="fastestFirst"
          ${cfg.fastestFirst !== false ? 'checked' : ''}> Fastest first, by travel time</label>
        <button class="ymca-btn primary" data-do="select">Tick ${plan.pick.length} vehicles</button>
        <button class="ymca-btn" data-do="clear">Untick everything</button>
        <div class="ymca-note" id="mm-done" hidden style="margin-top:10px">Ticked.</div>
      </div>`;
}

function mmOffMissionHtml() {
    return `
      <div class="ymca-note"><b>Nothing to do here.</b> MissionMagician puts itself
        <b>inside the mission window</b>, above the game's own missing-vehicle line. Open any
        mission and it is already there — you do not open YMCA for it at all.</div>

      <div class="ymca-card">
        <b>What it does there</b>
        <ul class="ymca-sub" style="margin:6px 0 0;padding-left:20px">
          <li>Lists what the mission needs, from the game's own mission list, against what is in
            range — and keeps the list current as the game works out the travel times.</li>
          <li>One button ticks the vehicles that match, <b>fastest first by travel time</b>, not by
            how close the dot looks on the map.</li>
          <li>It never presses Dispatch. That stays yours.</li>
        </ul>
      </div>

      <div class="ymca-card">
        <b>If it still says this while a mission is open</b>
        <p class="ymca-sub" style="margin:4px 0 10px">This copies the window's structure —
          element, class and field names and the numbers in them. No mission text, addresses or
          player names.</p>
        <button class="ymca-btn" data-do="capture">Capture this mission window</button>
        <span class="ymca-status" id="mm-status"></span>
        <div class="ymca-note warn" id="mm-wrongpage" hidden style="margin-top:10px">
          <b>That was not the mission frame.</b> Nothing was copied, because there was nothing on
          this page worth sending. Open the mission, then open YMCA with the floating button
          <i>inside</i> it, and press this there.</div>
        <textarea id="mm-out" rows="10" readonly style="width:100%;margin-top:10px;
          font-family:ui-monospace,monospace;font-size:11.5px"></textarea>
      </div>`;
}

function mmWireCapture(el, ctx) {
    el.addEventListener('click', (e) => {
        if (!e.target.closest('[data-do="capture"]')) return;
        const out = el.querySelector('#mm-out');
        const report = captureMissionWindow();
        out.value = JSON.stringify(report, null, 1);
        const warn = el.querySelector('#mm-wrongpage');
        warn.hidden = report.looksLikeMissionWindow;
        if (report.looksLikeMissionWindow) {
            ctx.clipboard(out.value, 'the mission window structure');
        } else {
            ctx.status('No mission window on this page — nothing worth sending.');
        }
        ctx.log.info('captured mission window',
            report.looksLikeMissionWindow ? `${report.found.length} selectors found` : 'not on a mission page');
    });
}

/**
 * Describe the mission window without reading its content.
 *
 * Structure is what is needed — which form carries the dispatch, how a vehicle
 * row is marked up, what the alarm control is called. Mission text, street
 * names and player names are not, so they are not taken.
 *
 * The first real capture answered half of it: the dispatch is a plain form with
 * `input[name="vehicle_ids[]"]` checkboxes and an `input[name="commit"]` submit,
 * which is exactly the shape the safe-write rule wants — tick the game's own
 * boxes and submit the game's own form, never build one. What it could not
 * answer is what holds those checkboxes, because the table is not
 * `#vehicle_show_table_body` or `table.vehicle_table`. So this version stops
 * guessing at container names and walks up from a checkbox instead.
 */
function captureMissionWindow() {
    const CANDIDATES = [
        // Confirmed present on a real mission page.
        '#mission_general_info', '#missing_text', '#vehicle_show_table_all',
        '.alert-missing-vehicles', 'input[name="vehicle_ids[]"]', '.aao',
        'input[name="commit"]', '.alert_next', '.vehicle_checkbox',
        // Confirmed absent, kept so a future game change shows up as a diff.
        '.mission_header', '#mission_vehicle_driving', '#vehicle_show_table_body',
        'table.vehicle_table', '#mission_vehicle_amount', '#mission_aao_group',
        'form#vehicle_select', '#vehicle_list',
        // Named by jxn-30/LSS-Scripts, not yet seen on this player's page.
        '#vehicle_show_table_body_all', '.vehicle_select_table_tr', '#mission_alarm_btn',
        '#vehicle_list_step', '.vehicle_checkbox[vehicle_type_id]',
    ];
    const seen = CANDIDATES.filter((sel) => !!document.querySelector(sel));

    const classOf = (el) => (typeof el.className === 'string' ? el.className.trim().slice(0, 120) : '');
    /** Digits out, so an id is reported as a shape rather than as a particular thing. */
    const shapeId = (id) => String(id || '').replace(/\d+/g, '#').slice(0, 48);

    const outline = (el) => (el ? { tag: el.tagName.toLowerCase(), id: shapeId(el.id) || undefined, class: classOf(el) || undefined } : null);

    const checkbox = document.querySelector('input[name="vehicle_ids[]"], .vehicle_checkbox');
    const rowsPresent = document.querySelectorAll('.vehicle_select_table_tr').length
        || document.querySelectorAll('input[name="vehicle_ids[]"]').length;

    /* --- the form that actually dispatches ---
     * Its field names are what a safe write needs: everything unrelated has to
     * survive, so it has to be known what "everything unrelated" is. Names only;
     * a value could be a CSRF token or a caption. */
    // :has() is recent enough that an older browser would throw and take the whole
    // capture with it, and closest() answers this on every page seen so far anyway.
    let form = checkbox?.closest('form') || null;
    if (!form) {
        try {
            form = document.querySelector('form:has(input[name="vehicle_ids[]"])');
        } catch (e) { /* no :has() here */ }
    }
    const dispatchForm = form ? {
        id: shapeId(form.id) || undefined,
        class: classOf(form) || undefined,
        action: (form.getAttribute('action') || '').split('?')[0].replace(/\d+/g, '#'),
        method: form.getAttribute('method') || 'get',
        fieldNames: [...new Set([...form.elements].map((f) => f.name).filter(Boolean))].slice(0, 30),
        submitNames: [...form.querySelectorAll('[type=submit]')].map((b) => b.name || '(unnamed)'),
        checkboxCount: form.querySelectorAll('input[name="vehicle_ids[]"]').length,
    } : 'no form wraps the vehicle checkboxes';

    /* --- what holds a vehicle, found by walking up rather than by guessing --- */
    const chain = [];
    for (let node = checkbox?.parentElement; node && node !== document.body && chain.length < 8; node = node.parentElement) {
        chain.push(outline(node));
        if (node.tagName === 'FORM') break;
    }

    const row = checkbox?.closest('tr') || chain[1] && checkbox?.parentElement?.parentElement || null;
    const describeRow = (el) => (el ? {
        tag: el.tagName.toLowerCase(),
        class: classOf(el) || undefined,
        idShape: shapeId(el.id) || undefined,
        attrs: [...el.attributes].map((a) => a.name),
        // Numbers in attributes are how a row says which vehicle type it is. Text is not taken.
        numericAttrs: Object.fromEntries([...el.attributes]
            .filter((a) => /^-?\d+$/.test(a.value) && a.value.length <= 12)
            .map((a) => [a.name, Number(a.value)])),
        cellCount: el.cells?.length,
        cells: [...(el.cells || el.children)].slice(0, 10).map((c) => ({
            tag: c.tagName.toLowerCase(),
            class: classOf(c) || undefined,
            childTags: [...c.children].slice(0, 5).map((x) => x.tagName.toLowerCase()),
            childClasses: [...c.children].slice(0, 5).map((x) => classOf(x)).filter(Boolean),
        })),
    } : 'no vehicle row found');

    /* --- everything the page marks as mission-ish ---
     * The mission's *type* has to be findable, because that is the key into
     * /einsaetze.json where the requirements and the credit figure already are.
     * Reading the requirements off the page would mean reading its text. */
    const missionHints = [];
    for (const el of document.querySelectorAll('[id*="mission"], [class*="mission"], [data-mission-type-id], [data-mission-id]')) {
        const hint = {
            tag: el.tagName.toLowerCase(),
            idShape: shapeId(el.id) || undefined,
            class: classOf(el) || undefined,
            numericData: Object.fromEntries(Object.entries(el.dataset || {})
                .filter(([, v]) => /^-?\d+$/.test(v) && v.length <= 12)
                .map(([k, v]) => [k, Number(v)])),
        };
        if (!hint.idShape && !hint.class && !Object.keys(hint.numericData).length) continue;
        if (missionHints.some((h) => h.idShape === hint.idShape && h.class === hint.class)) continue;
        missionHints.push(hint);
        if (missionHints.length >= 25) break;
    }

    const aaos = [...document.querySelectorAll('.aao')];

    return {
        note: 'structure only — element, class and field names and the numbers in them. '
            + 'No mission text, addresses, player names or field values.',
        url: location.pathname.replace(/\d+/g, '#'),
        looksLikeMissionWindow: /\/missions?\//.test(location.pathname)
            || !!document.querySelector('#mission_general_info, #missing_text'),
        // On the big map this page is an iframe, so saying which one it is beats guessing later.
        inFrame: window.top !== window.self,
        vehicleRowsPresent: rowsPresent,
        found: seen,
        missing: CANDIDATES.filter((sel) => !seen.includes(sel)),
        dispatchForm,
        vehicleContainerChain: chain,
        vehicleRow: describeRow(row),
        checkbox: checkbox ? {
            name: checkbox.name,
            class: classOf(checkbox),
            idShape: shapeId(checkbox.id) || undefined,
            // The first capture only read data-* and so missed vehicle_type_id, which is a
            // plain attribute. Names and types, not values: data-distance says where you are.
            attributes: [...checkbox.attributes]
                .map((a) => `${a.name}:${/^-?[\d.]+$/.test(a.value) ? 'number' : 'string'}`),
            // The vehicle type is the one value that has to come through, because it is what
            // matches a row against a requirement from /einsaetze.json.
            vehicleTypeId: Number(checkbox.getAttribute('vehicle_type_id')) || null,
        } : 'no vehicle checkbox found',
        aao: aaos.length ? {
            count: aaos.length,
            sample: {
                tag: aaos[0].tagName.toLowerCase(),
                class: classOf(aaos[0]),
                attrs: [...aaos[0].attributes].map((a) => a.name),
                numericData: Object.fromEntries(Object.entries(aaos[0].dataset || {})
                    .filter(([, v]) => /^-?\d+$/.test(v))
                    .map(([k, v]) => [k, Number(v)])),
            },
        } : 'no AAO buttons found',
        missionHints,
        alarmControls: [...document.querySelectorAll('input[type=submit], button[type=submit], .btn-success')]
            .slice(0, 8).map((b) => ({
                tag: b.tagName.toLowerCase(), type: b.type, name: b.name || undefined,
                class: classOf(b).slice(0, 80) || undefined,
                text: (b.value || b.textContent || '').trim().slice(0, 30),
            })),
        patients: mmPatientProbe(),
        /* What the game's own refusals on this page are called. The wording is
         * never taken — a class list is structure, and it is what says which
         * alert is the missing-vehicles one and which is something else. */
        dangerAlerts: [...document.querySelectorAll('.alert-danger')].map((a) => a.className),
        requirementBlocks: [...document.querySelectorAll('#missing_text, .missing_text, #mission_general_info')]
            .map((e) => ({
                id: e.id, class: classOf(e),
                childTags: [...e.children].map((c) => c.tagName),
                // Whether the requirement is text or markup decides whether it can be parsed
                // at all, without saying what it says.
                textLength: (e.textContent || '').trim().length,
                hasElementChildren: e.children.length > 0,
            })),
    };
}

/* ======================================================================
 * The panel in the game's own mission window.
 *
 * A tool you have to open a lightbox to reach is a tool you stop using, and
 * the lightbox has the further problem that YMCA's window is built before the
 * mission frame has finished loading — so it read an empty page unless you
 * reloaded it. Living in the window solves both: it is there when the mission
 * is, and it re-reads itself as the game fills the table in.
 *
 * This is the one place a module writes markup outside its own panel, so it
 * writes **no colours of its own**. Everything is the game's own Bootstrap —
 * `panel`, `table`, `btn`, `label` — which means it follows the game into dark
 * mode without YMCA having to know anything about it.
 * ====================================================================== */

const MM_PANEL_ID = 'ymca-mm-panel';

/* The two states the table can be in, said loudly enough to read without
 * looking. Not from the interface probe: the game has no "everything is
 * covered" of its own to match, so these are chosen, and they are the only
 * colours in YMCA that are. */
const MM_RED = '#e74c3c';
const MM_GREEN = '#00bc8c';

/**
 * A switch rather than a tick box.
 *
 * The real checkbox is still there and still what the browser reports — it is
 * moved out of sight rather than replaced, so a click, a label and a keyboard
 * all behave as they did. Only the track and the knob are drawn.
 */
/** How many requirement rows the frame is built for. Below this it does not
 * shrink; above it, the rest scroll. */
const MM_ROWS_SHOWN = 6;

const MM_SWITCH_CSS = `
#${MM_PANEL_ID} .mm-switch{display:inline-flex;align-items:center;gap:7px;
  font-weight:normal;margin:0;cursor:pointer;user-select:none}
#${MM_PANEL_ID} .mm-switch input{position:absolute;opacity:0;width:0;height:0}
#${MM_PANEL_ID} .mm-switch i{position:relative;width:30px;height:16px;flex:0 0 30px;
  border-radius:8px;background:rgba(127,127,127,.5);transition:background .15s}
#${MM_PANEL_ID} .mm-switch i::after{content:"";position:absolute;top:2px;left:2px;
  width:12px;height:12px;border-radius:50%;background:#fff;transition:left .15s}
#${MM_PANEL_ID} .mm-switch input:checked + i{background:${MM_GREEN}}
#${MM_PANEL_ID} .mm-switch input:checked + i::after{left:16px}
#${MM_PANEL_ID} .mm-switch input:focus-visible + i{outline:2px solid currentColor;outline-offset:2px}
#${MM_PANEL_ID} .mm-switch.off{opacity:.55}
#${MM_PANEL_ID} .mm-lock{background:none;border:0;padding:0 2px;line-height:1;opacity:.45;color:inherit}
#${MM_PANEL_ID} .mm-lock.on{opacity:1}

/* The cells are what is painted, not the table. Bootstrap's own table styling
 * and the game's dark theme both set a background on td and th, so colouring
 * the table alone put the colour behind them and nothing showed. */
#${MM_PANEL_ID} .mm-table.mm-short,#${MM_PANEL_ID} .mm-table.mm-ok{color:#fff}
#${MM_PANEL_ID} .mm-table.mm-short td,#${MM_PANEL_ID} .mm-table.mm-short th{
  background-color:${MM_RED}!important;color:#fff!important;border-color:rgba(255,255,255,.25)!important}
#${MM_PANEL_ID} .mm-table.mm-ok td,#${MM_PANEL_ID} .mm-table.mm-ok th{
  background-color:${MM_GREEN}!important;color:#fff!important;border-color:rgba(255,255,255,.25)!important}
/* A met line goes green on its own, whatever the table around it is doing, so
 * what is still missing is the only thing still red. */
#${MM_PANEL_ID} .mm-table tr.mm-row-ok td{
  background-color:${MM_GREEN}!important;transition:background-color .25s}
#${MM_PANEL_ID} .mm-table.mm-short small,#${MM_PANEL_ID} .mm-table.mm-ok small{color:rgba(255,255,255,.8)}

/* One height, whatever the mission asks for.
 *
 * A panel that grows and shrinks with the requirement count moves the buttons
 * under the cursor between one mission and the next. The frame is ${MM_ROWS_SHOWN}
 * rows tall and stays there: fewer rows leave space below, more rows scroll
 * inside it, and Dispatch never moves. */
#${MM_PANEL_ID} .mm-scroll{position:relative;margin-bottom:8px;
  height:calc(var(--mm-head) + ${MM_ROWS_SHOWN} * var(--mm-row));
  --mm-row:29px;--mm-head:33px;
  overflow-y:auto;overflow-x:hidden;scrollbar-width:thin;
  scrollbar-color:rgba(127,127,127,.55) transparent}
#${MM_PANEL_ID} .mm-scroll::-webkit-scrollbar{width:8px}
#${MM_PANEL_ID} .mm-scroll::-webkit-scrollbar-track{background:transparent}
#${MM_PANEL_ID} .mm-scroll::-webkit-scrollbar-thumb{
  background:rgba(127,127,127,.55);border-radius:4px;
  border:2px solid transparent;background-clip:content-box}
#${MM_PANEL_ID} .mm-scroll:hover::-webkit-scrollbar-thumb{background:rgba(127,127,127,.8);
  background-clip:content-box}
#${MM_PANEL_ID} .mm-scroll .mm-table{margin-bottom:0}
#${MM_PANEL_ID} .mm-scroll thead th{position:sticky;top:0;z-index:1}

/* Only when there is more below: the last rows fade rather than being cut,
 * and the fade lifts as the bottom is reached. Masked, not painted over, so it
 * works on whatever colour the row happens to be. */
#${MM_PANEL_ID} .mm-scroll.mm-more{
  -webkit-mask-image:linear-gradient(to bottom,#000 calc(100% - 34px),transparent);
  mask-image:linear-gradient(to bottom,#000 calc(100% - 34px),transparent);
  transition:-webkit-mask-image .2s,mask-image .2s}
#${MM_PANEL_ID} .mm-scroll.mm-more.mm-end{
  -webkit-mask-image:linear-gradient(to bottom,#000 100%,#000);
  mask-image:linear-gradient(to bottom,#000 100%,#000)}

/* The glyphs sit on the text baseline and take its colour. */
#${MM_PANEL_ID} .mm-switches{display:flex;flex-wrap:wrap;align-items:center;gap:7px 14px;
  margin-bottom:8px}
#${MM_PANEL_ID} .mm-buttons{display:flex;flex-wrap:wrap;align-items:center;gap:7px;
  justify-content:flex-end}
#${MM_PANEL_ID} .mm-key{display:inline-block;margin-left:5px;padding:0 5px;border-radius:3px;
  font:600 11px/17px "Helvetica Neue",Helvetica,Arial;text-transform:uppercase;
  background:rgba(255,255,255,.22);box-shadow:inset 0 -1px 0 rgba(0,0,0,.25)}
#${MM_PANEL_ID} .mm-glyph{vertical-align:-2.5px;margin-left:6px;opacity:.8;overflow:visible}
#${MM_PANEL_ID} tr:hover .mm-glyph{opacity:1}`;

function mmSwitch(key, label, on, disabled) {
    return `<label class="mm-switch${on ? '' : ' off'}"${disabled ? ' title="not on this mission"' : ''}>
    <input type="checkbox" data-cfg="${key}"${on ? ' checked' : ''}${disabled ? ' disabled' : ''}>
    <i></i>${label}</label>`;
}

/**
 * Follow-up is a plain switch.
 *
 * It holds vehicles that are out on another mission and can be redirected here,
 * so two missions armed at once can take each other's and leave them driving
 * between. It was guarded against — a claim, a lock, an automatic switch-off
 * after dispatching — and the guard was wrong more often than the thing it
 * guarded against happened. It stays on until it is switched off.
 */
/* The game fills travel times in after the page settles and appends rows when
 * "load missing vehicles" is used, so the panel re-reads rather than assuming
 * the first look was the whole picture. */
const MM_REDRAW_MS = 400;

/* Returns true once the panel is in. Until then the shell tries again as the
 * mission window builds itself, so the panel appears with the markup rather
 * than after the last script on the page has finished loading. */
YMCA.inject('missionmagician', (ctx) => {
    if (!mmReadMissionPage().onMissionPage) return false;
    mmMountPanel(ctx);
    return true;
});

function mmMountPanel(ctx) {
    if (document.getElementById(MM_PANEL_ID)) return;

    const panel = document.createElement('div');
    panel.id = MM_PANEL_ID;
    panel.className = 'panel panel-default';
    panel.innerHTML = '<div class="panel-body"><i>YMCA is reading this mission…</i></div>';

    if (!document.getElementById('ymca-mm-style')) {
        const style = document.createElement('style');
        style.id = 'ymca-mm-style';
        style.textContent = MM_SWITCH_CSS;
        document.head.append(style);
    }

    /* Top of the right-hand half, which is where LSS-Manager puts its own mission
     * helper. The window is two columns — the dispatch orders on the left and
     * everything else on the right — and this belongs with the everything else.
     * Above the game's missing-vehicle line, then the top of the frame, are the
     * fallbacks for a window laid out differently. */
    const right = document.getElementById('col_right');
    const missing = document.getElementById('missing_text');
    if (right) right.prepend(panel);
    else if (missing) missing.parentNode.insertBefore(panel, missing);
    else document.getElementById('iframe-inside-container')?.prepend(panel);

    let timer = null;
    let lastPlan = null;
    /* Drawing waits on the catalogue and sometimes on the mission's own
     * requirements page, so two draws can be in flight at once and the slower —
     * older — one can land last and put a stale plan on screen. Only the newest
     * is allowed to render. */
    let drawing = 0;
    const draw = async () => {
        const mine = (drawing += 1);
        const cfg = ctx.store.read('cfg', { fastestFirst: true });
        /* Another mission holding follow-up means its tab is not opened here
         * either: the guard is on what gets read, not only on the switch. */
        const page = mmReadMissionPage(cfg.followUp === true);
        if (!page.onMissionPage) return;
        const plan = await mmPlan(page, ctx, cfg);
        if (mine !== drawing) return;
        panel.dataset.pick = plan.pick.map((v) => v.id).join(',');
        panel.dataset.type = String(plan.missionType || '');
        plan.surplus = mmSurplus(plan);
        lastPlan = plan;
        panel.innerHTML = mmGamePanelHtml(plan, cfg, ctx);
        mmRecount(panel, plan);
        mmWatchScroll(panel);
    };
    const redraw = () => {
        clearTimeout(timer);
        timer = setTimeout(() => { draw(); }, MM_REDRAW_MS);
    };

    const tick = () => {
        const ids = (panel.dataset.pick || '').split(',').filter(Boolean);
        const n = mmSelectIds(ids);
        ctx.log.info('ticked vehicles', `${n} in the mission window`);
        const done = panel.querySelector('#mm-panel-done');
        if (done) done.hidden = false;
        /* AND THAT IS WHERE IT STOPS. What follows a tick is the player
         * reading the table and pressing the game's own Dispatch. An alarm
         * cannot be taken back, and a tool that presses it is playing the game
         * rather than helping somebody play it. */
    };

    /* The keys are read on every press rather than captured here, so changing
     * one in ElementFriend takes effect without reopening the mission. The
     * game's own dispatch orders are on single letters too, so this stays out
     * of the way of anything being typed and of any chord — a letter with a
     * modifier is a browser shortcut, not a dispatch. */
    document.addEventListener('keydown', (e) => {
        if (e.ctrlKey || e.metaKey || e.altKey) return;
        const pressed = (e.key || '').toLowerCase();
        if (!/^[a-z]$/.test(pressed)) return;
        const keys = mmKeys();
        const what = pressed === keys.tick ? 'tick' : pressed === keys.clear ? 'clear' : null;
        if (!what) return;
        const on = e.target;
        if (on && (on.isContentEditable || /^(input|textarea|select)$/i.test(on.tagName))) return;
        if (!document.getElementById(MM_PANEL_ID)) return;
        e.preventDefault();
        if (what === 'tick') {
            tick();
            ctx.status?.('Ticked.');
            return;
        }
        mmClear();
        const done = document.getElementById('mm-panel-done');
        if (done) done.hidden = true;
        ctx.status?.('Unticked.');
    });

    panel.addEventListener('click', (e) => {
        if (e.target.closest('[data-do="select"]')) {
            tick();
        } else if (e.target.closest('[data-do="clear"]')) {
            mmClear();
            const done = panel.querySelector('#mm-panel-done');
            if (done) done.hidden = true;
        } else if (e.target.closest('[data-do="report"]')) {
            mmCopyState(ctx, lastPlan, panel);
        } else if (e.target.closest('[data-do="type"]')) {
            mmCopyType(ctx, panel.dataset.type);
        } else if (e.target.closest('[data-do="cancel"]')) {
            /* This one writes to the account, so it says exactly what it will do
             * and waits to be told yes. It is undoable in the only way that
             * matters here — the vehicles can be sent again — and it clicks the
             * game's own send-back button rather than posting anything. */
            const drop = mmSurplus(lastPlan);
            if (!drop.length) { ctx.status('Nothing is spare.'); return; }
            const ok = confirm(`Send ${drop.length} vehicle${drop.length > 1 ? 's' : ''} back?\n\n`
                + 'Every requirement was checked again after each one, so what is left still '
                + 'covers the mission. They can be alarmed again afterwards.');
            if (!ok) return;
            for (const v of drop) v.back.click();
            ctx.log.info('sent back', `${drop.length} surplus vehicles`);
            ctx.status(`Sent ${drop.length} back.`);
        }
    });

    panel.addEventListener('change', (e) => {
        const key = e.target.dataset.cfg;
        /* AUTO'S SWITCH IS NOT HERE. It lives in the game's own mission-filter
         * row, where it is on screen whatever mission is open — a switch inside
         * the panel was two clicks away whenever the window it belonged to was
         * shut, and moved with the table under the cursor besides. */
        if (!['fastestFirst', 'ambulancePerPatient', 'followUp', 'countDriving'].includes(key)) return;
        const cfg = ctx.store.read('cfg', {});
        cfg[key] = e.target.checked;
        ctx.store.write('cfg', cfg);
        draw();
    });

    /* Watch the whole mission, not only the selection table. Rows arriving and
     * travel times landing are one half; a vehicle reaching the mission is the
     * other, and that turns up in a different table entirely — which is how a
     * panel that only watched the selection list ended up showing a plan made
     * before anything had been sent.
     *
     * Its own writes are skipped, or rendering would trigger another render. */
    /* Follow-up takes vehicles off other missions, so it is a decision for one
     * alarm rather than a setting. It switches itself off once the alarm goes,
     * unless the lock beside it says otherwise.
     *
     * Only one of the game's five ways to dispatch submits the form. `Dispatch`
     * is `input[name="commit"]` inside `#mission-form`; `Dispatch and Next`
     * (`.alert_next`), the alliance one that shares as it goes
     * (`.alert_next_alliance`) and both navbar buttons (`#mission_alarm_btn`,
     * `#mission_alarm_btn_mobile`) are all `<a href="#">` that post by
     * themselves. Watching the submit alone left follow-up on through every
     * one of them.
     *
     * The click is only listened to, never taken over: the capture phase runs
     * before the game's own handler and nothing here touches the event, so the
     * dispatch goes exactly as it would. Switching off is the safe direction
     * anyway — the lock is what makes it stay on. */

    /* The game fires change on every box it ticks, its dispatch orders included,
     * so this catches the player's clicks and YMCA's alike. */
    document.addEventListener('change', (e) => {
        if (e.target?.classList?.contains('vehicle_checkbox')) mmRecount(panel, lastPlan);
    });

    const watched = document.getElementById('iframe-inside-container') || document.body;
    new MutationObserver((records) => {
        for (const rec of records) {
            if (rec.target instanceof Node && panel.contains(rec.target)) continue;
            redraw();
            return;
        }
    }).observe(watched, {
        childList: true, subtree: true, attributes: true, attributeFilter: ['timevalue'],
    });
    draw();
    ctx.log.info('panel placed in the mission window');
}

/** Tick by id, so the panel survives the game re-sorting its own table. */
function mmSelectIds(ids) {
    let n = 0;
    for (const id of ids) {
        const box = document.getElementById(`vehicle_checkbox_${id}`);
        if (!box || box.checked) continue;
        box.checked = true;
        box.dispatchEvent(new Event('change', { bubbles: true }));
        n += 1;
    }
    return n;
}

/**
 * The panel, in the game's own clothes.
 *
 * No colour is chosen here. `label-success` and `label-danger` are the game's,
 * so a met requirement and a short one read the same as everywhere else in it.
 */
/**
 * Which vehicles at the mission are surplus.
 *
 * Not "more than the requirement asks for" — that is the trap. A Quint at the
 * mission may be the only thing covering the ladder *and* one of the engines,
 * so removing it looks safe against the engine count and is not. The only
 * honest test is to take one away and check every requirement again, which is
 * what this does: try each candidate, keep the removal only if everything is
 * still met afterwards, and carry that forward so two removals are checked
 * together rather than each against the full set.
 *
 * Slowest first, so what is given back is what would have arrived last.
 */
function mmSurplus(plan) {
    const known = mmKnownTypes();
    const here = [];
    const rows = document.querySelectorAll(
        '#mission_vehicle_at_mission tbody tr[id^="vehicle_row"], '
        + '#mission_vehicle_driving tbody tr[id^="vehicle_row"]');
    for (const row of rows) {
        const back = row.querySelector('.btn-backalarm-ajax');
        const typeId = row.querySelector('[vehicle_type_id]')?.getAttribute('vehicle_type_id');
        // Without a way to send it back, or without knowing what it covers, leave it alone.
        if (!back || !typeId || !known[typeId]) continue;
        here.push({ back, typeId, flags: known[typeId] });
    }
    if (!here.length) return [];

    /* Only requirements that can be judged. An unmatched one is unknown, and
     * nothing is sent back on the strength of a requirement nobody can check. */
    const checks = plan.lines
        .filter((l) => !l.unmatched && !l.unit && l.rule)
        .map((l) => ({ wanted: l.wanted, rule: l.rule }));
    if (!checks.length) return [];

    const covers = (flags, rule) => (rule.anyOf
        ? rule.anyOf.some((f) => flags.includes(f))
        : flags.includes(rule.flag));

    /* A vehicle whose abilities no requirement here judges is not surplus, it is
     * unaccounted for. An ambulance on a call whose patients went undetected has
     * no ambulance line to be measured against, and sending it away because
     * nothing asked for it is exactly the wrong reading. */
    const judged = new Set(checks.flatMap(({ rule }) => rule.anyOf || [rule.flag]));
    /* Judged against the flags a requirement can ask for. The game also writes
     * composites of its own — `road_rescue_or_fire_engine`, `ktw_or_rtw` — and
     * counting those as unaccounted-for would mean nothing is ever spare. */
    const meaningful = new Set([...MM_NAMED_FLAGS, ...judged]);
    const accountable = (v) =>
        v.flags.filter((f) => meaningful.has(f)).every((f) => judged.has(f));
    const met = (kept) => checks.every(({ wanted, rule }) =>
        kept.filter((v) => covers(v.flags, rule)).length >= wanted);

    if (!met(here)) return [];   // already short — nothing is spare

    let kept = here.slice();
    const drop = [];
    for (let i = here.length - 1; i >= 0; i -= 1) {
        if (!accountable(here[i])) continue;
        const without = kept.filter((v) => v !== here[i]);
        if (!met(without)) continue;
        kept = without;
        drop.push(here[i]);
    }
    return drop;
}

/**
 * Recount what is covered, from the boxes as they stand.
 *
 * Covered is what is committed: at the mission, on the way, or ticked. Not what
 * the plan would send — a plan nobody has acted on covers nothing, and a row
 * reading "covered" before a single box is ticked says nothing at all.
 *
 * Driven by the game's own change event, so ticking or unticking moves the
 * numbers without a redraw, whether it was YMCA or the player who did it.
 */
/** The fade lifts once the last row is in view, so nothing looks cut off when
 * there is nothing left below. */
function mmWatchScroll(panel) {
    const box = panel.querySelector('.mm-scroll');
    if (!box) return;
    const mark = () => {
        const end = box.scrollTop + box.clientHeight >= box.scrollHeight - 2;
        box.classList.toggle('mm-end', end);
    };
    box.addEventListener('scroll', mark, { passive: true });
    mark();
}

function mmRecount(panel, plan) {
    if (!plan || !plan.lines) return;
    const crew = mmKnownCrew();
    const ticked = [...document.querySelectorAll('.vehicle_checkbox:checked')].map((box) => ({
        has: (flag) => box.getAttribute(flag) === '1',
        water: Number(box.getAttribute('wasser_amount')) || 0,
        foam: Number(box.getAttribute('foam_amount_display')) || 0,
        /* The tanker's own percentage, off the game's own field — the same one
         * `calculateWaterBar` totals into `water_total_modifier`. */
        waterBonus: Number(box.getAttribute('water_modifier_raw'))
            || Number(box.getAttribute('water_modifier')) || 0,
        /* The box says which type it is; what that type seats was measured off
         * the game's own Crew column at some mission or other. */
        crew: crew[box.getAttribute('vehicle_type_id')] || 0,
    }));

    let allMet = true;
    let judged = false;
    for (const line of plan.lines) {
        if (line.unmatched) continue;
        judged = true;
        /* WATER IS COUNTED THE WAY THE PLAN PICKED IT, or the row would call a
         * send short that the game is about to accept: the loads add up and the
         * tankers' percentages raise the lot, scene and ticked together. Foam
         * and seats carry no such field, so they stay plain sums. */
        let byTick;
        if (line.carries === 'water_needed') {
            const base = (line.sceneBase || 0)
                + ticked.reduce((n2, v) => n2 + v.water, 0);
            const bonus = (line.sceneBonus || 0)
                + ticked.reduce((n2, v) => n2 + (v.water ? v.waterBonus : 0), 0);
            line.found = Math.round(base * (1 + bonus / 100));
            byTick = line.found - line.onScene;
        } else {
            byTick = line.unit
                ? ticked.reduce((n2, v) => n2 + (line.carries === 'personnel' ? v.crew
                    : v.foam), 0)
                : ticked.filter((v) => mmMeets(v, line.rule)).length;
            line.found = line.onScene + byTick;
        }
        line.ticked = byTick;
        if (line.found < line.wanted) allMet = false;

        const show = (attr, value) => {
            const cell = panel.querySelector(`[data-${attr}="${line.key}"]`);
            if (cell) cell.textContent = line.unit ? `${value} ${line.unit}` : String(value);
        };
        show('ticked', byTick);
        show('covered', line.found);
        /* Green the moment this line is met, red while it is not. One row at a
         * time, so a table half done reads as half done rather than as failing
         * — what is missing is the only thing still red. */
        panel.querySelector(`tr[data-row="${line.key}"]`)
            ?.classList.toggle('mm-row-ok', line.found >= line.wanted);
    }

    /* Seats follow the ticking the same way the counts do — by the player's own
     * numbers, and saying so. */
    const seatLine = panel.querySelector('[data-crew-seats]');
    if (seatLine) seatLine.innerHTML = mmSeatSentence();

    /* A refusal outranks the arithmetic. Every line can be covered and the send
     * still be turned down for want of trained crew, which is the one case
     * where the game knows something this table cannot work out — so the table
     * takes the game's answer and stops calling itself finished. */
    const refused = mmCrewRefusal(plan.crewTraining);
    if (refused) { allMet = false; judged = true; }
    const refusalLine = panel.querySelector('[data-crew-refusal]');
    if (refusalLine) {
        refusalLine.innerHTML = refused
            ? `<b class="text-danger">The game turned this send down for want of
               ${esc(refused.label)} crew</b>, so nothing here is called covered.
               Move crew onto a vehicle that is going and press the game's own
               Dispatch yourself.`
            : '';
    }

    /* The table is the surface with the answer on it, so it carries the answer:
     * red while anything is short, green once nothing is. */
    const table = panel.querySelector('.mm-table');
    if (table) {
        table.classList.toggle('mm-short', judged && !allMet);
        table.classList.toggle('mm-ok', judged && allMet);
    }
}

/**
 * Hand back what this panel is looking at.
 *
 * So a mission it cannot plan does not need the player to describe it: the
 * type, where the requirements came from, what was read and what was not, and
 * what is in range. Mission type ids and counts — the game's own constants —
 * and no mission text, addresses or names.
 */
/**
 * The shape of the two tables that only exist once something is happening.
 *
 * A vehicle already at a mission has no checkbox, so what it covers is looked
 * up by type — which is why an unowned type cannot be judged. Whether that is
 * actually necessary depends on what the game writes on those rows, and this
 * is that question asked once, of the real page.
 */
function mmTableShapes() {
    const shapes = {};
    for (const id of ['mission_vehicle_at_mission', 'mission_vehicle_driving',
        'vehicle_show_table_body_occupied']) {
        const table = document.getElementById(id);
        if (!table) { shapes[id] = 'not on this page'; continue; }
        const row = table.querySelector('tr[id^="vehicle_row"], tr.vehicle_select_table_tr, tbody tr');
        if (!row) { shapes[id] = 'present, no rows'; continue; }
        shapes[id] = {
            rowAttributes: [...row.attributes].map((a) =>
                `${a.name}=${/^\d+$/.test(a.value) ? '#' : a.value.slice(0, 12)}`),
            cells: [...row.cells].map((td) => ({
                classes: td.className || null,
                attributes: [...td.attributes].map((a) => a.name),
                controls: [...td.querySelectorAll('a,button,input')]
                    .map((el) => `${el.tagName.toLowerCase()}.${el.className}`.trim()),
            })),
        };
    }
    return shapes;
}

async function mmCopyState(ctx, plan, panel) {
    const page = mmReadMissionPage(false);
    const state = {
        note: 'mission type ids, counts and requirement keys only',
        ymca: YMCA.version,
        missionType: page.missionType,
        helpHref: page.helpHref ? page.helpHref.replace(/\d+/g, '#') : null,
        planned: !!plan?.requirements,
        requirementKeys: plan?.requirements ? Object.keys(plan.requirements) : [],
        source: plan?.fromHelpPage ? 'mission help page' : 'einsaetze.json',
        lines: (plan?.lines || []).map((l) => ({
            key: l.key, wanted: l.wanted, there: l.onScene, ticked: l.ticked, unmatched: !!l.unmatched,
        })),
        patients: mmPatientProbe(),
        /* WHAT THE PANEL ACTUALLY PICKED, and what it adds up to.
         *
         * Three rounds of "why did it send nine engines" arrived as reports
         * showing every line already covered and `ticked: 0` — the aftermath of
         * a plan, never the plan. A report that cannot answer the question it
         * was pressed for is a round trip spent for nothing. So the picked set
         * rides in it: how many of each type, the water and foam they carry
         * between them, and which requirement each one is answering. Type ids
         * and counts, the game's own constants, and no vehicle of the player's
         * named. */
        picked: plan?.pick ? {
            count: plan.pick.length,
            byType: plan.pick.reduce((n, v) => {
                n[v.typeId ?? 'unknown'] = (n[v.typeId ?? 'unknown'] || 0) + 1;
                return n;
            }, {}),
            water: plan.pick.reduce((n, v) => n + (v.water || 0), 0),
            foam: plan.pick.reduce((n, v) => n + (v.foam || 0), 0),
            answering: plan.pick.map((v) => (plan.lines || [])
                .filter((l) => l.rule && mmMeets(v, l.rule)).map((l) => l.key)),
        } : null,
        /* Whether the game refused this send for want of crew, and what the
         * danger alerts on the page are called. The wording is not carried —
         * the match is made against the trainings this mission itself names,
         * so a refusal that names none of them shows up here as an alert that
         * was seen and not read, which is the reading that needs looking at. */
        crewRefusal: plan?.crewTraining?.length ? {
            trainings: plan.crewTraining.map((t) => t.key),
            matched: mmCrewRefusal(plan.crewTraining)?.label || null,
            dangerAlerts: [...document.querySelectorAll('.alert-danger')]
                .map((a) => a.className),
        } : null,
        /* What is already at the mission, broken down. "You missed one that was
         * on route" cannot be answered by a `there` count alone: the rows the
         * panel saw, how many it could read a type off, and which types those
         * were are what says whether one went missing and where. Type ids are
         * the game's own constants. */
        scene: plan?.scene ? {
            atMission: plan.scene.atCount,
            onTheWay: plan.scene.drivingSeen,
            countingWhatIsOnTheWay: plan.scene.countDriving,
            counted: plan.scene.total - plan.scene.unknown,
            unknownType: plan.scene.unknown - plan.scene.unreadable,
            rowSaidNoType: plan.scene.unreadable,
            typeIds: plan.scene.typeIds,
            tankNotKnown: plan.scene.unknownTank,
        } : null,
        /* What each type carries, read off the selection table's checkboxes.
         * A water line that asks for the whole amount again is answered by
         * whichever of these is missing. */
        tanksByType: mmKnownTanks(),
        vehiclesInRange: page.rows.length,
        followUpTabPresent: page.followUpOffered,
        vehicleTypesLearnt: Object.keys(mmKnownTypes()).length,
        /* The types themselves, not just how many. A count cannot be added to
         * data/vehicle-types.json, and this is the button that gets pressed —
         * it is in the mission window, where the question comes up. Type ids,
         * names and flag names; nothing about the vehicles carrying them. */
        capabilitiesByType: mmKnownTypes(),
        typeNames: Object.fromEntries(Object.entries(mmLearntTypes())
            .filter(([, t]) => t.name).map(([id, t]) => [id, t.name])),
        /* Which of them this repo does not ship, so the gap is the answer
         * rather than something to work out by comparing two lists. */
        notInDataset: Object.keys(mmKnownTypes())
            .filter((id) => !MM_SHIPPED_TYPES[id]?.capabilities)
            .map(Number).sort((a, b) => a - b),
        panelPlaced: !!panel,
        /* The two tables nothing here has ever seen with something in them:
         * what is at the mission, and what the follow-up tab offers. If either
         * carries the capability flags the way a selection checkbox does, a
         * vehicle nobody owns can be counted without owning one. Attribute and
         * class names only — no captions, no addresses, no player names. */
        tablesNotSeenYet: mmTableShapes(),
    };
    await ctx.clipboard(JSON.stringify(state, null, 1), 'what this panel is seeing');
}

/**
 * Hand back one mission type, complete.
 *
 * A mission *type* is the game's static catalogue — no player, no place, no
 * instance of anything — so the whole record can go back as it is, and that is
 * what settles a requirement nobody has matched a vehicle attribute to yet.
 */
async function mmCopyType(ctx, typeId) {
    try {
        const missions = await ctx.rawGame('/einsaetze.json');
        const list = Array.isArray(missions) ? missions : Object.values(missions);
        const record = list.find((m) => String(m.id) === String(typeId));
        if (!record) { ctx.status('That mission type is not in the list.'); return; }
        await ctx.clipboard(JSON.stringify(record, null, 1), 'this mission type, complete');
        ctx.log.info('copied mission type', String(typeId));
    } catch (err) {
        ctx.status('Could not read the mission list.');
        ctx.log.warn('copy mission type failed', err.message);
    }
}


/**
 * The two silences, told apart.
 *
 * A requirement with no rule used to read one way: "left alone". But the game
 * naming that capability on its own dispatch-order form means the rule is not
 * what is missing — a vehicle is. That is the player's answer to give, and it
 * is a different sentence from "YMCA has never heard of this", which is ours.
 */
function mmUnmatchedNote(unmatched, ctx) {
    if (!unmatched.length) return '';
    const theirs = unmatched.filter((l) => l.gameFlag);
    const ours = unmatched.filter((l) => !l.gameFlag);
    const names = (list) => list.map((l) => ctx.esc(l.label)).join(', ');
    return `<div class="alert alert-warning" style="padding:6px 10px">
      ${theirs.length ? `<div><b>Nothing in range can do this:</b> ${names(theirs)}.
        ${theirs.length > 1 ? 'They are' : 'It is'} ${theirs.length > 1 ? '' : 'a '}capabilit${
    theirs.length > 1 ? 'ies' : 'y'} the game has, so what is missing is the vehicle.</div>` : ''}
      ${ours.length ? `<div${theirs.length ? ' style="margin-top:4px"' : ''}>
        <b>Left alone:</b> ${names(ours)}. Not a capability the game names, so YMCA does not
        know what answers ${ours.length > 1 ? 'them' : 'it'}.
        <button type="button" class="btn btn-xs btn-default" data-do="type">Copy this mission
          type</button> to have it added.</div>` : ''}
    </div>`;
}

function mmGamePanelHtml(plan, cfg, ctx) {
    if (!plan.requirements) {
        return `<div class="panel-body">
      <b>YMCA</b> — this mission's requirements could not be read, from the game's own list or
      from its requirements page.
      <button type="button" class="btn btn-default btn-xs" data-do="report">Copy what happened</button>
    </div>`;
    }

    const keys = mmKeys();
    const rows = plan.lines.map((l) => {
        // mmRecount fills this and keeps it filled, so it is never rendered stale.
        const cell = l.unmatched
            ? '?'
            : `<span data-covered="${ctx.esc(l.key)}">0</span>`;
        const num = 'text-right" style="width:1%;white-space:nowrap';
        return `<tr data-row="${ctx.esc(l.key)}">
      <td class="${num}">${ctx.fmt(l.wanted)}${l.unit ? ` ${l.unit}` : ''}</td>
      <td class="${num}">${l.onScene
        ? `${ctx.fmt(l.onScene)}${l.unit ? ` ${l.unit}` : ''}` : '&ndash;'}</td>
      <td class="${num}" data-ticked="${ctx.esc(l.key)}">0</td>
      <td class="${num};padding-right:10px"><b>${cell}</b></td>
      <td>${ctx.esc(l.label)}${mmIcon(l.icon)}${
    l.key === 'patients' && plan.patients
        ? `<small> &middot; ${plan.patients.count} patient${
            plan.patients.count > 1 ? 's' : ''}, as this window states</small>` : ''}${
    l.fromWindow ? '<small> &middot; as this window states</small>' : ''}${
    /* Nothing stated this one; it is here because the call cannot be finished
     * without it. The reason rides on the row rather than in the code alone. */
    l.addedHere ? `<small title="${ctx.esc(l.addedHere)}"> &middot; not in the game's own
        list</small>` : ''}${
    /* Nothing here maps this one; the flag was read off the checkboxes in this
     * very table. It counts the same, and it says which it is. */
    l.derived ? `<small title="matched on the game's own ${ctx.esc(l.derived)} flag,
        read from this table"> &middot; read from the page</small>` : ''}</td></tr>`;
    }).join('');

    const unmatched = plan.lines.filter((l) => l.unmatched);

    return `
    <div class="panel-heading">
      <b>YMCA</b> — what this mission needs
      ${plan.name ? `<small> · ${ctx.esc(plan.name)}</small>` : ''}
      ${plan.listedCredits ? `<span class="label label-default pull-right"
        title="what the game lists this kind of call as paying on average"
        >~${ctx.fmt(plan.listedCredits)} credits</span>` : ''}
    </div>
    <div class="panel-body">
      <div class="mm-scroll${plan.lines.length > MM_ROWS_SHOWN ? ' mm-more' : ''}">
        <table class="table table-condensed mm-table">
          <thead><tr>
            <th class="text-right">Wanted</th>
            <th class="text-right" title="already at the mission or on the way">There</th>
            <th class="text-right" title="ticked, not yet dispatched">Ticked</th>
            <th class="text-right" style="padding-right:10px">Covered</th>
            <th>Needs</th></tr></thead>
          <tbody>${rows}</tbody>
        </table>
      </div>

      ${plan.crewTraining?.length ? `<p class="text-muted" style="margin:0 0 8px">
        ${plan.crewTraining.map((t) => `Crew: <b>${t.count}</b> with
          ${ctx.esc(t.label)} training`).join('; ')} &mdash; they ride on whatever is sent.
        <span data-crew-seats>${mmSeatSentence()}</span>
        <span data-crew-refusal></span></p>` : ''}

      ${plan.patients && !plan.patients.measured ? `<p class="text-muted" style="margin:0 0 8px">
        The catalogue says this mission can produce up to <b>${plan.patients.count}</b> patients.
        This window has not said how many it has, so no ambulance is picked for them.</p>` : ''}

      ${plan.scene.unknownTank && plan.lines.some((l) => l.unit)
        ? `<p class="text-muted" style="margin:0 0 8px">
        ${plan.scene.unknownTank} already there or on the way ${plan.scene.unknownTank > 1
            ? 'carry tanks' : 'carries a tank'} this has not seen in a selection list yet, so
        whatever ${plan.scene.unknownTank > 1 ? 'they are' : 'it is'} carrying is not counted
        below.</p>` : ''}

      ${plan.crewUntrained ? `<p class="text-muted" style="margin:0 0 8px">
        Nothing in range carries the training this call is short of, so nothing is picked for
        it — a vehicle the game does not flag for it cannot be the one that brings it.</p>` : ''}

      ${plan.crewUnknown ? `<p class="text-muted" style="margin:0 0 8px">
        ${plan.crewUnknown} of the vehicles picked ${plan.crewUnknown > 1 ? 'have' : 'has'} never
        had ${plan.crewUnknown > 1 ? 'their crew' : 'its crew'} stated by the game, so
        ${plan.crewUnknown > 1 ? 'they count' : 'it counts'} as nobody on the crew line until
        one of that type turns up at a mission.</p>` : ''}

      ${plan.scene.total || plan.scene.drivingSeen ? `<p class="text-muted" style="margin:0 0 8px">
        ${[plan.scene.atCount ? `<b>${plan.scene.atCount}</b> at the mission` : '',
        plan.scene.drivingSeen ? `<b>${plan.scene.drivingSeen}</b> on the way${
            plan.scene.countDriving ? '' : ', not counted'}` : '']
        .filter(Boolean).join(', ')}${plan.scene.total ? ', subtracted above' : ''}${
        plan.scene.unknown ? ` — except ${plan.scene.unknown} ${plan.scene.unreadable
            === plan.scene.unknown ? 'whose row does not say which type it is'
            : 'whose type has not been seen in a selection list yet'}, so what they cover is
        not known` : ''}.</p>` : ''}

      ${mmUnmatchedNote(unmatched, ctx)}

      <!-- The switches stack on the left and the buttons keep the last line to
           themselves, hard right. They were one row: a fourth switch pushed the
           buttons off the end, and the one thing that must never move is the
           button the cursor is already on. -->
      <div class="mm-switches">
        ${mmSwitch('fastestFirst', 'Fastest first', cfg.fastestFirst !== false)}
        ${mmSwitch('ambulancePerPatient', 'Ambulance per patient', cfg.ambulancePerPatient !== false)}
        ${mmSwitch('countDriving', 'Count what is on the way', cfg.countDriving !== false)}
        ${mmSwitch('followUp', `Follow-up${plan.followUp ? ` (${plan.followUp})` : ''}`,
        cfg.followUp === true, !plan.followUpOffered)}
      </div>
      <div class="mm-buttons">
        ${plan.surplus.length ? `<button type="button" class="btn btn-warning btn-sm"
          data-do="cancel">Cancel ${plan.surplus.length} unused</button>` : ''}
        <button type="button" class="btn btn-success btn-sm" data-do="select"
          ${keys.tick ? `title="or press ${ctx.esc(keys.tick.toUpperCase())}"` : ''}
          >Tick ${plan.pick.length} vehicles${keys.tick
        ? ` <kbd class="mm-key">${ctx.esc(keys.tick)}</kbd>` : ''}</button>
        <button type="button" class="btn btn-default btn-sm" data-do="clear"
          ${keys.clear ? `title="or press ${ctx.esc(keys.clear.toUpperCase())}"` : ''}
          >Untick everything${keys.clear
        ? ` <kbd class="mm-key">${ctx.esc(keys.clear)}</kbd>` : ''}</button>
        <button type="button" class="btn btn-default btn-sm" data-do="report"
          title="copy what this panel is seeing">&#8942;</button>
      </div>
      ${plan.untimed ? `<small class="text-muted">${plan.untimed} of ${plan.available}
        have no travel time yet, ordered by distance until the game works them out</small>` : ''}
      <div class="alert alert-info" id="mm-panel-done" hidden style="padding:6px 10px;margin:8px 0 0">
        Ticked.</div>
      <div id="mma-note" hidden></div>
    </div>`;
}

/* --------------------------------------------------------------------------
 * RecruitDude — every station's hiring, on one screen.
 *
 * Hiring is four clicks per station: open the building, Hire new people, pick a
 * length, confirm. Across fourteen stations that is the whole evening, and it
 * is the same four clicks every time.
 *
 * IT USED TO DO THE PRESSING, AND THAT WAS THE WRONG SIDE OF THE LINE. It was
 * the one exception to "where there can be no undo, do not write at all", and
 * the exception did not hold: a tool that spends credits at fourteen stations
 * off one press is doing the playing, which is the same objection that took
 * MissionMagician Auto and HighFive Auto out in 0.0.51. What was actually
 * wanted was never the sending — it was not having to open fourteen buildings
 * to find the four clicks.
 *
 * So it lays the choice out and presses nothing. Each station's row carries the
 * game's own hire links, one per length, and the player clicks the one they
 * want. One click instead of four, no credits spent by anything here, and no
 * preview to stand in for an undo that never existed.
 *
 * Where the numbers come from, all of it the game's own:
 *   /api/buildings                  the stations, their type and their name
 *   /buildings/<id>                 "16 Employees", the artwork, the countdown
 *   /buildings/<id>/hire            where the game's own recruit buttons live
 *   /buildings/<id>/hire_do/1|2|3   recruit for one, two or three days
 *
 * The personnel count is not in /api/buildings, so it is read from each
 * station's own page — once, kept for the page load, and only for the stations
 * actually being shown.
 *
 * WHAT IS STILL OPEN: which element states a recruitment already running.
 * `data-end-time` is the game's own countdown attribute — it is on
 * `span#extension_countdown_<id>` — but whether personnel gets one, and under
 * what id, has never been seen from this side. So every countdown on the page
 * is read, one whose id names hiring is shown as Days left, and where none
 * does the column says so rather than showing a number off the wrong clock.
 * -------------------------------------------------------------------------- */

const RR_CACHE = new Map();

/** Buildings that employ people. A dispatch center has none to hire. */
const RR_NO_STAFF = new Set([1]);

/** An id that names hiring rather than an extension being built. */
const RR_HIRING_ID = /personnel|personal|staff|hire|schooling|recruit/i;

/**
 * What a station's page says about it.
 *
 * `Personnel:` is a `<dt>` and the count is the `<dd>` after it — "16
 * Employees" — so the number is taken from the pair rather than from a position
 * in the list, which moves as the game adds rows. The station's artwork is the
 * `img.pull-right` the page heads itself with.
 *
 * A countdown is `data-end-time`, which is the game's own attribute and not one
 * invented here. Every one on the page is collected with the id it sits on, so
 * a page that names its hiring countdown something nobody here has heard of can
 * still be read next time rather than argued about.
 */
async function rrRead(buildingId) {
    if (RR_CACHE.has(buildingId)) return RR_CACHE.get(buildingId);
    const load = (async () => {
        const res = await fetch(`/buildings/${buildingId}`, { credentials: 'same-origin' });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const doc = new DOMParser().parseFromString(await res.text(), 'text/html');

        let staff = null;
        for (const dt of doc.querySelectorAll('dt')) {
            if (!/personnel/i.test(dt.textContent)) continue;
            const dd = dt.nextElementSibling;
            const n = dd && /(\d[\d,.]*)\s*(employee|personnel|people)/i.exec(dd.textContent);
            if (n) { staff = Number(n[1].replace(/[,.]/g, '')); break; }
        }
        const art = doc.querySelector('img.pull-right[src*="/images/"]')?.getAttribute('src') || null;
        // The game only offers the link when the station can actually hire.
        const canHire = !!doc.querySelector(`a[href$="/buildings/${buildingId}/hire"]`)
            || !!doc.querySelector('a[href*="/hire"]');

        const clocks = [];
        for (const el of doc.querySelectorAll('[data-end-time]')) {
            clocks.push({ id: el.id || null, endsAt: el.getAttribute('data-end-time') });
        }
        const hiring = clocks.find((c) => c.id && RR_HIRING_ID.test(c.id)) || null;
        return { staff, art, canHire, clocks, hiring };
    })().catch((err) => ({ staff: null, art: null, canHire: true, clocks: [], hiring: null,
        why: err.message }));
    RR_CACHE.set(buildingId, load);
    return load;
}

/** The lengths the game sells for credits, as its own links word them. */
const RR_DAYS = [
    { days: 1, label: '1 day' },
    { days: 2, label: '2 days' },
    { days: 3, label: '3 days' },
];

/**
 * Days left on a countdown the game stated, or null.
 *
 * `data-end-time` has only ever been seen as milliseconds since the epoch, so
 * anything that does not read as a time in the future is left as no answer
 * rather than turned into a number.
 */
function rrDaysLeft(endsAt) {
    const at = Number(endsAt);
    if (!Number.isFinite(at)) return null;
    const ms = at - Date.now();
    if (ms <= 0) return null;
    return Math.ceil(ms / 86400000);
}

YMCA.register({
    id: 'recruitroom',
    optional: true,
    defaultOn: true,
    title: 'RecruitDude',
    tagline: 'Hiring, every station at once',

    description: 'Every station that employs people, with its crew count and the game’s own '
        + 'recruit links for one, two or three days side by side. It does not hire for you — '
        + 'spent credits do not come back, so the link that costs money stays yours to click.',

    async mount(el, ctx) {
        const buildings = await ctx.game('/api/buildings');
        const cfg = ctx.store.read('cfg', {});

        const centres = buildings.filter((b) =>
            buildings.some((x) => x.leitstelle_building_id === b.id));
        const area = cfg.area && centres.some((c) => String(c.id) === String(cfg.area))
            ? String(cfg.area) : '';

        const stations = buildings
            .filter((b) => !RR_NO_STAFF.has(b.building_type))
            .filter((b) => !area || String(b.leitstelle_building_id) === area)
            .sort((a, b) => (a.caption || '').localeCompare(b.caption || ''));

        el.innerHTML = `
      <div class="ymca-card">
        <b>${stations.length} station${stations.length === 1 ? '' : 's'}</b>
        <p class="ymca-sub" style="margin:4px 0 10px">Crew counts come from each station's own
          page. The recruit links are the game's own &mdash; one click instead of four, and
          <b>nothing here spends a credit until you click one</b>.</p>
        ${centres.length ? `<label class="ymca-dim">Dispatch center
          <select data-cfg="area" style="margin-left:6px">
            <option value="">Everything you own</option>
            ${centres.map((c) => `<option value="${c.id}"${String(c.id) === area ? ' selected' : ''}
              >${ctx.esc(c.caption || `Center ${c.id}`)}</option>`).join('')}
          </select></label>` : ''}
      </div>

      <div class="ymca-card">
        <table id="rr-table" style="margin-top:4px">
          <thead><tr><th style="width:1%"></th><th>Station</th>
            <th class="ymca-num">Crew</th>
            <th class="ymca-num" title="From the game's own countdown, where it states one"
              >Days left</th>
            <th>Recruit for</th></tr></thead>
          <tbody>${stations.map((b) => `
            <tr data-station="${b.id}">
              <td class="rr-art"></td>
              <td><a href="/buildings/${b.id}" target="_blank" rel="noopener"
                >${ctx.esc(b.caption || `Building ${b.id}`)}</a></td>
              <td class="ymca-num rr-staff"><span class="ymca-dim">&hellip;</span></td>
              <td class="ymca-num rr-left"><span class="ymca-dim">&hellip;</span></td>
              <td class="rr-do">${RR_DAYS.map((d) => `<a class="ymca-btn"
                href="/buildings/${b.id}/hire_do/${d.days}" target="_blank" rel="noopener"
                >${d.label}</a>`).join(' ')}</td>
            </tr>`).join('')}
          </tbody>
        </table>
        ${stations.length ? '' : '<p class="ymca-dim">No station in this dispatch center hires.</p>'}
      </div>

      <div class="ymca-note">Each link is the game's own <code>hire_do</code>, opened in a new
        tab. <b>Credits spent on people do not come back</b>, and nothing here clicks one for
        you &mdash; that is the whole reason this is a layout rather than a queue.</div>`;

        el.addEventListener('change', (e) => {
            if (e.target.dataset.cfg !== 'area') return;
            ctx.store.write('cfg', Object.assign(ctx.store.read('cfg', {}), { area: e.target.value }));
            YMCA.modules.find((m) => m.id === 'recruitroom').mount(el, ctx);
        });

        /* One station at a time, so a big alliance of stations does not arrive
         * as fourteen requests at once. Each row fills itself in as it lands. */
        let noClock = 0;
        const clockIds = new Set();
        for (const b of stations) {
            const row = el.querySelector(`tr[data-station="${b.id}"]`);
            if (!row) continue;
            /* eslint-disable no-await-in-loop */
            const info = await rrRead(b.id);
            const cell = row.querySelector('.rr-staff');
            if (cell) {
                cell.innerHTML = info.staff === null
                    ? '<span class="ymca-dim">&ndash;</span>'
                    : `<b>${ctx.fmt(info.staff)}</b>`;
            }
            const left = row.querySelector('.rr-left');
            if (left) {
                const days = info.hiring ? rrDaysLeft(info.hiring.endsAt) : null;
                left.innerHTML = days === null
                    ? '<span class="ymca-dim" title="this page states no hiring countdown">&ndash;</span>'
                    : `<b>${ctx.fmt(days)}</b>`;
                if (days === null) noClock += 1;
            }
            for (const c of info.clocks || []) if (c.id) clockIds.add(c.id.replace(/\d+/g, '#'));
            const art = row.querySelector('.rr-art');
            if (art && info.art) {
                art.innerHTML = `<img src="${ctx.esc(info.art)}" width="24" height="24" alt=""
                  style="vertical-align:-6px">`;
            }
            await ctx.sleep(80);
        }
        /* Whether a station page states a hiring countdown at all has never been
         * seen from this side, so what the pages did carry is written down for
         * the next read rather than left as a column of dashes nobody can act on. */
        ctx.store.write('clocks', { at: Date.now(), noCountdown: noClock,
            countdownIds: [...clockIds].sort() });
        ctx.status(`${stations.length} stations.`);
    },
});

/* --------------------------------------------------------------------------
 * SimpleAAO — the dispatch orders you would have built by hand.
 *
 * A dispatch order is a filter the game builds in its own editor: "send three
 * fire engines", "send one K-9 unit". Building one is a page of seventy-odd
 * fields where two of them matter, and then you do it again for two engines,
 * and again for four. Nobody builds the twenty orders they actually want.
 *
 * THE FORM SAYS HOW, AND NOTHING HERE IS GUESSED AT. `/aaos/new` carries one
 * field per capability the game has a word for, and each one is
 * `<input type="number" name="aao[fire]">` — so an order is a **count** per
 * capability, not a tick. That is the whole feature: pick the class the game
 * names, pick how many, and the order is the form the game would have posted.
 *
 * Every word on this page is the game's own. The groups are the editor's own
 * tabs (Fire, Rescue, Police, FBI, Water Rescue, Brush, Tow Trucks, Mountain
 * Rescue); the rows are its own labels — "Police Motorcycle", "Utility Truck",
 * "Fire Engine". Nothing is translated and no list of classes is kept here, so
 * a capability the game adds next month turns up on its own.
 *
 * IT WRITES, AND IT CAN BE UNDONE — which is why it may write at all. A
 * dispatch order is a thing the game lets you delete; credits and an alarm are
 * not. So the rule is met the way the rule asks: a preview that names exactly
 * what is about to be created, a confirmation before anything is sent, and
 * every order it made written down here with the game's own link to it, so
 * removing one is a click rather than a hunt.
 *
 * NOTHING IS HAND-BUILT. The FormData comes out of the real form fetched from
 * `/aaos/new`, and two fields are replaced — the caption and the one count. The
 * CSRF token, the category, the colours and every other setting go back exactly
 * as the game wrote them. That is the route SwitchDispatchCenter and the
 * Renamer already take.
 * -------------------------------------------------------------------------- */

/** The editor, fetched once for the page load: the form is the vocabulary. */
let SA_FORM = null;

async function saEditor() {
    if (SA_FORM) return SA_FORM;
    SA_FORM = (async () => {
        const res = await fetch('/aaos/new', { credentials: 'same-origin' });
        if (!res.ok) throw new Error(`the dispatch-order editor answered HTTP ${res.status}`);
        const doc = new DOMParser().parseFromString(await res.text(), 'text/html');
        const form = doc.querySelector('form[action*="aao"], form');
        if (!form) throw new Error('the dispatch-order editor carried no form');

        /* A DOMParser leaves `form.action` empty where the page had none, which
         * has cost this repo a release once already. The attribute is read, and
         * where the game states none the form is posted back to where it came
         * from rather than to a path made up here. */
        const action = form.getAttribute('action') || '/aaos/new';

        /* The tabs ARE the groups, named by the game. `#tabs` links point at the
         * panels by id, so the two are paired without naming either. */
        const tabName = new Map();
        for (const a of doc.querySelectorAll('a[href^="#"][data-toggle="tab"]')) {
            tabName.set(a.getAttribute('href').slice(1), a.textContent.trim());
        }

        const groups = [];
        for (const panel of doc.querySelectorAll('.tab-pane[id]')) {
            const rows = [];
            for (const input of panel.querySelectorAll('input[type="number"][name^="aao["]')) {
                const key = /^aao\[(.+)\]$/.exec(input.getAttribute('name'))?.[1];
                if (!key) continue;
                const label = panel.querySelector(`label[for="${input.id}"]`)?.textContent.trim();
                rows.push({ key, label: label || key, field: input.getAttribute('name') });
            }
            if (rows.length) {
                groups.push({ id: panel.id, name: tabName.get(panel.id) || panel.id, rows });
            }
        }
        if (!groups.length) throw new Error('the editor named no vehicle class at all');
        return { doc, form, action, groups };
    })().catch((err) => { SA_FORM = null; throw err; });
    return SA_FORM;
}

/**
 * Create one order, out of the game's own form.
 *
 * Two fields are replaced and nothing else is touched, so whatever the editor
 * would have sent by default is what gets sent.
 */
async function saCreate(editor, field, count, caption) {
    const data = new FormData(editor.form);
    data.set('aao[caption]', caption);
    data.set(field, String(count));
    const res = await fetch(editor.action, {
        method: (editor.form.getAttribute('method') || 'post').toUpperCase(),
        credentials: 'same-origin',
        body: data,
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    /* Where the game redirected to is its own page for what it just made, so
     * the way back to delete it is a reading rather than a path invented here. */
    return res.url || null;
}

YMCA.register({
    id: 'simpleaao',
    optional: true,
    defaultOn: true,
    title: 'SimpleAAO',
    tagline: 'Dispatch orders, one click each',

    description: 'The dispatch orders you would otherwise build one seventy-field page at a '
        + 'time. Pick a vehicle class the game names and how many of it, and the order is '
        + 'created from the game’s own editor. Every one it makes is listed here with the link '
        + 'to delete it again.',

    async mount(el, ctx) {
        el.innerHTML = '<p class="ymca-dim">Reading the game’s dispatch-order editor…</p>';
        let editor;
        try {
            editor = await saEditor();
        } catch (err) {
            el.innerHTML = `<div class="ymca-note bad">${ctx.esc(err.message)}. Nothing can be
        offered here until it does &mdash; every class and every group on this page is read off
        that form rather than kept in a list.</div>`;
            return;
        }

        const cfg = ctx.store.read('cfg', {});
        const open = editor.groups.some((g) => g.id === cfg.group) ? cfg.group : editor.groups[0].id;
        const made = ctx.store.read('made', []);

        const group = editor.groups.find((g) => g.id === open);
        const counts = [1, 2, 3, 4, 5];

        el.innerHTML = `
      <div class="ymca-card">
        <b>${editor.groups.length} groups, ${editor.groups.reduce((n, g) => n + g.rows.length, 0)}
          vehicle classes</b>
        <p class="ymca-sub" style="margin:4px 0 10px">All of it read off the game's own editor,
          groups and names alike. A number is how many of that class the order sends, which is
          what the editor's own field counts.</p>
        <div>${editor.groups.map((g) => `<button class="ymca-btn${g.id === open ? ' primary' : ''}"
          data-group="${ctx.esc(g.id)}">${ctx.esc(g.name)}</button>`).join(' ')}</div>
      </div>

      <div class="ymca-card">
        <table>
          <thead><tr><th>Vehicle class</th><th>Create an order for</th></tr></thead>
          <tbody>${group.rows.map((r) => `
            <tr>
              <td>${ctx.esc(r.label)} <small class="ymca-dim">${ctx.esc(r.key)}</small></td>
              <td>${counts.map((n) => `<button class="ymca-btn" data-make="${ctx.esc(r.field)}"
                data-n="${n}" data-label="${ctx.esc(r.label)}">${n}</button>`).join(' ')}</td>
            </tr>`).join('')}
          </tbody>
        </table>
        <p class="ymca-sub" style="margin:10px 0 0">Each button says what it is about to create
          and waits to be told yes. An order <b>can</b> be deleted again &mdash; that is why this
          one may write at all.</p>
        <span class="ymca-status" id="sa-status"></span>
      </div>

      <div class="ymca-card">
        <b>Made from here</b>
        <p class="ymca-sub" style="margin:4px 0 8px">Every order this made, with the game's own
          link to it. Deleting one is the game's own page, not a button here.</p>
        <div id="sa-made">${made.length ? `<table><tbody>${made.map((m) => `
          <tr><td>${ctx.esc(m.caption)}</td>
            <td class="ymca-dim">${ctx.esc(m.field)} = ${ctx.esc(String(m.count))}</td>
            <td>${m.url ? `<a href="${ctx.esc(m.url)}" target="_blank" rel="noopener"
              >open it</a>` : '<span class="ymca-dim">no link came back</span>'}</td></tr>`)
            .join('')}</tbody></table>`
            : '<span class="ymca-dim">Nothing yet.</span>'}</div>
        ${made.length ? '<button class="ymca-btn" data-forget>Clear this list</button>' : ''}
      </div>`;

        const say = (text) => {
            const at = el.querySelector('#sa-status');
            if (at) at.textContent = text;
            ctx.status(text);
        };

        el.addEventListener('click', async (e) => {
            const tab = e.target.closest('[data-group]');
            if (tab) {
                ctx.store.write('cfg', Object.assign(ctx.store.read('cfg', {}),
                    { group: tab.dataset.group }));
                YMCA.modules.find((m) => m.id === 'simpleaao').mount(el, ctx);
                return;
            }
            if (e.target.closest('[data-forget]')) {
                /* The list, not the orders: nothing here deletes anything in the
                 * game, and a button that cleared both would be lying about one. */
                ctx.store.write('made', []);
                YMCA.modules.find((m) => m.id === 'simpleaao').mount(el, ctx);
                return;
            }

            const go = e.target.closest('[data-make]');
            if (!go) return;
            const field = go.dataset.make;
            const count = Number(go.dataset.n);
            const caption = `${go.dataset.label} ${count}`;

            /* The preview names exactly what is about to exist, and the yes is
             * the player's. Nothing is sent before it. */
            const ok = confirm(`Create a dispatch order in your game:\n\n`
                + `  Name:  ${caption}\n  Sends: ${count} × ${go.dataset.label}\n\n`
                + 'Everything else comes from the game’s own editor unchanged. '
                + 'You can delete it again in the game.');
            if (!ok) return;

            go.disabled = true;
            say(`Creating ${caption}…`);
            try {
                const url = await saCreate(editor, field, count, caption);
                const kept = ctx.store.read('made', []);
                kept.unshift({ caption, field, count, url, at: Date.now() });
                ctx.store.write('made', kept.slice(0, 200));
                ctx.log.info('dispatch order created', `${field}=${count}`);
                say(`${caption} created.`);
                YMCA.modules.find((m) => m.id === 'simpleaao').mount(el, ctx);
            } catch (err) {
                go.disabled = false;
                ctx.log.warn('dispatch order failed', err.message);
                say(`It was refused: ${err.message}`);
            }
        });

        ctx.status(`${group.rows.length} classes in ${group.name}.`);
    },
});

/* --------------------------------------------------------------------------
 * HeatSeeker — where your cover is thick and where it is thin.
 *
 * A fleet list says what you own; it does not say where it is. Fourteen
 * stations and eighty vehicles read as a table of numbers, and the question
 * nobody can answer from that table is the one worth asking: pick a kind of
 * vehicle, and where on the map is there none of it?
 *
 * EVERYTHING HERE IS ALREADY IN THE GAME'S OWN JSON, so nothing was captured
 * for it. `/api/buildings` carries `latitude` and `longitude` per station along
 * with `leitstelle_building_id`; `/api/vehicles` carries `building_id` and
 * `vehicle_type`. Vehicles per station per type, and where each station is.
 *
 * THE SCALE IS RELATIVE TO THIS MAP AND SAYS SO. There is no figure anywhere in
 * the game for what "good cover" is, so the deepest shade is the best-covered
 * spot *on this player's own map* rather than a standard. Inventing a threshold
 * would be a guess wearing a colour.
 *
 * WHY THE DEFAULT IN THE WINDOW IS NOT RED-TO-GREEN, although that is what was
 * asked for: run over the documented status palette, `#0ca30c` against
 * `#d03b3b` comes back at **ΔE 4.1 under deuteranopia** — below the floor of 6,
 * which is to say the two ends of the scale are the one pair a colour-blind
 * reader cannot tell apart. Magnitude takes one hue, light to dark, so that is
 * the default there. Red to green is what the game's own map opens on, because
 * it is what was pictured and because the count is written on every station —
 * the second encoding that measurement asks for.
 *
 * A HEATMAP IS A SUM OF RADIAL KERNELS, NOT A CIRCLE PER STATION. The first
 * version drew a coarse grid in banded colours, which reads as a blob that
 * grows and runs into the next blob rather than as a quantity. What is drawn
 * now is the textbook thing: one radial fall-off per station, ADDED together
 * into a mask, and the mask coloured through a continuous ramp. Three things
 * follow from doing it that way and all three are the point —
 *
 *   - the sum is the reading. Two stations near each other are hotter than
 *     either alone, which is what "how much cover is here" means;
 *   - the kernel is compactly supported, `(1 - t²)^focus`, so the wash STOPS at
 *     the distance the player set instead of trailing off for ever. Raising the
 *     exponent hugs the stations more tightly, and that is a setting;
 *   - the colour is continuous, sampled from the browser's own gradient
 *     interpolation at 256 steps, so there are no bands to mistake for
 *     thresholds nobody set.
 *
 * AND THE NORMALISATION IS THE MAP'S, NOT THE SCREEN'S. Dividing by the hottest
 * cell on screen meant the colours changed as you panned — the same station
 * dark green alone and orange beside a bigger one. The peak is taken over every
 * station in play, in kilometres, so it does not move when the view does.
 * -------------------------------------------------------------------------- */

/** The documented sequential ramp: one hue, light to dark, for magnitude. */
const HM_BLUE = ['#e7f1fd', '#cde2fb', '#9ec5f4', '#6da7ec', '#3987e5', '#256abf', '#184f95', '#0d366b'];
/* The status palette's own steps, for the red-to-green that was asked for —
 * with a deeper green past the top of it. Five steps left "well covered" and
 * "covered twice over" the same colour, and the difference between those two is
 * exactly what somebody looking at their own map wants to see. */
const HM_WARM = ['#d03b3b', '#e8714a', '#f5a623', '#d6c916', '#8fbf1a', '#0ca30c', '#0a7a33', '#07532c'];

const HM_SCALES = {
    blue: { label: 'One hue, light to dark', steps: HM_BLUE },
    warm: { label: 'Red to green', steps: HM_WARM },
};

/* How tightly the wash hugs the station. The exponent on `(1 - t²)`: 1 is a
 * soft dome that fills the whole reach, 7 is a tight core with a thin skirt.
 * It is a setting because how far a vehicle counts for is already the player's
 * and this is the other half of the same question. */
const HM_FOCUS = {
    soft: { label: 'Soft, fills the whole reach', p: 1.5 },
    balanced: { label: 'Balanced', p: 2.5 },
    tight: { label: 'Tight around the station', p: 4 },
    tighter: { label: 'Tightest', p: 7 },
};

/** Kilometres between two points on the globe, near enough for a city. */
function hmKm(aLat, aLon, bLat, bLon) {
    const R = 6371;
    const rad = Math.PI / 180;
    const dLat = (bLat - aLat) * rad;
    const dLon = (bLon - aLon) * rad;
    const lat = ((aLat + bLat) / 2) * rad;
    const x = dLon * Math.cos(lat);
    return Math.sqrt(dLat * dLat + x * x) * R;
}

/* ------------------------------------------------------------ the gradient */

/**
 * The ramp as 256 samples, interpolated by the browser rather than by us.
 *
 * A list of seven colours drawn as seven bands reads as seven thresholds, and
 * there are no thresholds here. Painting the list into a one-pixel-tall canvas
 * gradient and reading it back gives a continuous ramp for nothing, and it is
 * the same interpolation CSS would do with the same stops.
 */
const hmRamps = new Map();
function hmRamp(steps) {
    const key = steps.join(',');
    if (hmRamps.has(key)) return hmRamps.get(key);
    const c = document.createElement('canvas');
    c.width = 256;
    c.height = 1;
    const g = c.getContext('2d');
    const grad = g.createLinearGradient(0, 0, 256, 0);
    steps.forEach((s, i) => grad.addColorStop(steps.length === 1 ? 0 : i / (steps.length - 1), s));
    g.fillStyle = grad;
    g.fillRect(0, 0, 256, 1);
    const lut = g.getImageData(0, 0, 256, 1).data;
    hmRamps.set(key, lut);
    return lut;
}

/** The ramp's colour at t, as the three channels. */
function hmAt(lut, t) {
    const i = Math.max(0, Math.min(255, Math.round((t > 0 ? t : 0) * 255))) * 4;
    return [lut[i], lut[i + 1], lut[i + 2]];
}

function hmRgb(c) { return `rgb(${Math.round(c[0])},${Math.round(c[1])},${Math.round(c[2])})`; }

/** WCAG relative luminance, so "readable" is a measurement and not a feeling. */
function hmLum(r, g, b) {
    const f = (c) => {
        const v = c / 255;
        return v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4;
    };
    return 0.2126 * f(r) + 0.7152 * f(g) + 0.0722 * f(b);
}

/**
 * The same colour, darkened until it reads on white.
 *
 * The badge is white so the figure is legible over any tile, which means the
 * ramp's own yellow would be a number nobody can read. Darkening in steps until
 * the contrast ratio clears 4.5:1 keeps the shade that count earned while
 * making it legible, rather than swapping in a colour of YMCA's own.
 */
function hmInk(c) {
    let [r, g, b] = c;
    for (let i = 0; i < 14; i += 1) {
        if (1.05 / (hmLum(r, g, b) + 0.05) >= 4.5) break;
        r *= 0.82; g *= 0.82; b *= 0.82;
    }
    return hmRgb([r, g, b]);
}

/* -------------------------------------------------------------- the drawing */

/** Canvases reused between frames, because allocating one per frame is not free. */
const hmScratches = new Map();
function hmScratch(key, w, h) {
    let c = hmScratches.get(key);
    if (!c) { c = document.createElement('canvas'); hmScratches.set(key, c); }
    if (c.width !== w) c.width = w;
    if (c.height !== h) c.height = h;
    return c;
}

/**
 * The hottest a point on this map can be, in the map's own units.
 *
 * Taken at the stations, because the sum of kernels peaks where the kernels are
 * centred. In kilometres, so it is the same number at every zoom and the
 * colours do not change under a pan — which is the fault it was written to fix.
 */
function hmPeak(stations, radius, focus) {
    let peak = 0;
    for (const a of stations) {
        let sum = 0;
        for (const b of stations) {
            const t = hmKm(a.lat, a.lon, b.lat, b.lon) / radius;
            if (t < 1) sum += b.n * ((1 - t * t) ** focus);
        }
        if (sum > peak) peak = sum;
    }
    return peak || 1;
}

/**
 * Paint the heat itself: one radial fall-off per station, added up.
 *
 * `globalCompositeOperation = 'lighter'` is what makes it a sum rather than a
 * pile of discs — it adds the source into the destination, so where two
 * stations' reach overlaps the mask carries both. What accumulates is the
 * ALPHA channel, which is why the colouring pass reads that and not the red.
 *
 * The mask is drawn at a third of the size and blown back up. That is not a
 * corner cut: scaling up with smoothing is a bilinear filter, which is exactly
 * the smoothing this wants, done by the browser at no cost — and it takes the
 * per-pixel colouring loop from a million iterations a frame to a hundred
 * thousand.
 */
function hmHeat(g, w, h, pts, opts) {
    const { peak, steps, opacity, rPx, focus } = opts;
    if (!pts.length || !(rPx > 0) || !(w > 0) || !(h > 0)) return;

    const s = 1 / 3;
    const mw = Math.max(1, Math.ceil(w * s));
    const mh = Math.max(1, Math.ceil(h * s));
    const mask = hmScratch('mask', mw, mh);
    const mg = mask.getContext('2d', { willReadFrequently: true });
    mg.setTransform(1, 0, 0, 1, 0, 0);
    mg.clearRect(0, 0, mw, mh);
    mg.globalCompositeOperation = 'lighter';

    const rr = rPx * s;
    /* The kernel as gradient stops. Twelve is enough that the browser's own
     * interpolation between them is invisible, and the last one is a real zero
     * so the reach ends where the player said it does. */
    for (const p of pts) {
        const x = p.x * s;
        const y = p.y * s;
        if (x < -rr || y < -rr || x > mw + rr || y > mh + rr) continue;
        const grad = mg.createRadialGradient(x, y, 0, x, y, rr);
        for (let i = 0; i <= 12; i += 1) {
            const t = i / 12;
            grad.addColorStop(t, `rgba(255,255,255,${((1 - t * t) ** focus).toFixed(4)})`);
        }
        mg.globalAlpha = Math.min(1, p.n / peak);
        mg.fillStyle = grad;
        mg.beginPath();
        mg.arc(x, y, rr, 0, Math.PI * 2);
        mg.fill();
    }
    mg.globalCompositeOperation = 'source-over';
    mg.globalAlpha = 1;

    const img = mg.getImageData(0, 0, mw, mh);
    const d = img.data;
    const lut = hmRamp(steps);
    for (let i = 0; i < d.length; i += 4) {
        const v = d[i + 3];
        if (!v) { d[i] = 0; d[i + 1] = 0; d[i + 2] = 0; continue; }
        const j = v * 4;
        d[i] = lut[j];
        d[i + 1] = lut[j + 1];
        d[i + 2] = lut[j + 2];
        /* Fades in over the coldest sliver, so the far edge of the reach is a
         * fade rather than a line drawn round every station. */
        d[i + 3] = Math.round(255 * opacity * Math.min(1, v / 30));
    }
    mg.putImageData(img, 0, 0);

    g.imageSmoothingEnabled = true;
    g.imageSmoothingQuality = 'high';
    g.drawImage(mask, 0, 0, mw, mh, 0, 0, w, h);
}

/**
 * The station and what it counted, in a badge that reads over any tile.
 *
 * White fill, a ring in the shade that count earned, and the figure in the same
 * shade darkened until it clears 4.5:1 against the white. The colour is still
 * the reading; the badge is only what makes it legible over a map that is
 * already full of things.
 */
function hmBadges(g, pts, lut, peak) {
    g.font = 'bold 12px "Helvetica Neue", Helvetica, Arial';
    g.textAlign = 'center';
    g.textBaseline = 'middle';
    for (const p of pts) {
        const colour = hmAt(lut, Math.min(1, p.n / peak));
        const label = String(p.n);
        const r = Math.max(9, g.measureText(label).width / 2 + 6);
        g.beginPath();
        g.arc(p.x, p.y, r, 0, Math.PI * 2);
        g.fillStyle = '#fff';
        g.fill();
        g.lineWidth = 2.5;
        g.strokeStyle = hmRgb(colour);
        g.stroke();
        g.fillStyle = hmInk(colour);
        g.fillText(label, p.x, p.y);
    }
}

/**
 * What is at each station, by type.
 *
 * A station with no coordinates is counted and named rather than plotted: the
 * game states them for every building this has seen, and if one day it does not
 * that is worth knowing rather than quietly dropping the station.
 */
function hmStations(buildings, vehicles) {
    const byId = new Map();
    for (const b of buildings || []) {
        byId.set(String(b.id), {
            id: String(b.id),
            name: b.caption || `Building ${b.id}`,
            centre: b.leitstelle_building_id == null ? '' : String(b.leitstelle_building_id),
            lat: Number(b.latitude),
            lon: Number(b.longitude),
            byType: new Map(),
            total: 0,
        });
    }
    for (const v of vehicles || []) {
        const at = byId.get(String(v.building_id));
        if (!at) continue;
        const t = String(v.vehicle_type ?? '');
        at.byType.set(t, (at.byType.get(t) || 0) + 1);
        at.total += 1;
    }
    const placed = [];
    const noPlace = [];
    for (const s of byId.values()) {
        if (!s.total) continue;
        if (Number.isFinite(s.lat) && Number.isFinite(s.lon)) placed.push(s);
        else noPlace.push(s.name);
    }
    return { placed, noPlace };
}

/**
 * The lists to tick: the types this fleet holds and the centres they answer to.
 *
 * Worked out in one place because there are two pages of tick boxes now — the
 * window's and the one on the game's own map — and two copies of this would
 * drift the first time a type was named.
 */
function hmChoices(buildings, vehicles) {
    const { placed, noPlace } = hmStations(buildings, vehicles);
    /* The names come from the store every module writes to, so a type named
     * once is named here too. A type nothing has named is still offered — by
     * its id, which is what the game calls it. */
    let names = {};
    try { names = JSON.parse(localStorage.getItem('ymca-vehicle-types')) || {}; } catch (e) { /* none */ }
    const nameOf = (id) => (names[id] && (names[id].name || names[id])) || `Type ${id}`;
    const types = [...new Set(placed.flatMap((s) => [...s.byType.keys()]))]
        .sort((a, b) => String(nameOf(a)).localeCompare(String(nameOf(b))));
    const centres = (buildings || [])
        .filter((b) => (buildings || []).some((x) => String(x.leitstelle_building_id) === String(b.id)))
        .map((b) => ({ id: String(b.id), name: b.caption || `Center ${b.id}` }));
    /* A STATION ANSWERING TO NO CENTRE IS STILL A STATION. Without an entry of
     * its own it vanished the moment the list was filtered at all, which reads
     * as cover that is not there — the one thing this page must not get wrong.
     * It is offered by the game's own words for it. */
    if (centres.length && placed.some((s) => !s.centre)) {
        centres.push({ id: '', name: '— not assigned —' });
    }
    const countOf = (t) => placed.reduce((n, s) => n + (s.byType.get(t) || 0), 0);
    return { placed, noPlace, types, centres, nameOf, countOf };
}

/** The settings both faces read, with every default in one place. */
function hmSettings(cfg) {
    return {
        radius: Number(cfg.radius) || 8,
        focus: HM_FOCUS[cfg.focus] ? cfg.focus : 'tight',
        scale: HM_SCALES[cfg.scale] ? cfg.scale : 'blue',
        mapScale: HM_SCALES[cfg.mapScale] ? cfg.mapScale : 'warm',
        opacity: Number.isFinite(Number(cfg.opacity)) ? Number(cfg.opacity) : 0.55,
    };
}

YMCA.register({
    id: 'heatmap',
    optional: true,
    defaultOn: true,
    title: 'HeatSeeker',
    tagline: 'Where your cover is thin',

    description: 'A map of your own stations shaded by how many of a chosen kind of vehicle '
        + 'can reach each spot. Tick the types and the dispatch centres to see cover for all of '
        + 'it or one branch at a time, in here or on the game’s own map. The scale is '
        + 'relative to your own map, not a standard.',

    /* An injection cannot be un-run, so what it put in the game's page is taken
     * back here: the control, the canvas and the tick boxes all go. */
    onSwitch(on) {
        if (on) return;
        hmClear();
        document.getElementById(HM_BTN_ID)?.remove();
    },

    async mount(el, ctx) {
        el.innerHTML = '<p class="ymca-dim">Reading your stations and your fleet…</p>';
        const [buildings, vehicles] = await Promise.all([
            ctx.game('/api/buildings'), ctx.game('/api/vehicles'),
        ]);
        const { placed, noPlace, types, centres, nameOf, countOf } = hmChoices(buildings, vehicles);
        if (!placed.length) {
            el.innerHTML = `<div class="ymca-note">No station of yours carries both a vehicle and
        a position, so there is nothing to draw yet.${noPlace.length
    ? ` ${noPlace.length} station${noPlace.length === 1 ? '' : 's'} had vehicles but no
        coordinates.` : ''}</div>`;
            return;
        }

        const cfg = ctx.store.read('cfg', {});
        const set = hmSettings(cfg);
        const on = new Set(Array.isArray(cfg.types) && cfg.types.length ? cfg.types : types);
        const centresOn = new Set(Array.isArray(cfg.centres) && cfg.centres.length
            ? cfg.centres : centres.map((c) => c.id));

        el.innerHTML = `
      <div class="ymca-card">
        <b>${placed.length} station${placed.length === 1 ? '' : 's'} on the map</b>
        <p class="ymca-sub" style="margin:4px 0 10px">Every spot is shaded by how many of the
          ticked vehicles reach it, each station spreading its own count outwards and the
          overlaps adding up. <b>The scale is this map's own</b> &mdash; the deepest shade is
          wherever your cover is thickest, not a standard anybody set.</p>
        <canvas id="hm-canvas" style="width:100%;height:360px;border-radius:4px"></canvas>
        <div id="hm-legend" style="display:flex;align-items:center;gap:8px;margin-top:8px"></div>
      </div>

      <div class="ymca-card">
        <b>Which vehicles</b>
        <p class="ymca-sub" style="margin:4px 0 8px">Cover for all of them at once, or one kind
          at a time. Counts are written on each station, so the colour is never the only thing
          saying it.</p>
        <div style="margin-bottom:8px">
          <button class="ymca-btn" data-all="types">All of them</button>
          <button class="ymca-btn" data-none="types">None</button>
        </div>
        <div class="ymca-pick">${types.map((t) => `<label><input type="checkbox"
          data-type="${ctx.esc(t)}"${on.has(t) ? ' checked' : ''}> ${ctx.esc(String(nameOf(t)))}
          <span class="ymca-dim">${countOf(t)}</span></label>`).join('')}</div>
      </div>

      ${centres.length ? `
      <div class="ymca-card">
        <b>Which dispatch centres</b>
        <p class="ymca-sub" style="margin:4px 0 8px">The whole area, or one centre's own cover.</p>
        <div style="margin-bottom:8px">
          <button class="ymca-btn" data-all="centres">All of them</button>
          <button class="ymca-btn" data-none="centres">None</button>
        </div>
        <div class="ymca-pick">${centres.map((c) => `<label><input type="checkbox"
          data-centre="${ctx.esc(c.id)}"${centresOn.has(c.id) ? ' checked' : ''}>
          ${ctx.esc(c.name)}</label>`).join('')}</div>
      </div>` : ''}

      <div class="ymca-card">
        <b>How it is drawn</b>
        <label style="display:block;margin-top:7px">How far a vehicle counts for
          <select data-radius style="margin-left:6px">
            ${[2, 4, 6, 8, 12, 20, 35].map((n) => `<option value="${n}"${n === set.radius
    ? ' selected' : ''}>${n} km</option>`).join('')}
          </select></label>
        <label style="display:block;margin-top:7px">How tightly it hugs the station
          <select data-focus style="margin-left:6px">
            ${Object.entries(HM_FOCUS).map(([k, f]) => `<option value="${k}"${k === set.focus
    ? ' selected' : ''}>${f.label}</option>`).join('')}
          </select></label>
        <label style="display:block;margin-top:7px">Scale in here
          <select data-scale style="margin-left:6px">
            ${Object.entries(HM_SCALES).map(([k, s]) => `<option value="${k}"${k === set.scale
    ? ' selected' : ''}>${s.label}</option>`).join('')}
          </select></label>
        <label style="display:block;margin-top:7px">Scale on the game's map
          <select data-mapscale style="margin-left:6px">
            ${Object.entries(HM_SCALES).map(([k, s]) => `<option value="${k}"${k === set.mapScale
    ? ' selected' : ''}>${s.label}</option>`).join('')}
          </select></label>
        <label style="display:block;margin-top:7px">How strong on the map
          <select data-opacity style="margin-left:6px">
            ${[0.25, 0.4, 0.55, 0.7, 0.85].map((n) => `<option value="${n}"${n === set.opacity
    ? ' selected' : ''}>${Math.round(n * 100)}%</option>`).join('')}
          </select></label>
        <p class="ymca-sub" style="margin:8px 0 0">The button on the game's own map turns the
          same cover on over the real thing, and brings these tick boxes with it so the choosing
          happens where the map is. There it opens on <b>red to green</b>, because that is what
          it is for &mdash; and the count is written beside every station in the same shade,
          which is what makes that scale readable at all.</p>
        <p class="ymca-dim" style="margin:8px 0 0;font-size:12px"><b>Red to green is the one pair
          a colour-blind reader cannot separate</b> &mdash; measured, not assumed: those two ends
          come back at &#916;E 4.1 under deuteranopia, where 6 is the floor. One hue from light
          to dark says the same thing and says it to everybody, so that is what this one opens
          on. The distance is yours because no page of the game states what a vehicle covers.</p>
        ${noPlace.length ? `<p class="ymca-warn" style="margin:8px 0 0;font-size:12px">
          ${noPlace.length} station${noPlace.length === 1 ? '' : 's'} with vehicles stated no
          position, so ${noPlace.length === 1 ? 'it is' : 'they are'} not on the map.</p>` : ''}
      </div>`;

        const save = (patch) => ctx.store.write('cfg', { ...ctx.store.read('cfg', {}), ...patch });

        const draw = () => {
            const canvas = el.querySelector('#hm-canvas');
            if (!canvas) return;
            const picked = [...el.querySelectorAll('[data-type]:checked')].map((b) => b.dataset.type);
            const areas = new Set([...el.querySelectorAll('[data-centre]:checked')]
                .map((b) => b.dataset.centre));
            const r = Number(el.querySelector('[data-radius]')?.value) || set.radius;
            const steps = HM_SCALES[el.querySelector('[data-scale]')?.value || set.scale].steps;
            const focus = (HM_FOCUS[el.querySelector('[data-focus]')?.value] || HM_FOCUS[set.focus]).p;

            const shown = placed
                .filter((s) => !centres.length || areas.has(s.centre))
                .map((s) => ({ ...s, n: picked.reduce((n, t) => n + (s.byType.get(t) || 0), 0) }))
                .filter((s) => s.n > 0);

            const w = canvas.clientWidth || 600;
            const h = 360;
            const dpr = window.devicePixelRatio || 1;
            canvas.width = Math.round(w * dpr);
            canvas.height = Math.round(h * dpr);
            const g = canvas.getContext('2d');
            g.setTransform(dpr, 0, 0, dpr, 0, 0);
            g.clearRect(0, 0, w, h);

            const legend = el.querySelector('#hm-legend');
            if (!shown.length) {
                legend.innerHTML = '<span class="ymca-dim">Nothing ticked, so there is nothing '
                    + 'to draw.</span>';
                return;
            }

            /* The frame is the stations plus the reach around them, so a lone
             * station at the edge is not drawn half off the canvas. */
            const pad = r / 110 + 0.02;
            const minLat = Math.min(...shown.map((s) => s.lat)) - pad;
            const maxLat = Math.max(...shown.map((s) => s.lat)) + pad;
            const midLat = (minLat + maxLat) / 2;
            const lonPad = pad / Math.max(0.2, Math.cos(midLat * Math.PI / 180));
            const minLon = Math.min(...shown.map((s) => s.lon)) - lonPad;
            const maxLon = Math.max(...shown.map((s) => s.lon)) + lonPad;
            /* Longitude degrees are shorter than latitude ones away from the
             * equator, so the frame is squared off rather than stretched. */
            const spanLat = Math.max(1e-6, maxLat - minLat);
            const spanLon = Math.max(1e-6, maxLon - minLon) * Math.cos(midLat * Math.PI / 180);
            const k = Math.min(w / spanLon, h / spanLat);
            const offX = (w - spanLon * k) / 2;
            const offY = (h - spanLat * k) / 2;
            const px = (lon) => offX + (lon - minLon) * Math.cos(midLat * Math.PI / 180) * k;
            const py = (lat) => offY + (maxLat - lat) * k;

            const pts = shown.map((s) => ({ x: px(s.lon), y: py(s.lat), n: s.n }));
            const peak = hmPeak(shown, r, focus);
            /* `k` is pixels per degree of latitude, and a degree of latitude is
             * 111.32 km wherever you stand. */
            hmHeat(g, w, h, pts, { peak, steps, opacity: 0.85, rPx: (r * k) / 111.32, focus });
            hmBadges(g, pts, hmRamp(steps), peak);

            const total = shown.reduce((n, s) => n + s.n, 0);
            legend.innerHTML = `<span class="ymca-dim" style="font-size:12px">thin</span>
        <span style="flex:0 0 140px;height:12px;border-radius:2px;display:inline-block;
          background:linear-gradient(to right,${steps.join(',')})"></span>
        <span class="ymca-dim" style="font-size:12px">thickest here</span>
        <span class="ymca-dim" style="font-size:12px;margin-left:10px">&middot;
          ${shown.length} station${shown.length === 1 ? '' : 's'},
          ${ctx.fmt(total)} vehicle${total === 1 ? '' : 's'}, within ${r} km</span>`;
            ctx.status(`${shown.length} stations, ${r} km.`);
        };

        el.addEventListener('change', (e) => {
            if (e.target.dataset.radius !== undefined) save({ radius: Number(e.target.value) });
            else if (e.target.dataset.focus !== undefined) save({ focus: e.target.value });
            else if (e.target.dataset.scale !== undefined) save({ scale: e.target.value });
            else if (e.target.dataset.mapscale !== undefined) save({ mapScale: e.target.value });
            else if (e.target.dataset.opacity !== undefined) {
                save({ opacity: Number(e.target.value) });
            } else if (e.target.dataset.type !== undefined) {
                save({ types: [...el.querySelectorAll('[data-type]:checked')].map((b) => b.dataset.type) });
            } else if (e.target.dataset.centre !== undefined) {
                save({ centres: [...el.querySelectorAll('[data-centre]:checked')].map((b) => b.dataset.centre) });
            } else return;
            draw();
        });

        el.addEventListener('click', (e) => {
            const all = e.target.closest('[data-all]');
            const none = e.target.closest('[data-none]');
            if (!all && !none) return;
            const what = (all || none).dataset.all || (all || none).dataset.none;
            const sel = what === 'types' ? '[data-type]' : '[data-centre]';
            for (const box of el.querySelectorAll(sel)) box.checked = !!all;
            save(what === 'types'
                ? { types: all ? types : [] }
                : { centres: all ? centres.map((c) => c.id) : [] });
            draw();
        });

        draw();
        /* The canvas is sized off its own width, so a window that changes shape
         * gets redrawn rather than stretched. */
        window.addEventListener('resize', draw, { passive: true });
    },
});

/* --------------------------------------------------------------------------
 * And the same thing on the game's own map.
 *
 * THE TILES ARE THE PROJECTION, so no function of the game's is called and no
 * global is reached for. A loaded tile is
 * `https://maps.missionchief.com/tile/13/2410/3080.png` — zoom, column, row —
 * and in Web Mercator the tile at (x, y, z) is exactly the world-pixel square
 * from (x·256, y·256) to (x·256+256, y·256+256). One tile's `getBoundingClientRect`
 * therefore fixes the whole page: where world pixel zero sits on screen, and at
 * what scale. Every station's own latitude and longitude goes through the same
 * formula and lands where the game would have put it.
 *
 * That is why this needs neither `window.map` nor Leaflet: the answer is in the
 * markup, and markup is what this repo reads. It also survives the game
 * renaming anything it likes, because nothing here knows a name to break.
 *
 * THE BUTTON IS THE GAME'S OWN KIND. `.leaflet-top.leaflet-left` already holds
 * a `.leaflet-bar.leaflet-control.leaflet-control-custom` the game made itself,
 * so ours is one of those, next to it.
 *
 * AND THE TICK BOXES COME WITH IT. Choosing which vehicles to look at from
 * inside a lightbox, two clicks away from the map the answer is drawn on, is
 * the same fault as a tool you have to open a window to reach. The button turns
 * the mode on and the lists appear beside it; they go when the mode goes, or
 * when they are closed on their own — closing the lists is not switching the
 * cover off, because somebody who has finished choosing still wants to see it.
 * -------------------------------------------------------------------------- */

const HM_CANVAS_ID = 'ymca-heat-canvas';
const HM_BTN_ID = 'ymca-heat-btn';
const HM_PANEL_ID = 'ymca-heat-panel';
let hmFrame = null;
/* What was last painted. The map announces nothing when it moves, so this is
 * redrawn per frame — but a frame that would paint exactly the same pixels is
 * skipped, which is the difference between an idle map costing nothing and
 * costing a colouring pass sixty times a second. */
let hmLast = '';

/** Where world pixel zero sits on screen, and how big a world pixel is. */
function hmProjection() {
    const map = document.getElementById('map');
    if (!map) return null;
    /* A zoom animation has tiles of two zooms on screen at once and every rect
     * mid-flight, so the frame is skipped rather than drawn at the wrong size. */
    if (map.classList.contains('leaflet-zoom-anim')) return null;
    for (const img of map.querySelectorAll('img.leaflet-tile.leaflet-tile-loaded')) {
        const at = /\/(\d+)\/(\d+)\/(\d+)\.[a-z]+(?:\?|$)/i.exec(img.getAttribute('src') || '');
        if (!at) continue;
        const rect = img.getBoundingClientRect();
        if (!(rect.width > 0)) continue;
        const scale = rect.width / 256;
        const z = Number(at[1]);
        return {
            z,
            scale,
            /* Screen position of world pixel (0,0) at this zoom. */
            left: rect.left - Number(at[2]) * 256 * scale,
            top: rect.top - Number(at[3]) * 256 * scale,
            map: map.getBoundingClientRect(),
        };
    }
    return null;
}

/** Web Mercator, the projection every slippy map tile in the world is cut on. */
function hmWorld(lat, lon, z) {
    const n = 256 * (2 ** z);
    const rad = (lat * Math.PI) / 180;
    return {
        x: ((lon + 180) / 360) * n,
        y: ((1 - Math.log(Math.tan(rad) + 1 / Math.cos(rad)) / Math.PI) / 2) * n,
    };
}

/** The canvas the heat is painted on, over the map and under nothing. */
function hmCanvas() {
    const map = document.getElementById('map');
    if (!map) return null;
    let canvas = document.getElementById(HM_CANVAS_ID);
    if (!canvas) {
        canvas = document.createElement('canvas');
        canvas.id = HM_CANVAS_ID;
        /* Over the tiles and the markers, and never in the way of a click: the
         * map has to keep working exactly as it did. */
        canvas.style.cssText = 'position:absolute;inset:0;z-index:450;pointer-events:none';
        map.append(canvas);
    }
    return canvas;
}

function hmClear() {
    if (hmFrame) cancelAnimationFrame(hmFrame);
    hmFrame = null;
    hmLast = '';
    document.getElementById(HM_CANVAS_ID)?.remove();
    document.getElementById(HM_PANEL_ID)?.remove();
}

/**
 * Draw, and keep drawing: the map moves under us and nothing announces it.
 *
 * Watching for a pan means watching a transform the game rewrites constantly,
 * so it is asked once a frame instead — and a frame whose projection has not
 * moved and whose settings have not changed paints nothing at all.
 */
function hmPaint(state) {
    const canvas = hmCanvas();
    const p = hmProjection();
    if (!canvas || !p) return;

    const w = Math.round(p.map.width);
    const h = Math.round(p.map.height);
    const sig = `${p.z}|${Math.round(p.left)}|${Math.round(p.top)}|${p.scale}|${w}|${h}|${state.stamp}`;
    if (sig === hmLast) return;
    hmLast = sig;

    const dpr = window.devicePixelRatio || 1;
    if (canvas.width !== Math.round(w * dpr) || canvas.height !== Math.round(h * dpr)) {
        canvas.width = Math.round(w * dpr);
        canvas.height = Math.round(h * dpr);
    }
    const g = canvas.getContext('2d');
    g.setTransform(dpr, 0, 0, dpr, 0, 0);
    g.clearRect(0, 0, w, h);

    /* Screen position of a station, in the map's own coordinates. */
    const place = (s) => {
        const world = hmWorld(s.lat, s.lon, p.z);
        return {
            x: p.left + world.x * p.scale - p.map.left,
            y: p.top + world.y * p.scale - p.map.top,
        };
    };

    /* How many screen pixels a kilometre is, here. Mercator stretches with
     * latitude, so it is taken at the middle of the map rather than assumed. */
    const midLat = (() => {
        const worldY = (p.map.top + h / 2 - p.top) / p.scale;
        const n = 256 * (2 ** p.z);
        return (Math.atan(Math.sinh(Math.PI * (1 - (2 * worldY) / n))) * 180) / Math.PI;
    })();
    const kmInPixels = (256 * (2 ** p.z) * p.scale)
        / (40075.016686 * Math.cos((midLat * Math.PI) / 180));

    const rPx = Math.max(6, state.radius * kmInPixels);
    /* Off-screen stations still count towards what is drawn at the edge, so the
     * wash does not stop at the window; only the badges are trimmed. */
    const pts = state.stations.map((s) => ({ ...place(s), n: s.n }));
    if (!pts.length) return;

    hmHeat(g, w, h, pts, {
        peak: state.peak,
        steps: state.steps,
        opacity: state.opacity,
        rPx,
        focus: state.focus,
    });
    /* THE NUMBER CARRIES THE COLOUR TOO, in a badge that reads over any tile:
     * the game's own markers stay where they are, and this adds what it counted
     * beside each station in the shade that count earned. */
    hmBadges(
        g,
        pts.filter((s) => s.x > -40 && s.x < w + 40 && s.y > -40 && s.y < h + 40)
            .map((s) => ({ ...s, y: s.y - 14 })),
        hmRamp(state.steps),
        state.peak,
    );
}

/** What to draw, worked out from the settings the panel writes. */
function hmState(buildings, vehicles, cfg) {
    const { placed } = hmStations(buildings, vehicles);
    const set = hmSettings(cfg);
    const types = [...new Set(placed.flatMap((s) => [...s.byType.keys()]))];
    const on = new Set(Array.isArray(cfg.types) && cfg.types.length ? cfg.types : types);
    const areas = Array.isArray(cfg.centres) && cfg.centres.length ? new Set(cfg.centres) : null;
    const stations = placed
        .filter((s) => !areas || areas.has(s.centre))
        .map((s) => ({
            lat: s.lat,
            lon: s.lon,
            n: [...on].reduce((n, t) => n + (s.byType.get(t) || 0), 0),
        }))
        .filter((s) => s.n > 0);
    const focus = HM_FOCUS[set.focus].p;
    return {
        stations,
        radius: set.radius,
        focus,
        peak: hmPeak(stations, set.radius, focus),
        opacity: set.opacity,
        /* ON THE MAP THE DEFAULT IS THE ONE THAT WAS ASKED FOR. The measurement
         * that made one hue the default in the window has not changed — red and
         * green are ΔE 4.1 apart under deuteranopia — and it is answered here by
         * the count being written beside every station in the same shade, which
         * is the secondary encoding that measurement asks for. */
        steps: HM_SCALES[set.mapScale].steps,
        /* Anything a redraw depends on, so a frame that would repeat itself
         * does not. */
        stamp: JSON.stringify([stations.length, set, cfg.types, cfg.centres]),
    };
}

/**
 * The tick boxes, on the map, in the game's own kind of box.
 *
 * It borrows `.leaflet-bar`, which is the game's own control styling, for the
 * same reason the button does: a panel that invented a look of its own would be
 * the one thing on that map that did not belong to it. Every pointer event is
 * stopped at its edge — without that, ticking a box drags the map underneath.
 */
function hmMapPanel(ctx, corner, choices, repaint) {
    document.getElementById(HM_PANEL_ID)?.remove();
    const { types, centres, nameOf, countOf } = choices;
    const cfg = ctx.store.read('cfg', {});
    const set = hmSettings(cfg);
    const on = new Set(Array.isArray(cfg.types) && cfg.types.length ? cfg.types : types);
    const centresOn = new Set(Array.isArray(cfg.centres) && cfg.centres.length
        ? cfg.centres : centres.map((c) => c.id));

    const box = document.createElement('div');
    box.id = HM_PANEL_ID;
    box.className = 'leaflet-bar leaflet-control';
    box.style.cssText = 'background:#fff;color:#333;width:232px;max-height:62vh;overflow:auto;'
        + 'padding:8px 10px;margin-top:6px;font:12px/1.4 "Helvetica Neue",Helvetica,Arial;'
        + 'pointer-events:auto;cursor:default';
    const list = (items) => items.map((i) => `<label style="display:block;margin:2px 0">
      <input type="checkbox" data-${i.what}="${ctx.esc(i.id)}"${i.on ? ' checked' : ''}
        style="margin-right:5px;vertical-align:-1px">${ctx.esc(i.label)}${i.n === undefined ? ''
    : ` <span style="opacity:.55">${i.n}</span>`}</label>`).join('');

    box.innerHTML = `
    <div style="display:flex;align-items:center;margin:0 0 6px">
      <b style="flex:1">Cover</b>
      <a href="#" data-close style="color:#333;text-decoration:none;font-size:15px;
        line-height:1;padding:0 2px" title="Close this, leave the cover on">&times;</a>
    </div>
    <div style="font-weight:bold;margin:6px 0 2px">Which vehicles
      <a href="#" data-all="types" style="font-weight:normal;margin-left:4px">all</a>
      <a href="#" data-none="types" style="font-weight:normal;margin-left:4px">none</a></div>
    ${list(types.map((t) => ({
        what: 'type', id: t, label: String(nameOf(t)), n: countOf(t), on: on.has(t),
    })))}
    ${centres.length ? `<div style="font-weight:bold;margin:8px 0 2px">Which dispatch centres
      <a href="#" data-all="centres" style="font-weight:normal;margin-left:4px">all</a>
      <a href="#" data-none="centres" style="font-weight:normal;margin-left:4px">none</a></div>
    ${list(centres.map((c) => ({
        what: 'centre', id: c.id, label: c.name, on: centresOn.has(c.id),
    })))}` : ''}
    <div style="margin:8px 0 0">
      <label style="display:block;margin:3px 0">Reach
        <select data-radius style="float:right;width:88px">${[2, 4, 6, 8, 12, 20, 35]
        .map((n) => `<option value="${n}"${n === set.radius ? ' selected' : ''}>${n} km</option>`)
        .join('')}</select></label>
      <label style="display:block;margin:3px 0;clear:both">Focus
        <select data-focus style="float:right;width:88px">${Object.entries(HM_FOCUS)
        .map(([k, f]) => `<option value="${k}"${k === set.focus ? ' selected' : ''}>${
            f.label.split(',')[0]}</option>`).join('')}</select></label>
      <label style="display:block;margin:3px 0;clear:both">Strength
        <select data-opacity style="float:right;width:88px">${[0.25, 0.4, 0.55, 0.7, 0.85]
        .map((n) => `<option value="${n}"${n === set.opacity ? ' selected' : ''}>${
            Math.round(n * 100)}%</option>`).join('')}</select></label>
      <label style="display:block;margin:3px 0;clear:both">Scale
        <select data-mapscale style="float:right;width:88px">${Object.entries(HM_SCALES)
        .map(([k, s]) => `<option value="${k}"${k === set.mapScale ? ' selected' : ''}>${
            k === 'warm' ? 'Red to green' : 'One hue'}</option>`).join('')}</select></label>
    </div>
    <div style="clear:both;height:1px"></div>`;

    /* THE MAP IS UNDERNEATH. Leaflet reads pointer and wheel events off the
     * container, so a tick that reached it would drag or zoom the map while the
     * box was being used. Stopped at the box's own edge, before anything else
     * on it runs — stopping propagation does not stop the handlers below. */
    for (const kind of ['mousedown', 'pointerdown', 'touchstart', 'dblclick', 'wheel', 'click']) {
        box.addEventListener(kind, (e) => e.stopPropagation());
    }

    const save = (patch) => {
        ctx.store.write('cfg', { ...ctx.store.read('cfg', {}), ...patch });
        repaint();
    };
    const ticked = (sel) => [...box.querySelectorAll(`${sel}:checked`)]
        .map((b) => b.getAttribute(sel.slice(1, -1)));

    box.addEventListener('change', (e) => {
        const d = e.target.dataset;
        if (d.radius !== undefined) save({ radius: Number(e.target.value) });
        else if (d.focus !== undefined) save({ focus: e.target.value });
        else if (d.opacity !== undefined) save({ opacity: Number(e.target.value) });
        else if (d.mapscale !== undefined) save({ mapScale: e.target.value });
        else if (d.type !== undefined) save({ types: ticked('[data-type]') });
        else if (d.centre !== undefined) save({ centres: ticked('[data-centre]') });
    });

    box.addEventListener('click', (e) => {
        const close = e.target.closest('[data-close]');
        const all = e.target.closest('[data-all]');
        const none = e.target.closest('[data-none]');
        if (!close && !all && !none) return;
        e.preventDefault();
        /* CLOSING THE LISTS IS NOT SWITCHING THE COVER OFF. Somebody who has
         * finished choosing still wants to see what they chose. */
        if (close) { box.remove(); return; }
        const what = (all || none).dataset.all || (all || none).dataset.none;
        const sel = what === 'types' ? '[data-type]' : '[data-centre]';
        for (const b of box.querySelectorAll(sel)) b.checked = !!all;
        save(what === 'types'
            ? { types: all ? types : [] }
            : { centres: all ? centres.map((c) => c.id) : [] });
    });

    corner.append(box);
    return box;
}

YMCA.inject('heatmap', (ctx) => {
    /* The map page and nowhere else: a mission window is a frame with no map in
     * it, and a building page has none either. */
    if (window.top !== window.self) return true;
    const corner = document.querySelector('#map .leaflet-top.leaflet-left');
    if (!corner) return;
    if (document.getElementById(HM_BTN_ID)) return true;

    /* The game's own kind of control, beside the one it made itself. */
    const bar = document.createElement('div');
    bar.id = HM_BTN_ID;
    bar.className = 'leaflet-bar leaflet-control leaflet-control-custom';
    bar.style.cssText = 'background-color:#fff;width:30px;height:30px;cursor:pointer';
    bar.title = 'Cover for the vehicles you ticked in HeatSeeker';
    bar.innerHTML = `<svg viewBox="0 0 30 30" width="30" height="30" fill="none"
    stroke="#333" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"
    aria-hidden="true"><path d="M5 23 L11 9 L16 18 L20 13 L25 23 Z"/></svg>`;
    corner.append(bar);

    const run = (buildings, vehicles) => {
        const state = hmState(buildings, vehicles, ctx.store.read('cfg', {}));
        hmLast = '';
        const tick = () => {
            hmPaint(state);
            hmFrame = requestAnimationFrame(tick);
        };
        if (hmFrame) cancelAnimationFrame(hmFrame);
        tick();
    };

    const paint = async () => {
        const [buildings, vehicles] = await Promise.all([
            ctx.game('/api/buildings'), ctx.game('/api/vehicles'),
        ]);
        run(buildings, vehicles);
        /* The tick boxes come up with the mode, so the choosing happens where
         * the answer is drawn rather than two clicks away in a lightbox. */
        hmMapPanel(ctx, corner, hmChoices(buildings, vehicles), () => run(buildings, vehicles));
    };

    bar.addEventListener('click', (e) => {
        e.preventDefault();
        e.stopPropagation();
        const on = !document.getElementById(HM_CANVAS_ID);
        bar.style.backgroundColor = on ? '#8ab4f8' : '#fff';
        if (!on) { hmClear(); ctx.status('Cover overlay off.'); return; }
        paint().catch((err) => {
            hmClear();
            bar.style.backgroundColor = '#fff';
            ctx.log.warn('heat overlay', err.message);
        });
    });

    return true;
});

/* --------------------------------------------------------------------------
 * TrackOps — count the missions you finish, and what they paid.
 *
 * Only from the day it is installed, which is the honest limit: the game does
 * not hand out a history.
 *
 * Two wrong guesses got us here, and both are worth keeping written down.
 *
 * The first watcher wrapped fetch and XMLHttpRequest and saw zero requests
 * across half a minute in which the mission list never stopped moving. The
 * game is not polled over HTTP; it is pushed to over a socket that is already
 * open by the time a userscript set to document-idle runs.
 *
 * The second watched the mission list instead, and across 455 seconds recorded
 * 30 departures of which 30 came straight back. Not one mission left. That is
 * because a finished mission does not leave the list — the game adds the class
 * `mission_deleted` to its panel and leaves it sitting there. Counting rows
 * would have counted nothing forever.
 *
 * What the game actually does is call its own functions, and jxn-30/LSS-Scripts
 * has been hooking them for years: `missionMarkerAdd(mission)` when one
 * appears and `missionDelete(missionId)` when one ends. Those are driven by the
 * same socket, so hooking them is hooking the socket without needing to reach
 * it. That is what this does now.
 *
 * THE CREDITS COME FROM THE GAME TOO. Reading /api/credits after the fact was
 * wrong twice over: it races the payout, and it drifts the moment the player
 * buys anything. A mission page's own source settled it —
 *
 *     tellParent('creditsUpdate(2283098);');
 *
 * — the game pushes the new balance to a global `creditsUpdate` and the whole
 * thing runs over Faye, which eval()s what it is sent. So both halves of the
 * question are announced: `missionDelete` says a mission ended, `creditsUpdate`
 * says what the balance became. /api/credits is now only the opening reading.
 *
 * WHAT IS STILL INFERRED, and is labelled as such everywhere it shows:
 * `missionDelete` says a mission ended, not that *you* finished it, and the
 * balance moving right afterwards is not proof it moved *because* of it. So a
 * payout is only trusted when one mission ended alone and the balance rose
 * once within a few seconds. Anything else is recorded and shown, but kept out
 * of the averages.
 * -------------------------------------------------------------------------- */

/* The page the mission list lives on. Inside a mission's own iframe there is no
 * list and no globals to hook, so the recorder stays out of the way there. */
const TO_MAIN_PAGE = /^\/?$/;

const TO_LOG_KEY = 'ymca-trackops-log';
const TO_CFG_KEY = 'ymca-trackops-cfg';
const TO_LOG_MAX = 2000;

/* How long a mission's ending stays open for a balance change to be attributed
 * to it. The payout is pushed over the same channel, a beat behind. */
const TO_SETTLE_MS = 5000;

/* The game announces the same mission ending more than once. An id seen again
 * inside this window is the same ending, not a second one. */
const TO_DEDUPE_MS = 120000;

function toRead(key, fallback) {
    try {
        return JSON.parse(localStorage.getItem(key)) ?? fallback;
    } catch (e) {
        return fallback;
    }
}
function toWrite(key, value) {
    try {
        localStorage.setItem(key, JSON.stringify(value));
    } catch (e) { /* private window: it still counts, it just forgets */ }
}

const toCfg = () => toRead(TO_CFG_KEY, { recording: true });

YMCA.register({
    id: 'trackops',
    title: 'TrackOps',
    tagline: 'What you have run',
    optional: true,

    description: 'Counts the missions you finish and what each one actually paid, '
        + 'from the day it was installed.',

    async mount(el, ctx) {
        const cfg = toCfg();
        /* The game defines missionDelete while the page loads, which can be after this file
         * runs, and the retry below gives up rather than spinning forever. Opening the tool is
         * the natural second chance — and the one moment the player would notice it missing. */
        if (cfg.recording) toAttach();
        const whole = toRead(TO_LOG_KEY, []);
        const listed = await toListedCredits(ctx);
        const span = TO_SPANS[cfg.span] ? cfg.span : 'all';
        const log = toWithin(whole, span);
        const rows = toSummarise(log, listed);
        const yours = log.filter((e) => e.mine).length;
        const unknown = log.filter((e) => e.mine === undefined).length;

        el.innerHTML = `
      <div class="ymca-card">
        <b>Since ${whole.length ? new Date(whole[0].at).toLocaleDateString() : 'you turned it on'}</b>
        <p style="font-size:26px;font-weight:700;margin:8px 0 2px">${yours}
          <span class="ymca-dim" style="font-size:14px;font-weight:400">of yours</span>
          <span class="ymca-dim" style="font-size:14px;font-weight:400">&middot; ${log.length}
          finished nearby</span></p>
        <p class="ymca-dim">Across ${rows.length} kinds of mission${
    unknown ? `, ${unknown} recorded before TrackOps could tell whose they were` : ''}.</p>
        <div style="margin:10px 0 0">${Object.entries(TO_SPANS).map(([key, v]) =>
    `<button class="ymca-btn${key === span ? ' primary' : ''}" data-span="${key}"
            >${v.label}</button>`).join(' ')}</div>
        <label style="display:block;margin:10px 0 0"><input type="checkbox" data-cfg="recording"
          ${cfg.recording ? 'checked' : ''}> Keep recording</label>
      </div>

      <div class="ymca-note"><b>Yours means one of your vehicles was at it.</b> An alliance call
        somebody else handled ends on your map exactly like one of your own, so both numbers are
        shown: the game announced the ending, YMCA saw your vehicle.</div>

      <div class="ymca-card">
        <b>What missions actually paid</b>
        <p class="ymca-sub" style="margin:4px 0 10px">Read from the game's own credits ledger,
          where every line says what it was for. A mission's payout is the line named after the
          mission; a daily task is named as one and left out.</p>
        <label class="ymca-dim" style="display:block;margin-bottom:8px">How far back
          <select data-pages style="margin-left:6px">
            ${[1, 5, 10, 25, 50, 100, 200].map((n) => `<option value="${n}"${
    n === (Number(cfg.pages) || 5) ? ' selected' : ''}>${n} page${n === 1 ? '' : 's'}</option>`)
    .join('')}
          </select>
          <span style="margin-left:6px">&mdash; the game pages this, and one page is not an
            account's history</span></label>
        <button class="ymca-btn primary" data-do="ledger">Read the credits ledger</button>
        <button class="ymca-btn" data-do="ledger-copy">Copy it</button>
        <button class="ymca-btn" data-do="ledger-shape"
          title="press this if the ledger will not read">Copy the credits page</button>
        <span class="ymca-status" id="to-ledger-status"></span>
        <div id="to-ledger"></div>
      </div>

      <div class="ymca-note"><b>Counting endings is what this does.</b> Pairing an ending with
        the next rise in your balance could not tell that rise apart from a daily task reward, so
        that reading is gone — it put a 320-credit call at 3,716. The ledger above answers the
        same question by reading what the game wrote down.</div>

      ${rows.length ? `
      <div class="ymca-card">
        <b>What you have run</b>
        <table id="to-table" style="margin-top:8px">
          <thead><tr><th class="ymca-num">Yours</th><th class="ymca-num">Nearby</th>
            <th>Mission</th><th class="ymca-num">Listed</th>
            <th class="ymca-num" title="what the ledger says this mission paid">Paid</th></tr></thead>
          <tbody>${rows.map((r) => `
            <tr><td class="ymca-num">${r.yours || '<span class="ymca-dim">&ndash;</span>'}</td>
              <td class="ymca-num">${r.runs}</td>
              <td>${r.icon ? `<img src="${ctx.esc(r.icon)}" width="16" height="16" alt=""
                style="vertical-align:-3px;margin-right:6px">` : ''}${ctx.esc(r.name)}</td>
              <td class="ymca-num">${r.listed === null
        ? '<span class="ymca-warn">none listed</span>' : ctx.fmt(r.listed)}</td>
              <td class="ymca-num" data-paid="${ctx.esc(toNameKey(r.name))}"
                ><span class="ymca-dim">reading\u2026</span></td></tr>`).join('')}
          </tbody>
        </table>
        <p class="ymca-sub" style="margin-top:8px"><b>Listed</b> is the game's own figure from
          the mission list. <b>Paid</b> is what its own ledger wrote down, averaged over the
          lines named after that mission &mdash; measured, not paired with anything. Rows where
          the game lists nothing are the ones worth having: those are what the planner is
          guessing at.</p>
      </div>` : `
      <div class="ymca-card">
        <b>Nothing counted yet</b>
        <p class="ymca-dim">It records while you play, on the main map page. Finish a mission and
          come back. If this stays empty after a few, press the button below and send the result —
          that says which of the game's own hooks are reachable.</p>
      </div>`}

      <div class="ymca-card">
        <b>Hand it over</b>
        <button class="ymca-btn primary" data-do="copy">Copy what was measured</button>
        <button class="ymca-btn" data-do="probe">Check the hooks</button>
        <button class="ymca-btn" data-do="reset">Start over</button>
        <span class="ymca-status" id="to-status"></span>
        <textarea id="to-out" rows="10" readonly style="width:100%;margin-top:10px;
          font-family:ui-monospace,monospace;font-size:11.5px"></textarea>
      </div>`;

        /* The ledger is read on open rather than on a button, because a column
         * that says "reading\u2026" until somebody presses something is a column
         * nobody reads. The button stays: it is how the ledger's own table and
         * the copy are asked for. */
        toReadLedger(1).then(({ rows }) => {
            toFillPaid(el, ctx, toSummariseLedger(rows));
        }).catch((err) => {
            el.querySelectorAll('[data-paid]').forEach((cell) => {
                cell.innerHTML = '<span class="ymca-dim" title="the ledger could not be read"'
                    + '>&ndash;</span>';
            });
            ctx.log.warn('credits ledger unreadable on open', err.message);
        });

        /* The span changes what every number on the panel means, so the panel is
         * built again rather than patched in six places. */
        el.addEventListener('click', (e) => {
            const pick = e.target.closest('[data-span]');
            if (!pick) return;
            toWrite(TO_CFG_KEY, Object.assign(toCfg(), { span: pick.dataset.span }));
            YMCA.modules.find((m) => m.id === 'trackops').mount(el, ctx);
        });

        el.addEventListener('change', (e) => {
            if (e.target.hasAttribute?.('data-pages')) {
                toWrite(TO_CFG_KEY, Object.assign(toCfg(), { pages: Number(e.target.value) }));
                ctx.status(`Reading ${e.target.value} page(s) of the ledger.`);
                return;
            }
            if (e.target.dataset.cfg !== 'recording') return;
            const next = Object.assign(toCfg(), { recording: e.target.checked });
            toWrite(TO_CFG_KEY, next);
            if (next.recording) toAttach(); else toDetach();
            ctx.status(next.recording ? 'Recording.' : 'Stopped.');
            ctx.log.info(next.recording ? 'recording on' : 'recording off');
        });

        el.addEventListener('click', (e) => {
            const out = el.querySelector('#to-out');
            if (e.target.closest('[data-do="ledger"]') || e.target.closest('[data-do="ledger-copy"]')) {
                const copy = !!e.target.closest('[data-do="ledger-copy"]');
                const status = el.querySelector('#to-ledger-status');
                status.textContent = 'Reading…';
                const want = Number(toCfg().pages) || 5;
                toReadLedger(want, (done, asked, total) => {
                    status.textContent = `Page ${done} of ${asked}… (the game has ${total})`;
                }).then(({ path, rows, pagesRead, pagesTotal, more }) => {
                    const sum = toSummariseLedger(rows);
                    sum.pagesRead = pagesRead;
                    sum.pagesTotal = pagesTotal;
                    sum.more = more;
                    status.textContent = `${sum.lines} lines from ${path}, `
                        + `${pagesRead} of ${pagesTotal} page${pagesTotal === 1 ? '' : 's'}.`;
                    el.querySelector('#to-ledger').innerHTML = toLedgerHtml(sum, ctx);
                    toFillPaid(el, ctx, sum);
                    ctx.log.info('read the credits ledger', `${sum.lines} lines, ${sum.missions.length} kinds`);
                    if (copy) {
                        ctx.clipboard(JSON.stringify({
                            note: 'mission names and credit amounts from the game\'s own ledger',
                            ymca: YMCA.version,
                            lines: sum.lines,
                            /* HOW FAR BACK THIS READ. An average over one page
                             * of 210 is a sample, and a sample that does not
                             * say so reads as a measurement. */
                            pagesRead: sum.pagesRead,
                            pagesTheGameHas: sum.pagesTotal,
                            patientIncome: sum.patients,
                            ignoredLines: sum.ignored,
                            /* The wording of every kind of line, figures taken
                             * out: what a transport, prisoner or alliance count
                             * has to be built on before it can be built. */
                            lineKinds: sum.kinds,
                            byMission: sum.missions.map((m) => ({
                                name: m.name, runs: m.runs, average: m.average,
                                low: m.low, high: m.high,
                            })),
                        }, null, 1), 'the ledger');
                    }
                }).catch((err) => {
                    status.textContent = `Could not read it: ${err.message}`;
                    el.querySelector('#to-ledger').innerHTML = `<div class="ymca-note bad"
              style="margin-top:8px"><b>The ledger did not read.</b> ${ctx.esc(err.message)}<br>
              Press <b>Copy the credits page</b> and send what it gives you \u2014 it copies the
              shape of that page and nothing that is on it.</div>`;
                    ctx.log.warn('credits ledger unreadable', err.message);
                });
            } else if (e.target.closest('[data-do="ledger-shape"]')) {
                const status = el.querySelector('#to-ledger-status');
                status.textContent = 'Reading\u2026';
                toCaptureLedger().then((shape) => {
                    const text = JSON.stringify(shape, null, 1);
                    out.value = text;
                    status.textContent = `${shape.pages.length} pages looked at.`;
                    ctx.clipboard(text, 'the credits page\u2019s shape');
                });
            } else if (e.target.closest('[data-do="copy"]')) {
                const text = JSON.stringify(toExport(log, listed), null, 1);
                out.value = text;
                ctx.clipboard(text, 'what was measured');
            } else if (e.target.closest('[data-do="probe"]')) {
                const text = JSON.stringify(toProbe(), null, 1);
                out.value = text;
                ctx.clipboard(text, 'the hook check');
                ctx.log.info('hook check', text.slice(0, 120));
            } else if (e.target.closest('[data-do="reset"]')) {
                if (!confirm('Forget every mission recorded so far? This cannot be undone.')) return;
                toWrite(TO_LOG_KEY, []);
                ctx.status('Forgotten.');
                ctx.log.warn('recorded missions cleared');
                ctx.open('trackops');
            }
        });
    },
});

/* ------------------------------------------------------------ what it shows */

/** The game's own listed averages, so a measurement can be held against them. */
async function toListedCredits(ctx) {
    try {
        const missions = await ctx.game('/einsaetze.json');
        const list = Array.isArray(missions) ? missions : Object.values(missions);
        return Object.fromEntries(list.map((m) => [String(m.id), {
            name: m.name,
            // null and 0 both mean "the game does not say", which is the gap being filled.
            listed: m.average_credits || null,
            /* The game ships its own artwork for every mission and names it in
             * the catalogue: three states, green through red. The first is the
             * quiet one, which is what a list wants. */
            icon: Array.isArray(m.icons) && m.icons.length ? m.icons[0] : null,
        }]));
    } catch (err) {
        ctx.log.warn('could not read the mission list, so nothing can be named', err.message);
        return {};
    }
}

/** Only what happened inside the window the player asked for. */
const TO_SPANS = {
    all: { label: 'All', ms: null },
    day: { label: 'Today', ms: 24 * 3600e3 },
    week: { label: '7 days', ms: 7 * 24 * 3600e3 },
    month: { label: '30 days', ms: 30 * 24 * 3600e3 },
};

function toWithin(log, span) {
    const ms = TO_SPANS[span]?.ms;
    if (!ms) return log;
    const from = Date.now() - ms;
    return log.filter((e) => e.at >= from);
}

function toSummarise(log, listed) {
    const byType = new Map();
    for (const entry of log) {
        const key = String(entry.type);
        if (!byType.has(key)) {
            byType.set(key, {
                type: key,
                name: listed[key]?.name || `Mission type ${key}`,
                listed: listed[key] ? listed[key].listed : null,
                icon: listed[key]?.icon || null,
                runs: 0,
                yours: 0,
                measured: 0,
                total: 0,
            });
        }
        const row = byType.get(key);
        row.runs += 1;
        /* `mine` is absent on everything recorded before TrackOps started
         * looking, so it is counted as unknown rather than as a no. */
        if (entry.mine) row.yours += 1;
        if (entry.alone && entry.delta > 0) {
            row.measured += 1;
            row.total += entry.delta;
        }
    }
    return [...byType.values()]
        .map((r) => Object.assign(r, { average: r.measured ? r.total / r.measured : 0 }))
        .sort((a, b) => b.runs - a.runs);
}

/**
 * Write the ledger's own figure into every row of the run table.
 *
 * THIS IS MEASURED AND THE COLUMN BESIDE IT IS NOT THE SAME THING. The balance
 * delta was withdrawn because a rise cannot be told apart from a daily task
 * landing in the same second. A ledger line is the game writing down what it
 * paid and what it paid it for, so averaging those is reading rather than
 * inferring — and the count is shown beside it, because one line is not an
 * average.
 *
 * A mission with no line yet says so rather than showing a zero: nothing run
 * since the ledger page begins is not the same as nothing paid.
 */
let toLastLedger = null;

function toFillPaid(el, ctx, sum) {
    toLastLedger = sum;
    const byName = new Map(sum.missions.map((m) => [toNameKey(m.name), m]));
    for (const cell of el.querySelectorAll('[data-paid]')) {
        const m = byName.get(cell.dataset.paid);
        cell.innerHTML = m
            ? `${ctx.fmt(m.average)} <span class="ymca-dim" style="font-size:11px"
                title="${m.runs} line${m.runs > 1 ? 's' : ''} in the ledger">\u00d7${m.runs}</span>`
            : '<span class="ymca-dim" title="no line named after it on this page of the ledger"'
                + '>&ndash;</span>';
    }
}

/** The ledger, as a table: what each mission paid, and how much it varied. */
function toLedgerHtml(sum, ctx) {
    /* SAID ON THE PANEL, not only in the copy: every figure under here is over
     * the pages that were read and no further, and a reader who is not told
     * that will take an average of one page for an average of the account. */
    const howFar = sum.pagesTotal > 1
        ? `<div class="ymca-note" style="margin-top:8px">Everything below is the
        <b>${ctx.fmt(sum.pagesRead || 1)}</b> most recent page${(sum.pagesRead || 1) === 1 ? '' : 's'}
        of ${ctx.fmt(sum.pagesTotal)} the game has. ${sum.more
        ? 'There is more behind it — raise "How far back" to take it in.' : ''}</div>`
        : '';
    if (!sum.missions.length && !sum.patients.lines) {
        return '<p class="ymca-dim">The ledger answered, but nothing in it was a mission.</p>';
    }
    return `
    ${howFar}
    ${sum.patients.lines ? `<p style="margin:10px 0 4px"><b>${ctx.fmt(sum.patients.total)}</b>
      <span class="ymca-dim">from ${sum.patients.lines} patient treatment and transport lines
      &mdash; income the mission list does not carry at all.</span></p>` : ''}
    <table style="margin-top:8px">
      <thead><tr><th class="ymca-num">Run</th><th>Mission</th><th class="ymca-num">Average</th>
        <th class="ymca-num">Lowest</th><th class="ymca-num">Highest</th></tr></thead>
      <tbody>${sum.missions.slice(0, 60).map((m) => `<tr>
        <td class="ymca-num">${m.runs}</td><td>${ctx.esc(m.name)}</td>
        <td class="ymca-num">${ctx.fmt(m.average)}</td>
        <td class="ymca-num ymca-dim">${ctx.fmt(m.low)}</td>
        <td class="ymca-num ymca-dim">${ctx.fmt(m.high)}</td></tr>`).join('')}</tbody>
    </table>
    ${sum.kinds?.length ? `<details style="margin-top:10px"><summary class="ymca-dim"
      >Every kind of line in the ledger (${sum.kinds.length})</summary>
      <table style="margin-top:6px"><thead><tr><th>As the game words it</th>
        <th class="ymca-num">Lines</th><th class="ymca-num">In</th>
        <th class="ymca-num">Out</th></tr></thead>
      <tbody>${sum.kinds.slice(0, 80).map((k) => `<tr>
        <td>${ctx.esc(k.kind)}</td><td class="ymca-num">${ctx.fmt(k.lines)}</td>
        <td class="ymca-num">${k.paid ? ctx.fmt(k.paid) : ''}</td>
        <td class="ymca-num">${k.spent ? ctx.fmt(k.spent) : ''}</td></tr>`).join('')}</tbody>
      </table>
      <p class="ymca-dim" style="margin:6px 0 0;font-size:12px">Figures inside the wording are
        taken out, so this is what the game calls things and nothing of yours. It is what a
        count of transports, prisoners or alliance shares has to be built on.</p></details>` : ''}
    <p class="ymca-sub" style="margin-top:8px">${sum.ignored} lines left out as not a mission.
      This is one page of the ledger &mdash; the game keeps many.</p>`;
}

/**
 * What goes back for the planner's sake.
 *
 * Mission type ids and credit figures, which are the game's own constants, and
 * counts. No mission instance ids, no timestamps beyond the day, no balance.
 */
function toExport(log, listed) {
    const rows = toSummarise(log, listed);
    return {
        note: 'mission type ids, what each paid on average, and how often — no balance, '
            + 'no mission instance ids, no addresses, no names',
        ymca: YMCA.version,
        measuredFrom: log.length ? new Date(log[0].at).toISOString().slice(0, 10) : null,
        missionsEnded: log.length,
        missionsYours: log.filter((e) => e.mine).length,
        missionsWhoseOwnerIsUnknown: log.filter((e) => e.mine === undefined).length,
        missionsMeasured: log.filter((e) => e.alone && e.delta > 0).length,
        /* What the game wrote down, by name, so what a mission really pays can
         * go into data/missions.json instead of being asked for again. Names
         * and amounts, which are the game's own constants. */
        paidByName: toLastLedger ? toLastLedger.missions.map((m) => ({
            name: m.name, lines: m.runs, average: m.average, low: m.low, high: m.high,
        })) : null,
        payoutReadingRetired: 'a balance rise cannot be told apart from a daily reward',
        byMissionType: rows.map((r) => ({
            type: Number(r.type) || r.type,
            name: r.name,
            runs: r.runs,
            yours: r.yours,
            /* Kept, and kept labelled. A balance rise near a mission ending is
             * not that mission's payout — a daily task reward lands the same
             * way — so these are observations of the balance, not of a payout,
             * and nothing averages them. */
            balanceRoseNearby: r.measured,
            balanceRiseTotal: r.measured ? r.total : null,
            listedByGame: r.listed,
        })),
    };
}

/**
 * Which of the game's own hooks are actually there.
 *
 * If counting ever comes back empty this is the first thing to look at, and it
 * says so without the player having to describe anything.
 */
function toProbe() {
    const w = (typeof unsafeWindow !== 'undefined' ? unsafeWindow : window);
    const named = (fn) => (typeof fn === 'function' ? 'function' : typeof fn);
    return {
        note: 'which of the game\'s own functions are reachable — names and types only',
        page: location.pathname,
        onMainPage: TO_MAIN_PAGE.test(location.pathname),
        recording: toCfg().recording,
        hooked: toHooked,
        balanceKnown: toBalance !== null,
        globals: {
            missionDelete: named(w.missionDelete),
            creditsUpdate: named(w.creditsUpdate),
            missionMarkerAdd: named(w.missionMarkerAdd),
            missionInvolved: named(w.missionInvolved),
            mission_markers: Array.isArray(w.mission_markers) ? `array(${w.mission_markers.length})` : typeof w.mission_markers,
        },
        unsafeWindowAvailable: typeof unsafeWindow !== 'undefined',
        missionListPresent: !!document.getElementById('mission_list'),
        deletedPanelsOnPage: document.querySelectorAll('.mission_deleted').length,
        recorded: toRead(TO_LOG_KEY, []).length,
    };
}

/* ------------------------------------------------------- the credits ledger */

/**
 * The game keeps a ledger, and it names every line.
 *
 *     +575   Patient Treatment and Transport   20 Sep 00:45
 *     +649   Child swallows cleaning supply    20 Sep 00:44
 *     +13.500 Completed task "Treat 6 patients"
 *     -5.000 Vehicle bought
 *
 * Which is the thing the balance-watching could never be: each amount already
 * says what it was for. A mission's payout is the line named after the mission,
 * a daily task is named as one and thrown away, and "Patient Treatment" and
 * "Patient Treatment and Transport" are their own income — the figure the
 * ambulance path was missing.
 *
 * Amounts use a dot for thousands, so every character that is not a digit or a
 * sign is dropped before reading it.
 */
const TO_LEDGER_PATHS = ['/credits/overview', '/credits'];

/** Lines that are not a mission being paid for. Matched loosely and on purpose. */
const TO_NOT_A_MISSION = [
    /completed task/i, /\btask\b/i, /bought/i, /constructed/i, /built/i,
    /sold/i, /sale/i, /coins?/i, /alliance (deposit|withdraw)/i, /daily/i,
    /schooling|education|course/i, /extension/i, /expansion/i, /upgrade/i,
];

/** Income that belongs to the ambulance service rather than to a mission name. */
const TO_PATIENT_LINES = /^patient (treatment|transport)/i;

/**
 * Find the columns rather than assume them.
 *
 * The first version took cell 0 as the amount, cell 1 as the description and
 * cell 2 as the date, and threw away any row with fewer than three cells. That
 * is three assumptions about a page nobody here has seen, and on a real account
 * it came back with nothing at all. So each row is asked which of its cells is
 * a number and which carries words, and a row that answers neither is skipped
 * rather than taking the whole read with it.
 *
 * Amounts use a dot for thousands, so every character that is not a digit is
 * dropped and the sign is read separately.
 */
function toParseLedgerRow(tr) {
    const cells = [...(tr.cells || tr.querySelectorAll('td, th'))];
    if (cells.length < 2) return null;
    const text = (c) => (c.textContent || '').replace(/\s+/g, ' ').trim();

    let amount = null;
    let amountAt = -1;
    for (let i = 0; i < cells.length; i += 1) {
        const t = text(cells[i]);
        if (!/^[+\-\u2212]?\s*[\d.,]+$/.test(t) || !/\d/.test(t)) continue;
        const digits = Number(t.replace(/\D/g, ''));
        if (!Number.isFinite(digits) || !digits) continue;
        amount = /^[-\u2212]/.test(t) ? -digits : digits;
        amountAt = i;
        break;
    }
    if (amount === null) return null;

    /* The description is the wordiest cell that is not the amount. A date has
     * digits and separators; a mission name has letters. */
    let what = '';
    for (let i = 0; i < cells.length; i += 1) {
        if (i === amountAt) continue;
        const t = text(cells[i]);
        if (!/[a-z]{3}/i.test(t)) continue;
        if (t.length > what.length) what = t;
    }
    if (!what) return null;

    const at = text(cells[cells.length - 1]);
    return { amount, what, at: at === what ? '' : at };
}

/** What the page looked like, for a read that came back empty. */
function toLedgerShape(doc) {
    const tables = [...doc.querySelectorAll('table')];
    return {
        tables: tables.length,
        rows: tables.map((t) => t.querySelectorAll('tr').length),
        /* Cell shapes only: how many, what they are called, whether each held
         * digits or words. Never an amount and never a description. */
        firstRow: tables.map((t) => {
            const tr = t.querySelector('tbody tr, tr');
            if (!tr) return null;
            return [...(tr.cells || [])].map((c) => ({
                tag: c.tagName.toLowerCase(),
                class: (typeof c.className === 'string' && c.className.trim()) || undefined,
                digits: /\d/.test(c.textContent || ''),
                words: /[a-z]{3}/i.test(c.textContent || ''),
            }));
        }),
    };
}

/**
 * THE LEDGER IS 210 PAGES AND THIS READ ONE OF THEM.
 *
 * Everything the ledger answered — what a mission paid, how many patient
 * lines, every kind of line there is — was the most recent page and nothing
 * else, and it said so nowhere. An average over one page of an account's
 * history is not the account's average, and a figure that looks measured while
 * being a sample is exactly what this module already withdrew once.
 *
 * So: how far back it actually read is counted and said, the total the game
 * states is read off its own pagination, and **the next page is followed by
 * the game's own link** — `a[rel="next"]` — rather than by building
 * `?page=N`, which is the same rule every other reader here keeps.
 */
function toLedgerPages(doc) {
    const nav = doc.querySelector('ul.pagination');
    if (!nav) return { next: null, total: 1 };
    const next = nav.querySelector('li.next > a[rel="next"], a[rel="next"]')
        ?.getAttribute('href') || null;
    /* The highest page the game itself links to. It shows an ellipsis in the
     * middle and the last pages at the end, so the biggest number on it is the
     * total — read rather than counted. */
    let total = 1;
    for (const a of nav.querySelectorAll('a[href*="page="]')) {
        const n = Number(/[?&]page=(\d+)/.exec(a.getAttribute('href') || '')?.[1]);
        if (Number.isFinite(n) && n > total) total = n;
    }
    return { next, total };
}

async function toReadLedger(pages = 1, onProgress) {
    let lastError = null;
    let lastShape = null;
    for (const path of TO_LEDGER_PATHS) {
        try {
            /* eslint-disable no-await-in-loop */
            const res = await fetch(path, { credentials: 'same-origin' });
            if (!res.ok) { lastError = `HTTP ${res.status}`; continue; }
            const doc = new DOMParser().parseFromString(await res.text(), 'text/html');
            const rows = [...doc.querySelectorAll('table tr')]
                .map(toParseLedgerRow).filter(Boolean);
            if (!rows.length) {
                lastShape = { path, ...toLedgerShape(doc) };
                lastError = `${path} answered, but no row in it read as an amount and a description`;
                continue;
            }

            const { next: firstNext, total } = toLedgerPages(doc);
            let next = firstNext;
            let read = 1;
            const want = Math.max(1, Math.min(Number(pages) || 1, 200));
            while (next && read < want) {
                onProgress?.(read, want, total);
                const more = await fetch(next, { credentials: 'same-origin' });
                if (!more.ok) break;
                const page = new DOMParser().parseFromString(await more.text(), 'text/html');
                const got = [...page.querySelectorAll('table tr')]
                    .map(toParseLedgerRow).filter(Boolean);
                if (!got.length) break;
                rows.push(...got);
                next = toLedgerPages(page).next;
                read += 1;
                /* A page at a time, unhurried: this is 210 requests if somebody
                 * asks for all of it, and the game is not owed a stampede. */
                await new Promise((go) => { setTimeout(go, 200); });
            }
            return { path, rows, pagesRead: read, pagesTotal: total, more: !!next };
        } catch (err) {
            lastError = err.message;
        }
    }
    const err = new Error(lastError || 'no credits page answered');
    err.shape = lastShape;
    throw err;
}

/**
 * The credits page, as structure.
 *
 * Pressed when the ledger will not read, so the next version knows what it is
 * looking at. Table and cell shapes only \u2014 never an amount, never a line's
 * description, never a balance.
 */
async function toCaptureLedger() {
    const out = { ymca: YMCA.version, what: 'trackops-ledger', at: new Date().toISOString(), pages: [] };
    for (const path of TO_LEDGER_PATHS) {
        try {
            const res = await fetch(path, { credentials: 'same-origin' });
            if (!res.ok) { out.pages.push({ path, status: res.status }); continue; }
            const doc = new DOMParser().parseFromString(await res.text(), 'text/html');
            const rows = [...doc.querySelectorAll('table tr')].map(toParseLedgerRow).filter(Boolean);
            out.pages.push({
                path,
                status: res.status,
                rowsParsed: rows.length,
                ...toLedgerShape(doc),
                /* Where the rest of the ledger is: the game keeps many pages and
                 * one of these links is how to reach them. Shapes, not targets. */
                linkShapes: [...new Set([...doc.querySelectorAll('a[href]')]
                    .map((a) => (a.getAttribute('href') || '').split('?')[0].replace(/\d+/g, '#')))]
                    .filter(Boolean).slice(0, 25),
            });
        } catch (err) {
            out.pages.push({ path, failed: err.message });
        }
    }
    return out;
}

/**
 * One name, spelled one way.
 *
 * The catalogue names a mission and the ledger names the line after it, so the
 * two meet on the name — but only once case and spacing stop mattering.
 */
function toNameKey(name) {
    return String(name || '').toLowerCase().replace(/\s+/g, ' ').trim();
}

/**
 * What the ledger says, grouped by what each line was for.
 *
 * Nothing is inferred here: a line is only counted as a mission's payout if the
 * line is named after that mission. What is left over is reported as such
 * rather than spread across the missions around it.
 */
function toSummariseLedger(rows) {
    const missions = new Map();
    const patients = { lines: 0, total: 0 };
    const kinds = new Map();
    let ignored = 0;
    let spent = 0;

    /* WHAT IS THROWN AWAY IS WHAT THE STATS ARE MADE OF. Everything this counts
     * as "not a mission" — a prisoner delivered, an alliance share, a daily
     * task, a course — is a thing the player wants counted, and the only reason
     * it is not counted yet is that nobody here knows the words the game writes
     * for it. So each one is tallied by its own description with the figures
     * taken out: digits masked and anything quoted emptied, which leaves the
     * game's own wording and no mission, task or building of the player's in
     * it. That is the vocabulary the next version is built from. */
    const kindOf = (what) => String(what).replace(/"[^"]*"/g, '"…"')
        .replace(/\d[\d.,]*/g, '#').replace(/\s+/g, ' ').trim()
        .slice(0, 80);

    for (const row of rows) {
        const kind = kindOf(row.what);
        const tally = kinds.get(kind) || { kind, lines: 0, paid: 0, spent: 0 };
        tally.lines += 1;
        if (row.amount < 0) tally.spent += -row.amount; else tally.paid += row.amount;
        kinds.set(kind, tally);

        if (row.amount < 0) { spent += -row.amount; continue; }
        if (TO_PATIENT_LINES.test(row.what)) {
            patients.lines += 1;
            patients.total += row.amount;
            continue;
        }
        if (TO_NOT_A_MISSION.some((re) => re.test(row.what))) { ignored += 1; continue; }
        const seen = missions.get(row.what) || { name: row.what, runs: 0, total: 0, low: Infinity, high: 0 };
        seen.runs += 1;
        seen.total += row.amount;
        seen.low = Math.min(seen.low, row.amount);
        seen.high = Math.max(seen.high, row.amount);
        missions.set(row.what, seen);
    }

    return {
        missions: [...missions.values()]
            .map((m) => Object.assign(m, { average: Math.round(m.total / m.runs) }))
            .sort((a, b) => b.runs - a.runs || b.total - a.total),
        patients,
        ignored,
        spent,
        lines: rows.length,
        /* Every kind of line the ledger holds, by the game's own wording, with
         * every figure in the text taken out. Missions are in here too, because
         * telling a mission name from a payout kind by looking at it is exactly
         * the guess that has to stop. */
        kinds: [...kinds.values()].sort((a, b) => b.lines - a.lines),
    };
}

/* --------------------------------------------------------------- recording */

let toHooked = false;
let toOriginals = null;
let toBalance = null;
let toPending = [];
/** Mission ids already counted, so the game announcing one twice counts once. */
const toRecent = new Map();

/** The account balance, from the game's own endpoint rather than off the page. */
async function toReadBalance() {
    try {
        const res = await fetch('/api/credits', { credentials: 'same-origin' });
        const data = await res.json();
        const value = data.credits_user_current ?? data.credits_user_total ?? data.credits;
        return typeof value === 'number' ? value : null;
    } catch (err) {
        return null;
    }
}

/**
 * A mission ended. Hold it open for the balance to say what it paid.
 *
 * The type id is read off the panel before the game takes it away — it is the
 * key into /einsaetze.json, where the name and the listed figure live, so
 * nothing has to be read out of the page's text.
 *
 * THE SAME MISSION IS ANNOUNCED MORE THAN ONCE. The first run recorded 15
 * endings that were really 9 missions: six of them arrived twice, and because
 * a second ending inside the window marked both unattributable, every
 * duplicated mission measured nothing. A mission can only end once, so the
 * instance id is remembered and a repeat is dropped.
 */
/**
 * Missions one of your own vehicles was sent to.
 *
 * `missionDelete` says a mission ended, not that you were in it. An alliance
 * call somebody else handled ends on your map exactly like one of yours, and
 * counting those made "what you have run" a count of what your alliance has
 * run.
 *
 * Written from inside the mission window, where the answer is plain: the ids in
 * `/api/vehicles` are yours, and `#mission_vehicle_at_mission` says which
 * vehicles are there. An id in both is your vehicle at that mission. Pressing
 * one of the game's dispatch buttons says the same thing a moment earlier.
 *
 * Nothing is inferred from the map: a mission you never opened and never sent
 * to is simply not marked, and the panel counts it as unknown rather than as
 * yours.
 */
const TO_MINE_KEY = 'ymca-trackops-mine';
const TO_MINE_MAX = 400;

function toMarkMine(missionId) {
    const id = String(missionId || '');
    if (!id) return;
    const mine = toRead(TO_MINE_KEY, []);
    if (mine.includes(id)) return;
    mine.push(id);
    toWrite(TO_MINE_KEY, mine.slice(-TO_MINE_MAX));
}

const toIsMine = (id) => toRead(TO_MINE_KEY, []).includes(String(id));

function toMissionEnded(missionId) {
    const id = String(missionId);
    const at = Date.now();

    if (toPending.some((e) => e.mission === id)) return;
    if (toRecent.get(id) > at - TO_DEDUPE_MS) return;
    toRecent.set(id, at);
    for (const [key, when] of toRecent) if (when < at - TO_DEDUPE_MS) toRecent.delete(key);

    const panel = document.getElementById(`mission_${id}`);
    const type = panel?.getAttribute('mission_type_id') || null;
    if (type === null) return; // not one of ours, or already gone

    const entry = {
        mission: id, at, type: Number(type) || type, delta: null,
        alone: toPending.length === 0,
        mine: toIsMine(id),
    };
    /* Something else already waiting means a balance change could belong to
     * either, so neither is trusted for the averages — it is still counted. */
    if (toPending.length) for (const other of toPending) other.alone = false;
    toPending.push(entry);

    setTimeout(() => {
        toPending = toPending.filter((e) => e !== entry);
        const log = toRead(TO_LOG_KEY, []);
        log.push({
            at: entry.at, mission: entry.mission, type: entry.type,
            delta: entry.delta, alone: entry.alone, mine: entry.mine,
        });
        toWrite(TO_LOG_KEY, log.slice(-TO_LOG_MAX));
    }, TO_SETTLE_MS);
}

/**
 * The balance changed. Give it to whatever ended just before it.
 *
 * One rise belongs to one mission, so it goes to the longest-waiting ending
 * that has not been paid yet. The first version added every rise to every
 * pending mission, which double-counted the moment two ended together.
 *
 * A rise while nothing is pending is the player selling or being paid for
 * something else, and is simply the new baseline. A fall is never a payout.
 */
function toCreditsChanged(next) {
    if (typeof next !== 'number' || !isFinite(next)) return;
    const previous = toBalance;
    toBalance = next;
    if (previous === null) return;
    const delta = next - previous;
    if (delta <= 0) return;
    const waiting = toPending.filter((e) => e.delta === null);
    if (!waiting.length) return;
    waiting[0].delta = delta;
}

/**
 * Hook the game's own functions.
 *
 * Wrapped, never replaced: the original is called first and its return value
 * handed back, so the game behaves exactly as it would without YMCA. If the
 * game ever stops defining them, nothing is hooked and "Check the hooks" says
 * so rather than the counter silently staying at zero.
 */
function toAttach() {
    if (toHooked || !TO_MAIN_PAGE.test(location.pathname)) return;
    const w = (typeof unsafeWindow !== 'undefined' ? unsafeWindow : window);
    if (typeof w.missionDelete !== 'function') return;

    toOriginals = { target: w, missionDelete: w.missionDelete, creditsUpdate: w.creditsUpdate };

    w.missionDelete = function (...args) {
        const result = toOriginals.missionDelete.apply(this, args);
        try { toMissionEnded(args[0]); } catch (e) { /* never break the game's own call */ }
        return result;
    };

    /* creditsUpdate is what a mission window tells the page it is inside —
     * tellParent('creditsUpdate(2283098);') — so it carries the balance the
     * moment it changes, which no amount of polling can. */
    if (typeof w.creditsUpdate === 'function') {
        w.creditsUpdate = function (...args) {
            const result = toOriginals.creditsUpdate.apply(this, args);
            try { toCreditsChanged(Number(args[0])); } catch (e) { /* as above */ }
            return result;
        };
    }

    toHooked = true;
    toReadBalance().then((v) => { if (toBalance === null) toBalance = v; });
}

function toDetach() {
    if (!toHooked || !toOriginals) return;
    toOriginals.target.missionDelete = toOriginals.missionDelete;
    if (typeof toOriginals.creditsUpdate === 'function') {
        toOriginals.target.creditsUpdate = toOriginals.creditsUpdate;
    }
    toOriginals = null;
    toHooked = false;
}

/**
 * Inside a mission window: was one of your own vehicles there?
 *
 * Two signals, both measured, neither asking the player anything.
 *
 * Pressing any of the game's five dispatch controls sends what is ticked, and
 * what is ticked is yours — the selection table only ever lists your own
 * vehicles. That marks the mission immediately.
 *
 * The other is for a mission you joined earlier and reopened: `/api/vehicles`
 * is your fleet, `#mission_vehicle_at_mission` and `#mission_vehicle_driving`
 * are the vehicles there and on the way, and an id in both is yours. The fleet
 * list is the one YMCA already caches, so this costs no extra request.
 */
const TO_DISPATCH = '#mission-form input[name="commit"], .alert_next, .alert_next_alliance,'
    + ' #mission_alarm_btn, #mission_alarm_btn_mobile';

YMCA.inject('trackops', (ctx) => {
    const info = document.getElementById('mission_general_info');
    if (!info || !document.getElementById('mission-form')) return;

    const missionId = (/\/missions\/(\d+)/.exec(location.pathname) || [])[1]
        || info.getAttribute('mission_id') || null;
    if (!missionId) return;

    document.addEventListener('click', (e) => {
        if (!e.target?.closest?.(TO_DISPATCH)) return;
        toMarkMine(missionId);
        ctx.log.info('trackops', `mission ${missionId} is yours — you dispatched to it`);
    }, true);

    /* And for one you are already in. Re-checked as the tables fill, because
     * the vehicles at a mission arrive after the page does. */
    const check = async () => {
        if (toIsMine(missionId)) return;
        let fleet;
        try {
            // `shrink` is handed the whole answer, not each row, and only the ids are wanted.
            fleet = await ctx.gameCached('/api/vehicles', 6 * 3600e3,
                (data) => (Array.isArray(data) ? data.map((v) => String(v.id)) : []));
        } catch (err) { return; }
        const own = new Set(Array.isArray(fleet) ? fleet.map(String) : []);
        if (!own.size) return;
        const rows = document.querySelectorAll(
            '#mission_vehicle_at_mission tbody tr[id^="vehicle_row"], '
            + '#mission_vehicle_driving tbody tr[id^="vehicle_row"]');
        for (const row of rows) {
            if (own.has(row.id.replace('vehicle_row_', ''))) {
                toMarkMine(missionId);
                ctx.log.info('trackops', `mission ${missionId} is yours — your vehicle is there`);
                return;
            }
        }
    };
    check();
    const watcher = new MutationObserver(() => check());
    watcher.observe(document.body, { childList: true, subtree: true });
    setTimeout(() => watcher.disconnect(), 120000);
    return true;
});

/* The game defines its functions as the page finishes loading, which can be
 * after this file runs. Try now, then a few times, then give up quietly —
 * "Check the hooks" is there to say what happened. */
if (toCfg().recording && TO_MAIN_PAGE.test(location.pathname)) {
    let tries = 0;
    const attempt = () => {
        toAttach();
        if (!toHooked && (tries += 1) < 10) setTimeout(attempt, 1000);
    };
    attempt();
}

/* --------------------------------------------------------------------------
 * ElementFriend — the switchboard.
 *
 * Not a tool. A page of element tiles, one per part of YMCA that the player
 * may or may not want, each with a switch on its face and its own settings
 * behind it.
 *
 * WHY IT EXISTS. YMCA grew a tool at a time and every one of them landed on
 * the front page whether or not anybody asked for it. MissionMagician draws
 * itself into the mission window, TrackOps hooks the game's own functions,
 * RelabelTable renames things — those are not equally welcome to everyone, and
 * a tool set that cannot be turned down is a tool set somebody uninstalls
 * whole. So the switch, not the uninstall.
 *
 * WHAT A SWITCH ACTUALLY DOES. Both halves of a module: the tile disappears
 * from the launcher AND `YMCA.inject` refuses to run it, so nothing of it
 * reaches the game's page either. A switch that left the mission panel behind
 * would be switching off the part nobody looks at.
 *
 * THE SWITCHBOARD IS THE SHELL'S, NOT THIS MODULE'S. `YMCA.isOn` is read by
 * the launcher and by injection, both of which run before any module mounts.
 * ElementFriend is only the face of it, so a module that goes does not take
 * the state of every other one with it.
 *
 * TWO KINDS OF TILE. A module with `mainTile: false` — HighFive — lives only
 * here, because its work happens in the game's own page and a launcher tile
 * for it would open a panel that does nothing. Everything else keeps its main
 * tile and is listed here as well, so the one page answers "what have I got
 * switched on" without going looking.
 *
 * SETTINGS BELONG TO THE MODULE. A module may declare `settings(el, ctx)`, and
 * what it writes goes into its OWN namespace — `YMCA.contextFor(mod.id)`, not
 * ElementFriend's store — so the module reads its settings back without
 * knowing this page exists.
 * ------------------------------------------------------------------------ */

/**
 * The modules that carry a switch, minus the ones that belong to a group.
 *
 * A group is a tile of its own — EagleEye is the first — and its members are
 * listed inside it. Otherwise the switchboard grows a row per tweak and stops
 * being a page anybody can take in.
 */
function efElements() {
    return YMCA.modules.filter((m) => m.optional && !m.group);
}

function efSwitch(id, on, label) {
    return `<label class="ymca-switch" data-sw="${esc(id)}">
      <input type="checkbox" ${on ? 'checked' : ''}><i></i>
      <span class="ymca-sw-text">${esc(label || (on ? 'On' : 'Off'))}</span>
    </label>`;
}

/** Wire every switch inside `root`. `after` is told which module changed. */
function efWireSwitches(root, ctx, after) {
    root.querySelectorAll('.ymca-switch[data-sw] input').forEach((box) => {
        box.addEventListener('change', () => {
            const label = box.closest('.ymca-switch');
            const id = label.dataset.sw;
            YMCA.switchElement(id, box.checked);
            const text = label.querySelector('.ymca-sw-text');
            if (text) text.textContent = box.checked ? 'On' : 'Off';
            const mod = YMCA.modules.find((m) => m.id === id);
            ctx.status(`${mod ? mod.title : id} is ${box.checked ? 'on' : 'off'}.`);
            if (after) after(id, box.checked);
        });
    });
}

/**
 * One tile: what it is, what it does in a sentence or three, and its switch.
 *
 * THE DESCRIPTION IS THE POINT OF THE PAGE. A tagline of four words tells
 * somebody which tool this is and nothing about whether they want it, and "do
 * I want it" is the only question this page exists to answer. So the tile
 * carries the module's own `description` — the same sentences its own panel
 * heads itself with, so there is one wording to keep true rather than two.
 *
 * A GROUP SAYS WHAT IS IN IT instead, by name. "Switch this off and every one
 * of them goes" means nothing until the list is on the tile.
 */
function efTile(m) {
    const on = YMCA.isOn(m);
    const inside = YMCA.inGroup ? YMCA.inGroup(m.id) : [];
    const holds = inside.length
        ? `<span class="ymca-dim" style="font-size:12px">Holds ${
            inside.map((x) => esc(x.title)).join(', ')}</span>`
        : '';
    return `<div class="ymca-tile el ${on ? '' : 'off'}" data-el="${esc(m.id)}"
      role="button" tabindex="0">
      ${iconFor(m.id)}<b>${esc(m.title)}</b>
      <span>${esc(m.description || m.tagline || '')}</span>
      ${holds}
      ${!inside.length && m.mainTile === false
        ? '<span class="ymca-dim" style="font-size:12px">Lives in the game’s own pages</span>'
        : ''}
      <div class="ymca-foot">
        <span class="ymca-dim" style="font-size:12px">${m.settings
        ? 'Open for settings' : 'Nothing to set'}</span>
        ${efSwitch(m.id, on)}
      </div>
    </div>`;
}

/**
 * A group's own page of tiles — one renderer, not one per group.
 *
 * EagleEye had a copy of this inside it, and the moment EasyEdit wanted the
 * same page there would have been two copies to keep in step. Any group gets
 * it by calling this from its `settings`.
 */
function efGroupTiles(el, ctx, groupId, lead) {
    const inside = YMCA.inGroup(groupId);
    el.innerHTML = `
    <p class="ymca-lead">${esc(lead)}</p>
    <div class="ymca-tiles">
      ${inside.map(efTile).join('')}
      <div class="ymca-tile soon">${iconFor('default')}<b>More to come</b>
        <span>This is where the next ones land.</span></div>
    </div>`;

    /* A member's settings replace the whole panel, and Back comes here rather
     * than all the way out to the switchboard. */
    const panel = el.closest('#ymca-panel') || el;
    const self = YMCA.modules.find((m) => m.id === groupId);
    el.querySelectorAll('[data-el]').forEach((tile) => {
        tile.addEventListener('click', (e) => {
            if (e.target.closest('.ymca-switch')) return;
            const mod = YMCA.modules.find((m) => m.id === tile.dataset.el);
            if (mod) {
                efOpen(panel, ctx, mod,
                    () => efOpen(panel, YMCA.contextFor(groupId), self));
            }
        });
    });
    efWireSwitches(el, ctx, (id, on) => {
        el.querySelector(`[data-el="${id}"]`)?.classList.toggle('off', !on);
    });
}

function efTiles(el, ctx) {
    const mods = efElements();
    el.innerHTML = `
    <p class="ymca-lead">Everything YMCA is made of, one tile each. A switch takes that part
      out of the launcher <em>and</em> out of the game's own pages &mdash; nothing of it runs.
      Open a tile for what it can be set to.</p>
    <div class="ymca-tiles">
      ${mods.map(efTile).join('')}
      <div class="ymca-tile soon">${iconFor('default')}<b>More to come</b>
        <span>This is where the next elements land.</span></div>
    </div>`;

    // The switch is inside the tile, so the tile's own click has to stand aside
    // for it — otherwise flicking the switch also opens the settings.
    const open = (id) => {
        const mod = YMCA.modules.find((m) => m.id === id);
        if (mod) efOpen(el, ctx, mod);
    };
    el.querySelectorAll('[data-el]').forEach((tile) => {
        tile.addEventListener('click', (e) => {
            if (e.target.closest('.ymca-switch')) return;
            open(tile.dataset.el);
        });
        tile.addEventListener('keydown', (e) => {
            if (e.key !== 'Enter' && e.key !== ' ') return;
            if (e.target.closest('.ymca-switch')) return;
            e.preventDefault();
            open(tile.dataset.el);
        });
    });
    efWireSwitches(el, ctx, (id, on) => {
        el.querySelector(`[data-el="${id}"]`)?.classList.toggle('off', !on);
    });
}

function efOpen(el, ctx, mod, back) {
    const on = YMCA.isOn(mod);
    el.innerHTML = `
    <div class="ymca-row" style="justify-content:space-between;margin-bottom:12px">
      <button class="ymca-btn" id="ef-back">&larr; ${back ? 'Back' : 'All elements'}</button>
      ${efSwitch(mod.id, on, on ? 'On' : 'Off')}
    </div>
    <div class="ymca-card">
      <b style="font-size:15px">${esc(mod.title)}</b>
      <div class="ymca-dim" style="font-size:13px;margin-top:3px">${esc(mod.description || '')}</div>
    </div>
    <div id="ef-body"></div>`;

    el.querySelector('#ef-back').addEventListener('click', () => {
        if (back) back(); else efTiles(el, ctx);
    });
    efWireSwitches(el, ctx);

    const body = el.querySelector('#ef-body');
    if (!mod.settings) {
        body.innerHTML = `<div class="ymca-note">Nothing to set here. The switch is the whole
      of it: on and ${esc(mod.title)} is in the launcher${mod.mainTile === false
    ? '' : ' and in the game’s pages'}, off and it is not.</div>`;
        return;
    }
    /* A module's settings write into the module's own namespace, so it reads
     * them back without knowing this page exists. A throw here shows an error
     * and leaves the rest of the switchboard standing. */
    const failed = (err) => {
        logger.error('elementfriend', `${mod.id} settings failed`, err.stack || err.message);
        body.innerHTML = `<div class="ymca-note bad"><b>${esc(mod.title)}’s settings could
      not open.</b> ${esc(err.message)}<br>The switch above still works.</div>`;
    };
    /* A settings page that reads the game fails as a rejected promise, long
     * after the try block has closed, so both routes land on the same notice. */
    try {
        const running = mod.settings(body, YMCA.contextFor(mod.id));
        if (running && typeof running.then === 'function') running.catch(failed);
    } catch (err) {
        failed(err);
    }
}

YMCA.register({
    id: 'elementfriend',
    title: 'ElementFriend',
    tagline: 'What you want switched on',
    description: 'One page for every part of YMCA you can turn down, and the settings that '
        + 'belong to each of them.',

    async mount(el, ctx) {
        efTiles(el, ctx);
    },
});

/* --------------------------------------------------------------------------
 * Status 5 Helper (id: highfive) — clicking through the transports.
 *
 * Status 5 is a vehicle transporting: an ambulance taking a patient to a
 * hospital, a patrol car taking somebody to a prison. Each one wants a
 * destination picked, and picking it one vehicle at a time means going back to
 * the list and finding the next. LSS-Manager's version jumps straight to the
 * next vehicle in status 5 after each pick, so the whole queue is clicked
 * through in one place. That is what this is for.
 *
 * WHICH FIELD CARRIES THE STATUS IS ANSWERED. The first fleet capture came
 * back with `fms_real` and `fms_show` on every vehicle, both running 1 to 6
 * across a fleet of 83, so the status is the game's own field and 5 is a value
 * it really takes. Nothing here guesses at it any more, and the capture button
 * that found it stays for the day the field is renamed. `hospital_*` and
 * `police_cell_*` sit on the same record, which is where the two branches of
 * status 5 are told apart.
 *
 * So FINDING the vehicles works: the list below is read from `/api/vehicles`.
 *
 * AND THE GAME ADVANCES ITSELF, which is the whole trick. A transporting
 * vehicle's page carries
 *
 *     <a class="btn btn-success" id="next-vehicle-fms-5"
 *        href="/vehicles/15079875">Go to the next vehicle with a transport request</a>
 *
 * so the next vehicle in status 5 is a link the game has already worked out.
 * Nothing has to be searched for and nothing has to be guessed: HighFive reads
 * that href before the pick and follows it after, which is the one button
 * LSS-Manager presses for you.
 *
 * **IT NEVER PICKS, AND IT NEVER FETCHES THE PICK.** The destination is a plain
 * `<a href="/vehicles/<id>/patient/<hospital>">` and the player clicks it
 * themselves; HighFive only remembers where "next" pointed and goes there
 * afterwards. Doing the GET on their behalf would be writing something that
 * cannot be taken back, and a failed fetch would leave a patient untransported
 * while the panel moved on. Navigating is not writing.
 *
 * The jump is one-shot and it checks first: if the game already landed on the
 * vehicle it was going to send you to, it does nothing rather than skipping one.
 * It also expires, so a flag left behind cannot hijack a navigation minutes
 * later.
 *
 * WHAT IS STILL MISSING IS THE FILTERING. A range — "only hospitals within so
 * far" — needs to know which cell of that table carries the distance, and the
 * rows carry no class at all (`rowClasses: {}` on a page with 35 destinations).
 * So the capture asks for the table's own shape and the filter waits for it.
 * `hospital_max_distance`, `hospital_max_price` and `hospital_own` sit on the
 * vehicle in `/api/vehicles`, which is where the game keeps that setting
 * itself.
 *
 * THE FIRST CAPTURE WAS TAKEN ON THE MAP, which is why it came back with 67
 * building links and no destinations. The panel says where it is being pressed
 * now, so that round trip is not repeated.
 * ------------------------------------------------------------------------ */

/** Digits out: a path is reported as a shape, not as a particular vehicle. */
const hfShape = (s) => String(s || '').replace(/\d+/g, '#').slice(0, 80);

function hfTally(list, cap) {
    const counts = new Map();
    for (const item of list) counts.set(item, (counts.get(item) || 0) + 1);
    return Object.fromEntries([...counts.entries()]
        .sort((a, b) => b[1] - a[1]).slice(0, cap));
}

/**
 * The page YMCA is open over.
 *
 * YMCA's window is a lightbox on top of the game, so everything below it is
 * still in the document — a capture pressed here reads the vehicle page behind
 * it. That is why this does not need to be injected into the game's markup to
 * work.
 */
/**
 * The page's own answer to "is this a vehicle waiting for a destination".
 *
 * THE GAME NAMES THE TWO BRANCHES IN TWO LANGUAGES. A hospital is
 * `/vehicles/<id>/patient/<hospital>` and a prison is
 * `/vehicles/<id>/gefangener/<cell>` — the German word, in an English game,
 * exactly as `gw_gefahrgut` turned up in a requirement list. Matching only the
 * English one is why the ambulances advanced and the patrol cars did not.
 * Neither word is guessed at: both came off a capture.
 */
const HF_BRANCHES = ['patient', 'gefangener'];
const HF_PICK_LINK = HF_BRANCHES.map((w) => `a[href*="/${w}/"]`).join(', ');
const HF_PICKED = new RegExp(`^/vehicles/\\d+/(${HF_BRANCHES.join('|')})/-?\\d+`);
const HF_NEXT = '#next-vehicle-fms-5';

function hfCapturePage() {
    const classOf = (el) => (typeof el.className === 'string' ? el.className.trim().slice(0, 100) : '');

    const links = [...document.querySelectorAll('a[href]')]
        .map((a) => hfShape((a.getAttribute('href') || '').split('?')[0]))
        .filter((h) => h && h !== '#');

    const forms = [...document.querySelectorAll('form')].slice(0, 8).map((f) => ({
        id: hfShape(f.id) || undefined,
        class: classOf(f) || undefined,
        action: hfShape((f.getAttribute('action') || '').split('?')[0]),
        method: f.getAttribute('method') || 'get',
        // Names only. A value here could be a CSRF token or a caption.
        fieldNames: [...new Set([...f.elements].map((x) => x.name).filter(Boolean))].slice(0, 25),
    }));

    return {
        path: hfShape(location.pathname),
        inFrame: window.top !== window.self,
        /* Where a destination is picked will be one of these shapes. */
        linkShapes: hfTally(links, 45),
        idShapes: hfTally([...document.querySelectorAll('[id]')]
            .map((el) => hfShape(el.id)).filter(Boolean), 45),
        rowClasses: hfTally([...document.querySelectorAll('tr')]
            .map(classOf).filter(Boolean), 25),
        panelClasses: hfTally([...document.querySelectorAll('.panel, .box, .alert, .list-group')]
            .map(classOf).filter(Boolean), 25),
        tableCount: document.querySelectorAll('table').length,
        forms,
        /* WHAT THE RANGE FILTER IS WAITING FOR. 35 destinations came back with
         * no class on a single row, so which cell carries the distance cannot
         * be found by name. This asks the row itself: how many cells, what each
         * is called, and whether it holds digits or words. Never a hospital
         * name, never a distance, never a price — only the shape of the cell
         * one of them is in. */
        destinations: (() => {
            const link = document.querySelector(HF_PICK_LINK);
            const row = link?.closest('tr');
            const table = link?.closest('table');
            if (!link) return 'no destination link on this page';
            if (!row) {
                const up = link.parentElement;
                return { noRow: true, parent: up
                    ? { tag: up.tagName.toLowerCase(), class: classOf(up) || undefined } : null };
            }
            return {
                rows: table ? table.querySelectorAll('tr').length : null,
                tableId: hfShape(table?.id) || undefined,
                tableClass: classOf(table) || undefined,
                /* The headings, because they are what says which column is the
                 * distance — a number cannot say that about itself. */
                headings: [...(table?.querySelectorAll('thead th, thead td') || [])]
                    .map((th) => (th.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 40)),
                rowAttributes: [...row.attributes].map((a) => a.name),
                cells: [...(row.cells || [])].map((c) => ({
                    tag: c.tagName.toLowerCase(),
                    class: classOf(c) || undefined,
                    attributes: [...c.attributes].map((a) => a.name),
                    digits: /\d/.test(c.textContent || ''),
                    words: /[a-z]{4}/i.test(c.textContent || ''),
                    controls: [...c.querySelectorAll('a,button,input,span[id]')]
                        .map((x) => `${x.tagName.toLowerCase()}${hfShape(x.id) ? `#${hfShape(x.id)}` : ''}.${classOf(x)}`)
                        .slice(0, 4),
                })),
                /* FOUND, NOT NAMED. `own-hospitals` and `alliance-hospitals` were
                 * a list of ids to look for, which answers nothing on a prison
                 * page. Every element carrying an id and holding destinations
                 * is reported instead, so whatever the other branch calls its
                 * halves names itself. */
                sections: [...document.querySelectorAll('[id]')]
                    .map((el) => ({ el, n: el.querySelectorAll(HF_PICK_LINK).length }))
                    .filter(({ el, n }) => n && el.tagName !== 'BODY')
                    .slice(0, 12)
                    .map(({ el, n }) => ({
                        id: hfShape(el.id),
                        tag: el.tagName.toLowerCase(),
                        class: classOf(el) || undefined,
                        holdsLinks: n,
                    })),
            };
        })(),
        /* WHAT A BLOCK SAYS, WITHOUT SAYING IT. The prison list states every
         * figure inside the link's own text, so the wording is the structure —
         * and the wording is the game's, the same for every player. The name is
         * the alliance's building and is never carried: piece one is replaced
         * by its length, every digit in the rest is shaped out, and only the
         * first few blocks are reported. */
        destinationBlocks: [...document.querySelectorAll(HF_PICK_LINK)]
            .map(hfBlockOf).filter(Boolean)
            .filter((el, i, all) => all.indexOf(el) === i)
            .slice(0, 3)
            .map((el) => {
                const parts = hfParts(el);
                return {
                    tag: el.tagName.toLowerCase(),
                    class: classOf(el) || undefined,
                    isRow: !!el.cells,
                    nameLength: (parts[0] || '').length,
                    pieces: parts.slice(1).map((t) => t.replace(/\d+/g, '#').slice(0, 40)),
                };
            }),
        hasNextButton: !!document.querySelector(HF_NEXT),
    };
}

/**
 * The fields the first capture found carrying the status, in the order they
 * are trusted. `fms_real` is what the vehicle IS; `fms_show` is what the game
 * displays, which can lag it.
 */
const HF_STATUS_FIELDS = ['fms_real', 'fms_show'];
const HF_TRANSPORTING = 5;

/** Your vehicles in status 5, as the game's own field reports them. */
function hfTransporting(vehicles) {
    return (vehicles || []).filter((v) => HF_STATUS_FIELDS
        .some((f) => Number(v?.[f]) === HF_TRANSPORTING));
}

/**
 * What the fleet says about status, without saying anything about the fleet.
 *
 * A field is reported only when the whole fleet has few distinct values for it
 * and all of them are small integers. A status looks like that; a vehicle id,
 * a building id and a set of coordinates do not, so they are left out by the
 * shape of the test rather than by a list of names to avoid.
 */
function hfCaptureFleet(vehicles) {
    const fields = new Map();
    for (const v of vehicles.slice(0, 600)) {
        for (const [key, value] of Object.entries(v || {})) {
            if (!fields.has(key)) fields.set(key, { values: new Map(), kinds: new Set() });
            const f = fields.get(key);
            f.kinds.add(value === null ? 'null' : typeof value);
            /* An id names the player's own things, so it never gets a
             * histogram however small it happens to be on a small fleet. A
             * status field is not called an id, so nothing is lost. */
            const isIdentifier = key === 'id' || /(^|_)id$/.test(key);
            if (!isIdentifier && typeof value === 'number' && Number.isInteger(value)
                && value >= -1 && value <= 30) {
                f.values.set(value, (f.values.get(value) || 0) + 1);
            }
        }
    }
    const statusLike = {};
    for (const [key, f] of fields) {
        if (f.values.size && f.values.size <= 12) {
            statusLike[key] = Object.fromEntries([...f.values.entries()].sort((a, b) => a[0] - b[0]));
        }
    }
    return {
        vehicleCount: vehicles.length,
        fieldNames: [...fields.keys()].sort(),
        // key -> { value: how many vehicles }. The field carrying 5 names itself.
        smallIntegerFields: statusLike,
    };
}

function hfPanel(el, ctx) {
    const onVehiclePage = /^\/vehicles\/\d+/.test(location.pathname);
    el.innerHTML = `
    <div class="ymca-card">
      <b>Transporting right now</b>
      <p class="ymca-dim" style="margin:6px 0 9px">Your vehicles in status 5, read from the
        game's own <code>fms_real</code>. Each one opens where the destination is picked.</p>
      <div id="hf-list"><span class="ymca-dim">Reading your fleet\u2026</span></div>
      <button class="ymca-btn" data-do="again" style="margin-top:10px">Read it again</button>
    </div>

    <div class="ymca-card">
      <b>After you pick</b>
      <label style="display:block;margin-top:6px;font-weight:400;cursor:pointer">
        <input type="checkbox" data-cfg="advance"> Go straight to the next transport</label>
      <label style="display:block;margin-top:6px;font-weight:400;cursor:pointer">
        <input type="checkbox" data-cfg="closeWhenDone"> Close the window when there is nothing
        left</label>
      <label style="display:block;margin-top:10px">Never further than
        <input type="number" data-max min="0" step="1" style="width:74px;margin:0 6px"
          value="${hfCfg(ctx).max > 0 ? Number(hfCfg(ctx).max) : ''}" placeholder="any">
        <span class="ymca-dim">of whatever the distance column counts in</span></label>
      <label style="display:block;margin-top:10px">Wait before closing
        <input type="range" data-wait min="0" max="2000" step="50"
          value="${Number.isFinite(Number(hfCfg(ctx).closeAfter))
        ? Number(hfCfg(ctx).closeAfter) : HF_CLOSE_DEFAULT}" style="vertical-align:middle;
          width:200px;margin:0 8px">
        <b data-wait-shows></b></label>
      <p class="ymca-dim" style="margin:6px 0 0;font-size:12px">The game works out which vehicle
        is next and links to it; this follows that link once you have picked. It never picks for
        you and never repeats your click \u2014 assigning a hospital cannot be undone. The wait
        is only long enough to be sure nothing moved you on; if it closes too early, push it up
        and tell me the number that worked.</p>
    </div>

    <div class="ymca-card">
      <b>Sorting and filtering</b>
      <p class="ymca-dim" style="margin:6px 0 0">The controls sit on the vehicle's own page,
        above the destinations. Which column is the distance is not something the page says
        anywhere &mdash; not one row carries a class &mdash; so the table is asked instead: its
        own headers name the columns, and any column whose cells read as numbers can be sorted
        by. <b>Show the first 10</b> is the range: sort by distance and the far ones are gone.
        Yours and the alliance's can be separated where the page marks them.</p>
      <div id="hf-last" class="ymca-dim" style="font-size:12px;margin-top:9px"></div>
    </div>

    <div class="ymca-card">
      <b>Send the missing piece</b>
      <p class="ymca-dim" style="margin:6px 0 9px">Open one of the vehicles above, leave that
        page open, open YMCA from the navbar and press this. It copies <em>structure</em>: path
        shapes, element names, form field names. No hospital names, no patients, no addresses,
        no vehicle names.</p>
      <div class="ymca-row">
        <button class="ymca-btn ${onVehiclePage ? 'primary' : ''}" data-do="capture"
          >Copy this vehicle window</button>
        <button class="ymca-btn" data-do="fleet">Copy what your fleet says about status</button>
      </div>
      <p class="${onVehiclePage ? 'ymca-dim' : 'ymca-warn'}" style="margin:9px 0 0;font-size:12px"
        id="hf-where"></p>
    </div>`;

    /* Where it is being pressed, said before it is pressed. The first capture
     * came back from the map with 67 building links and no destinations, and
     * that was a whole round trip spent on a button that should have said so. */
    el.querySelector('#hf-where').textContent = onVehiclePage
        ? `You are on ${hfShape(location.pathname)} \u2014 this is the page to capture.`
        : `You are on ${hfShape(location.pathname)}, which is not a vehicle page. Capturing from `
          + 'here answers nothing about transporting; open a vehicle above first.';

    const paint = async () => {
        const list = el.querySelector('#hf-list');
        try {
            const moving = hfTransporting(await ctx.game('/api/vehicles'));
            list.innerHTML = moving.length
                ? `<div class="ymca-pick">${moving.map((v) => `<div><a href="/vehicles/${
                    encodeURIComponent(v.id)}" class="ymca-accent">${ctx.esc(v.caption || `#${v.id}`)
                }</a> <small>${ctx.esc(v.vehicle_type_caption || '')}</small></div>`).join('')}</div>
          <p class="ymca-dim" style="margin:8px 0 0;font-size:12px">${moving.length}
            transporting.</p>`
                : '<span class="ymca-dim">Nothing of yours is in status 5 right now.</span>';
        } catch (err) {
            list.innerHTML = `<span class="ymca-bad">Your fleet could not be read (${
                ctx.esc(err.message)}).</span>`;
        }
    };
    paint();

    const last = ctx.store.read('lastRun', null);
    el.querySelector('#hf-last').innerHTML = last
        ? `Last transport page seen ${ctx.esc(new Date(last.at).toLocaleString())}:
       ${last.destinations} destinations,
       ${last.namesNextVehicle ? 'the page named a next vehicle'
        : '<b>the page named no next vehicle</b>, so there was nowhere to go on to'},
       ${last.sortableColumns.length
        ? `sortable by ${ctx.esc(last.sortableColumns.join(', '))}`
        : 'no column read as a number'}.`
        : 'No transport page seen yet. Open a vehicle that is transporting.';

    const ceiling = el.querySelector('[data-max]');
    ceiling.addEventListener('input', () => {
        ctx.store.write('cfg', { ...hfCfg(ctx), max: Number(ceiling.value) || 0, seeded: 1 });
        ctx.status(ceiling.value ? `At most ${ceiling.value}.` : 'No ceiling.');
    });

    const wait = el.querySelector('[data-wait]');
    const shows = el.querySelector('[data-wait-shows]');
    const sayWait = () => { shows.textContent = `${wait.value} ms`; };
    sayWait();
    wait.addEventListener('input', sayWait);
    wait.addEventListener('change', () => {
        ctx.store.write('cfg', { ...hfCfg(ctx), closeAfter: Number(wait.value) });
        ctx.status(`Closing after ${wait.value} ms.`);
    });

    el.querySelectorAll('[data-cfg]').forEach((box) => {
        box.checked = hfCfg(ctx)[box.dataset.cfg] !== false;
        box.addEventListener('change', () => {
            ctx.store.write('cfg', { ...hfCfg(ctx), [box.dataset.cfg]: box.checked });
            ctx.status(box.checked ? 'On.' : 'Off.');
        });
    });

    el.addEventListener('click', async (e) => {
        const btn = e.target.closest('[data-do]');
        if (!btn) return;
        if (btn.dataset.do === 'again') { paint(); return; }
        if (btn.dataset.do === 'capture') {
            const report = { ymca: YMCA.version, what: 'highfive-window', at: new Date().toISOString(), onVehiclePage, ...hfCapturePage() };
            ctx.store.write('lastCapture', report);
            ctx.log.info('captured a vehicle window', report.path);
            ctx.clipboard(JSON.stringify(report, null, 2), 'the vehicle window\u2019s structure');
            return;
        }
        if (btn.dataset.do === 'fleet') {
            ctx.status('Reading your fleet\u2026');
            try {
                const vehicles = await ctx.game('/api/vehicles');
                const report = { ymca: YMCA.version, what: 'highfive-fleet', at: new Date().toISOString(), transporting: hfTransporting(vehicles).length, ...hfCaptureFleet(vehicles || []) };
                ctx.store.write('lastFleet', report);
                ctx.clipboard(JSON.stringify(report, null, 2), 'what your fleet says about status');
            } catch (err) {
                ctx.status('The fleet could not be read.');
                ctx.log.error('fleet capture failed', err.message);
            }
        }
    });
}

/* ------------------------------------------------- going to the next one */

/**
 * Where the jump is remembered between two page loads.
 *
 * sessionStorage rather than a variable, because the pick navigates: the page
 * that reads this is not the page that wrote it. It is one-shot and it expires,
 * so a flag left behind by a click the player thought better of cannot take
 * over a navigation two minutes later.
 */
const HF_JUMP_KEY = 'ymca-highfive-jump';
const HF_JUMP_GOOD_FOR = 30e3;

function hfCfg(ctx) {
    return ctx.store.read('cfg', { advance: true });
}

function hfArmJump(href) {
    try {
        sessionStorage.setItem(HF_JUMP_KEY, JSON.stringify({
            href, path: new URL(href, location.origin).pathname, at: Date.now(),
        }));
    } catch (e) { /* private window: the jump simply does not happen */ }
}

function hfTakeJump() {
    let held = null;
    try {
        held = JSON.parse(sessionStorage.getItem(HF_JUMP_KEY));
        // Taken, not read: one-shot, so a jump that fails cannot loop.
        sessionStorage.removeItem(HF_JUMP_KEY);
    } catch (e) {
        return null;
    }
    if (!held || Date.now() - held.at > HF_JUMP_GOOD_FOR) return null;
    return held;
}

/* ------------------------------------------- sorting what the page gave us */

/**
 * A number out of a cell, whichever way this game writes them.
 *
 * `2.79` is a distance and `1.450` is a thousand and a half, and both turn up
 * in the same table. A dot before exactly three digits at the end is a
 * thousands separator; anything else is a decimal point. Decided per value,
 * which is safe because a column holds one kind of thing.
 */
function hfNum(text) {
    const m = /-?\d[\d.,]*/.exec(String(text || ''));
    if (!m) return null;
    let t = m[0];
    if (/^-?\d{1,3}([.,]\d{3})+$/.test(t)) t = t.replace(/[.,]/g, '');
    else t = t.replace(',', '.');
    const n = Number(t);
    return Number.isFinite(n) ? n : null;
}

/** Every table holding destinations. There can be more than one. */
function hfTables() {
    const seen = new Set();
    for (const a of document.querySelectorAll(HF_PICK_LINK)) {
        const t = a.closest('table');
        if (t) seen.add(t);
    }
    return [...seen];
}

const hfText = (s) => String(s || '').replace(/\s+/g, ' ').trim();

/**
 * ONE DESTINATION IS NOT ALWAYS A ROW.
 *
 * The prison list is not a table at all. Its capture came back with
 * `rowClasses: {}`, 32 `/gefangener/` links and `destinations: { noRow: true }`
 * — each link sitting in a plain `div`. Everything here read `tr` and `cells`,
 * so the bar drew itself over a list it could then neither sort nor filter.
 *
 * WHICH ELEMENT IS "THE ROW" IS WORKED OUT, NOT NAMED. Climb from the link
 * until it is one of SEVERAL SIBLINGS that each hold a destination: that is
 * what "one destination per block" looks like in any layout, table or not. A
 * list of class names to try would have answered nothing here, exactly as a
 * list of section ids answered nothing on the same page.
 *
 * On the prison page the answer is the link itself — thirty-two `<a>` side by
 * side in one `div.prison-select`, with an `<h5>` between yours and the
 * alliance's. So the climb starts AT the link, not above it.
 *
 * AND `closest('tr')` IS NOT A SHORTCUT TO IT. Inside a mission window the
 * whole `div.prison-select` sits in one `tr.tablesorter-childRow` under the
 * vehicle it belongs to — so taking the nearest row first swallowed all
 * thirty-two destinations into a single block, which the capture showed as one
 * "row" with a 2604-character name and no pieces at all. The climb answers
 * every layout on its own, including a table's: a hospital link's `<td>` has no
 * destination-carrying siblings, so it climbs to the `<tr>`, which does.
 */
function hfBlockOf(link) {
    const holds = (el) => el.matches(HF_PICK_LINK) || !!el.querySelector(HF_PICK_LINK);
    let el = link;
    while (el && el.parentElement && el !== document.body) {
        if ([...el.parentElement.children].filter(holds).length > 1) return el;
        el = el.parentElement;
    }
    // One destination on the page: nothing to sort or hide it against.
    return link.parentElement || null;
}

/**
 * The blocks, grouped by the element they sit in.
 *
 * Sorting only ever moves a block inside its own parent — a row lifted into
 * another tbody would leave the game's own grouping behind it, and a card moved
 * out of its container would leave its layout behind it.
 */
function hfGroups() {
    const groups = new Map();
    for (const a of document.querySelectorAll(HF_PICK_LINK)) {
        const block = hfBlockOf(a);
        if (!block || !block.parentElement) continue;
        if (!groups.has(block.parentElement)) groups.set(block.parentElement, new Set());
        groups.get(block.parentElement).add(block);
    }
    return [...groups].map(([parent, blocks]) => ({ parent, blocks: [...blocks] }));
}

/**
 * What a block says, piece by piece.
 *
 * A row says it in cells. A block that is not a row says it in its own text,
 * and the game states it the same way every time:
 *
 *   NYPD | 7th Precinct(Available cells: 2, Distance: 0.69 km, owner's tax: 0%)
 *
 * — the name, then a bracketed list. So the brackets are the cells: the head is
 * one piece and each comma-separated item inside is another. Splitting only
 * inside the brackets is what keeps a name with a comma in it whole.
 *
 * The leaves come first, so an element with no element children contributes its
 * whole text and `29 / 30` is never broken in half by the markup around it.
 */
const HF_BRACKETED = /^([^(]*)\((.+)\)\s*$/;

function hfParts(el) {
    if (el.cells) return [...el.cells].map((c) => hfText(c.textContent));
    const out = [];
    const push = (raw) => {
        const t = hfText(raw);
        if (!t) return;
        const m = HF_BRACKETED.exec(t);
        if (!m) { out.push(t); return; }
        const head = hfText(m[1]);
        if (head) out.push(head);
        for (const piece of m[2].split(',')) {
            const p = hfText(piece);
            if (p) out.push(p);
        }
    };
    const visit = (node) => {
        for (const child of node.childNodes) {
            if (child.nodeType === 3) push(child.textContent);
            else if (child.nodeType === 1) {
                if (child.firstElementChild) visit(child);
                else push(child.textContent);
            }
        }
    };
    visit(el);
    return out;
}

/**
 * The figure inside a piece, without the word the game put in front of it.
 *
 * `Distance: 0.69 km` is the distance column of a table that has no columns.
 * A cell has no label, so this hands it straight back — which is what makes one
 * set of rules read both shapes.
 */
const hfValue = (part) => {
    const at = String(part || '').lastIndexOf(':');
    return at === -1 ? hfText(part) : hfText(String(part).slice(at + 1));
};

/**
 * What this table's columns are called and which of them hold numbers.
 *
 * ASKED OF THE PAGE, NOT GUESSED. Which cell carries the distance cannot be
 * found by name — not one row carries a class — so the table is asked instead:
 * its own headers name the columns, and a column counts as sortable when most
 * of its cells read as a number. That way a column this has never heard of
 * sorts just as well, and a game update that adds one needs no change here.
 */
/**
 * Which column is the distance, and what the columns are called.
 *
 * THE HEADING WAS THE WRONG PLACE TO ASK. A real page came back with six
 * headings over seven cells — `Buildings, Distance, Free beds, Department, ,`
 * against a row of name, distance, beds, **tax**, department, the button and an
 * empty one — so heading four sits over the tax column and anything matching by
 * position is one out from there on. The cells say it themselves instead: a
 * distance carries its unit, `0.75 km`, and no other column in that table does.
 * Read the value, not the label over it.
 *
 * THE COLUMNS ARE WORKED OUT ONCE, NOT PER TABLE. `#own-hospitals` and
 * `#alliance-hospitals` are two tables of the same shape, and asking each of
 * them put "Distance" in the dropdown twice — one entry that worked and one
 * that looked broken. One list, applied to both.
 */
const HF_DISTANCE_VALUE = /\d[\d.,]*\s*(km|mi|miles?|meilen)\b/i;

/** How far a transport may go before the list stops offering it. */
const HF_DEFAULT_MAX = 50;

const hfAllRows = () => hfGroups().flatMap((g) => g.blocks);

function hfColumns() {
    const rows = hfAllRows();
    if (!rows.length) return [];
    const parts = rows.map(hfParts);
    const heads = [...(hfTables()[0]?.querySelectorAll('thead th, thead td') || [])];
    const width = Math.max(...parts.map((p) => p.length));
    const out = [];
    const used = new Set();
    for (let i = 0; i < width; i += 1) {
        const pieces = parts.map((p) => p[i] || '');
        const values = pieces.map(hfValue);
        const numbers = values.filter((v) => hfNum(v) !== null).length;
        if (numbers < Math.max(2, Math.ceil(rows.length * 0.6))) continue;
        // All one value is a column nobody would sort by.
        if (new Set(values).size < 2) continue;
        /* A heading where the page has one; otherwise the word the game itself
         * put in front of the figure — `Distance: 0.69 km` names its own column
         * on a list that has no headings at all. */
        const stated = pieces.map((t) => (t.includes(':') ? hfText(t.slice(0, t.indexOf(':'))) : ''))
            .filter(Boolean);
        const heading = hfText(heads[i]?.textContent) || stated[0] || '';
        let label = heading || `Column ${i + 1}`;
        // Two tables of the same shape must not name the same column twice.
        if (used.has(label)) label = `${label} (${i + 1})`;
        used.add(label);
        out.push({
            index: i,
            label,
            // The value says it, the heading over it may not be the right one.
            distance: values.filter((v) => HF_DISTANCE_VALUE.test(v)).length > values.length / 2,
        });
    }
    return out;
}

/**
 * Which rows belong to which half of the list.
 *
 * `#own-hospitals` and `#alliance-hospitals` are in the page, but whether they
 * are the container or the heading above it is not something a capture said.
 * So both shapes are handled: if the element holds destinations it is the
 * container, otherwise the next thing after it that does. Neither, and the
 * control is not offered at all rather than offered and doing nothing.
 */
function hfSectionRows(id) {
    const el = document.getElementById(id);
    if (!el) return null;
    let holder = el.querySelector(HF_PICK_LINK) ? el : null;
    for (let n = holder ? null : el.nextElementSibling; n; n = n.nextElementSibling) {
        if (n.querySelector(HF_PICK_LINK)) { holder = n; break; }
    }
    if (!holder) return null;
    return new Set([...holder.querySelectorAll(HF_PICK_LINK)]
        .map(hfBlockOf).filter(Boolean));
}

/** Sort, then hide what the player did not ask to see. */
/**
 * One destination, read off whatever it states its figures in.
 *
 * A hospital is a row and says it in cells. A prison is a single `<a>` among
 * thirty-one others and says it in its own text:
 *
 *   NYPD | 7th Precinct(Available cells: 2, Distance: 0.69 km, owner's tax: 0%)
 *
 * `hfParts` hands both back as pieces, so one set of rules reads both: a figure
 * carries its unit, free space is `n / n`, tax ends in `%`. The only thing the
 * bracketed form adds is the word in front of the figure, and `hfValue` takes
 * that off.
 *
 * FREE SPACE IS THE ONE PLAIN COUNT A DESTINATION STATES. The prison list says
 * `Free cells: 1` where the hospital table says `29 / 30`, so where no piece
 * reads as `n / n` the first piece that is a plain whole number — and is
 * neither the distance nor the tax, both of which are read by shape first — is
 * that count. Nothing here reads the word, so it is the same rule in any
 * language the game is played in.
 */
function hfRead(block) {
    const link = block.matches?.(HF_PICK_LINK) ? block : block.querySelector(HF_PICK_LINK);
    if (!link) return null;
    const parts = hfParts(block);
    /* On a row, cell 0 repeats everything for a narrow screen, so it is never
     * asked for a figure — only for the name. A block that is not a row states
     * its name in the same first piece and nothing twice. */
    const rest = block.cells ? parts.slice(1) : parts;
    const values = rest.map(hfValue);
    const distance = values.find((t) => HF_DISTANCE_VALUE.test(t));
    const beds = values.map((t) => /^(\d+)\s*\/\s*(\d+)$/.exec(t)).find(Boolean);
    const tax = values.map((t) => /^(\d[\d.,]*)\s*%$/.exec(t)).find(Boolean);
    const count = beds ? null : values.find((t) => /^\d+$/.test(t));
    const label = block.querySelector?.('.label');
    const said = (label?.textContent || '').trim();
    return {
        block,
        name: ((block.cells ? block.cells[0]?.firstChild?.textContent : null)
            || parts[0] || '').trim().slice(0, 60),
        km: distance ? hfNum(distance) : null,
        free: beds ? Number(beds[1]) : (count ? Number(count) : null),
        tax: tax ? hfNum(tax[1]) : null,
        // Yes, no, or the page did not say — and "did not say" is not "no".
        department: /^(yes|ja)$/i.test(said) ? true : /^(no|nein)$/i.test(said) ? false : null,
    };
}

/**
 * Which one is the best of a list — and it is only ever MARKED.
 *
 * Treatment first: a patient who can be treated where he lands is the whole
 * point, so a hospital with the department wins over a nearer one without. Only
 * where none of them has it does it become a plain distance case.
 *
 * Then the nearest of those. Then, and only then, the swap: if the nearest
 * charges and there is a free one in the same group, the free one is the pick.
 * That is a saving rather than a detour, because everything still on screen is
 * already inside the range the player set.
 *
 * NOTHING IS PRESSED, AND THAT IS THE WHOLE DESIGN. The mark says which one
 * this would have chosen; the click is the player's, on the game's own link.
 * A destination with no room left is not a candidate, and one whose distance
 * cannot be read is left out rather than assumed to be near.
 */
function hfBest(rows) {
    const usable = rows.filter((r) => r.km !== null && (r.free === null || r.free > 0));
    if (!usable.length) return null;
    const treating = usable.filter((r) => r.department === true);
    const pool = treating.length ? treating : usable;
    const byDistance = pool.slice().sort((a, b) => a.km - b.km);
    const nearest = byDistance[0];
    const why = (pick, reason) => ({ pick, why: reason, treats: !!treating.length });
    if (!(nearest.tax > 0)) return why(nearest, 'nearest');
    const free = byDistance.find((r) => r.tax === 0);
    return free ? why(free, 'nearest free') : why(nearest, 'nearest');
}

/**
 * Put the mark on, and take every other one off.
 *
 * GREEN ON THE CELLS, NOT ON THE ROW. Bootstrap's table styling and the game's
 * dark theme both put a background on `td`, so a colour on the `<tr>` sits
 * behind them and nothing shows. `.success` is the game's own class for this
 * and it is defined for both, so it goes on the row AND on every cell — which
 * also means it follows the theme rather than carrying a colour of YMCA's own.
 *
 * And green says nothing on a list of green buttons: a block that is not a row
 * is marked `active`, Bootstrap's own word for the one that is chosen.
 */
function hfMark(blocks, best) {
    for (const el of blocks) {
        el.classList.remove('success', 'active');
        if (el.cells) for (const td of el.cells) td.classList.remove('success');
        el.removeAttribute('data-ymca-best');
    }
    if (!best) return;
    const el = best.pick.block;
    if (el.cells) {
        el.classList.add('success');
        for (const td of el.cells) td.classList.add('success');
    } else {
        el.classList.add('active');
    }
    el.setAttribute('data-ymca-best', best.why);
}

function hfApply(ctx, cfg) {
    const columns = hfColumns();
    /* Nearest first is the ground state, not a choice somebody has to make
     * every time: with nothing picked the distance column still orders the
     * list, and picking another column is what departs from it. */
    const nearest = columns.find((c) => c.distance) || null;
    const own = hfSectionRows('own-hospitals');
    const alliance = hfSectionRows('alliance-hospitals');
    let shown = 0;
    let total = 0;

    const marked = [];
    for (const group of hfGroups()) {
        const blocks = group.blocks;
        if (!blocks.length) continue;
        const visible = [];
        /* "The first ten" is ten per list. Inside a mission window every
         * vehicle carrying a prisoner has a list of its own, and one running
         * count across all of them left the later vehicles with nothing
         * showing at all. */
        shown = 0;

        const column = columns.find((c) => c.label === cfg.sortBy) || nearest;
        if (column) {
            const key = (el) => hfNum(hfValue(hfParts(el)[column.index]));
            const sorted = [...blocks].sort((a, b) => {
                const x = key(a);
                const y = key(b);
                if (x === null) return 1;      // unreadable blocks go last, either way
                if (y === null) return -1;
                return cfg.sortDown ? y - x : x - y;
            });
            /* Only within one parent: a row lifted into another tbody would
             * leave the game's own grouping behind it, and a card moved out of
             * its container would leave its layout behind it. */
            for (const el of sorted) group.parent.append(el);
        }

        for (const el of blocks) {
            let hide = false;
            if (cfg.who === 'own' && own) hide = !own.has(el);
            if (cfg.who === 'alliance' && alliance) hide = !alliance.has(el);
            /* THE RANGE IS A CEILING ON THE COLUMN BEING SORTED BY, not a
             * distance this knows the units of. Sort by distance and "at most
             * 20" is twenty of whatever that column counts in; sort by price
             * and it is a price. The page names the column and the player
             * names the number, so neither has to be guessed — and a block
             * whose figure cannot be read is never hidden by it. */
            if (!hide && column && cfg.max > 0) {
                const value = hfNum(hfValue(hfParts(el)[column.index]));
                if (value !== null && value > cfg.max) hide = true;
            }
            if (!hide && cfg.limit && shown >= cfg.limit) hide = true;
            el.style.display = hide ? 'none' : '';
            if (!hide) { shown += 1; total += 1; visible.push(el); }
        }

        /* THE BEST ONE IS MARKED, NEVER PRESSED. It is judged on what is still
         * on screen, so the range and the sections the player set are already
         * in it, and it is redone on every redraw — a mark that stayed put when
         * the range changed would be pointing at a hospital that is no longer
         * offered. One per list, because in a mission window each vehicle
         * carrying a prisoner has a list of its own and the nearest cell for
         * one of them is the wrong answer for another. */
        const best = cfg.best === false ? null
            : hfBest(visible.map(hfRead).filter(Boolean));
        hfMark(blocks, best);
        if (best) marked.push(best);
    }
    ctx.log.info('destinations filtered', `${total} shown, by ${cfg.sortBy || 'page order'}`);
    return { total, marked };
}

/**
 * On a vehicle waiting for a destination: the controls, and remembering where
 * "next" points.
 *
 * The click is only listened to. It is never taken over, never prevented and
 * never repeated as a fetch — the player's own click is what assigns the
 * hospital, and that cannot be undone.
 */
function hfOnPickPage(ctx) {
    if (document.getElementById('hf-bar')) return true;
    const link = document.querySelector(HF_PICK_LINK);
    if (!link) return false;

    const next = document.querySelector(HF_NEXT);
    const columns = hfColumns();

    /* NEAREST FIRST, AND A CEILING, WITHOUT ANYBODY ASKING FOR EITHER.
     *
     * The game's own order puts your own hospitals above nearer ones, which is
     * not an order anybody driving there would choose. Nearest first is the
     * ground state now — `hfApply` falls back to the distance column whenever
     * nothing else is picked — so it cannot be lost by a redraw writing an
     * empty sort back, which is exactly how the first version of this lost it.
     *
     * The ceiling is seeded once and marked, rather than inferred from a field
     * being unset: `max` is written back as 0 on every redraw, so "nobody has
     * chosen" stopped being visible after the first one. */
    const cfg = hfCfg(ctx);
    if (!cfg.seeded) {
        cfg.seeded = 1;
        if (!(cfg.max > 0)) cfg.max = HF_DEFAULT_MAX;
        ctx.store.write('cfg', cfg);
        ctx.log.info('seeded the defaults', `at most ${cfg.max}, nearest first`);
    }

    const haveSections = !!(hfSectionRows('own-hospitals') || hfSectionRows('alliance-hospitals'));
    const total = document.querySelectorAll(HF_PICK_LINK).length;

    /* The game's own Bootstrap, never YMCA's role classes: this is the game's
     * page and it has to follow it into whatever theme it is wearing. */
    const bar = document.createElement('div');
    bar.id = 'hf-bar';
    bar.className = 'alert alert-info';
    bar.style.margin = '6px 0';
    bar.innerHTML = `
    <div style="display:flex;flex-wrap:wrap;gap:10px;align-items:center">
      <b>Status 5 Helper</b>
      <label style="font-weight:400;margin:0;cursor:pointer">
        <input type="checkbox" id="hf-advance" ${cfg.advance !== false ? 'checked' : ''}>
        Go straight to the next transport</label>
      ${next ? `<a class="btn btn-xs btn-success" id="hf-next"
        href="${next.getAttribute('href')}">Next transport</a>`
        : '<span style="opacity:.75">This is the last transport.</span>'}
    </div>
    <div style="display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin-top:7px">
      ${columns.length ? `<label style="font-weight:400;margin:0">Sort by
        <select id="hf-sort" class="input-sm">
          <option value="">the page's own order</option>
          ${columns.map((c) => `<option value="${ctx.esc(c.label)}"${
        c.label === cfg.sortBy ? ' selected' : ''}>${ctx.esc(c.label)}</option>`).join('')}
        </select></label>
      <label style="font-weight:400;margin:0;cursor:pointer">
        <input type="checkbox" id="hf-down" ${cfg.sortDown ? 'checked' : ''}> biggest first</label>`
        : '<span style="opacity:.75">No column in this table reads as a number.</span>'}
      ${columns.length ? `<label style="font-weight:400;margin:0">At most
        <input type="number" id="hf-max" min="0" step="1" style="width:74px"
          value="${cfg.max > 0 ? Number(cfg.max) : ''}" placeholder="any"
          ${cfg.sortBy ? '' : 'disabled title="pick a column to sort by first"'}>
        <span style="opacity:.75">${ctx.esc(cfg.sortBy || '\u2014')}</span></label>` : ''}
      <label style="font-weight:400;margin:0">Show
        <select id="hf-limit" class="input-sm">
          ${[0, 5, 10, 20, 40].map((n) => `<option value="${n}"${n === (cfg.limit || 0)
        ? ' selected' : ''}>${n ? `the first ${n}` : `all ${total}`}</option>`).join('')}
        </select></label>
      ${haveSections ? `<label style="font-weight:400;margin:0">
        <select id="hf-who" class="input-sm">
          ${[['all', 'Yours and the alliance\u2019s'], ['own', 'Yours only'],
        ['alliance', 'The alliance\u2019s only']].map(([v, t]) => `<option value="${v}"${
        v === (cfg.who || 'all') ? ' selected' : ''}>${t}</option>`).join('')}
        </select></label>` : ''}
      <label style="font-weight:400;margin:0;cursor:pointer">
        <input type="checkbox" id="hf-best" ${cfg.best !== false ? 'checked' : ''}>
        Mark the best one</label>
      <span style="opacity:.75" id="hf-count"></span>
    </div>
    <div style="margin-top:7px" id="hf-best-said"></div>`;

    /* Above whatever holds the destinations. `before()` needs a parent, so a
     * table sitting directly in <body> falls back to going in at the top. */
    const holder = link.closest('table') || link.closest('div');
    if (holder && holder.parentElement) holder.before(bar);
    else document.body.prepend(bar);

    const read = () => ({
        ...hfCfg(ctx),
        advance: bar.querySelector('#hf-advance').checked,
        sortBy: bar.querySelector('#hf-sort')?.value || '',
        sortDown: !!bar.querySelector('#hf-down')?.checked,
        best: !!bar.querySelector('#hf-best')?.checked,
        limit: Number(bar.querySelector('#hf-limit').value) || 0,
        max: Number(bar.querySelector('#hf-max')?.value) || 0,
        who: bar.querySelector('#hf-who')?.value || 'all',
    });
    const redraw = () => {
        const now = read();
        ctx.store.write('cfg', now);
        /* The ceiling belongs to whichever column is being sorted by, so it
         * follows the sort rather than being fixed when the bar was drawn —
         * a box that stays greyed out after you pick a column is a box that
         * looks broken. */
        /* The ceiling belongs to whichever column is actually ordering the
         * list — the one picked, or the distance column that orders it when
         * nothing is. Tying it to the dropdown alone left it greyed out for
         * ever, because nearest-first is a fallback rather than a choice. */
        const effective = columns.find((c) => c.label === now.sortBy)
            || columns.find((c) => c.distance);
        const max = bar.querySelector('#hf-max');
        if (max) {
            max.disabled = !effective;
            max.title = effective ? '' : 'no column in this table reads as a number';
            max.nextElementSibling.textContent = effective ? effective.label : '\u2014';
        }
        const { total: shown, marked } = hfApply(ctx, now);
        bar.querySelector('#hf-count').textContent = shown < total
            ? `${shown} of ${total} shown` : '';
        /* WHICH ONE AND WHY, IN WORDS, because a green row on its own is a
         * recommendation nobody can check. The click stays the player's, so
         * the reason has to be readable before they make it. */
        const said = bar.querySelector('#hf-best-said');
        if (said) {
            const first = marked[0];
            said.innerHTML = !first ? ''
                : `<b>Best: ${esc(first.pick.name)}</b> · ${first.pick.km} away${
                    first.pick.free !== null ? ` · ${first.pick.free} free` : ''}${
                    first.treats ? ` · can treat` : ''} <span style="opacity:.75">(${
                    esc(first.why)}${marked.length > 1
                        ? `, and one per list in ${marked.length} lists` : ''})</span>`;
        }
    };
    bar.addEventListener('change', redraw);
    // A number field only fires `change` when it loses focus, and a range you
    // have to click away from to see is a range nobody trusts.
    bar.addEventListener('input', (e) => {
        if (e.target.id !== 'hf-max') return;
        redraw();
    });
    redraw();

    document.addEventListener('click', (e) => {
        const picked = e.target.closest(HF_PICK_LINK);
        if (!picked || hfCfg(ctx).advance === false) return;
        const href = document.querySelector(HF_NEXT)?.getAttribute('href');
        if (!href) { ctx.log.info('picked, but the page names no next vehicle'); return; }
        hfArmJump(href);
        ctx.log.info('picked a destination, next is armed', href);
    }, true);

    /* Why it did or did not advance, without anybody having to describe it.
     * "It does not go to the next one" has four different causes and only one
     * of them is a bug. */
    ctx.store.write('lastRun', {
        at: new Date().toISOString(),
        path: hfShape(location.pathname),
        inFrame: window.top !== window.self,
        destinations: total,
        namesNextVehicle: !!next,
        sortableColumns: columns.map((c) => c.label),
        sectionsFound: haveSections,
        advance: cfg.advance !== false,
    });
    return true;
}

/**
 * The page a pick lands on says so itself.
 *
 * THE FLAG WAS THE WRONG MECHANISM. Remembering where "next" pointed, then
 * reading it back after the navigation, has four ways to fail quietly and no
 * way to say which one happened. The capture ended that: picking a destination
 * lands on `/vehicles/<id>/patient/<hospital>` — a page with no destinations,
 * no tables and `#next-vehicle-fms-5` already on it. **The page is the proof.**
 * Nothing has to be remembered across the navigation and nothing can expire.
 *
 * "Leave without transport" is the same path with a negative hospital id, so it
 * moves on the same way.
 */
/**
 * Nothing left to do: close the window.
 *
 * A second on the pick page with no navigation is the game saying there is no
 * next transport — the button it would have put there is not there. Escape is
 * what the player would press, so Escape is what is pressed, on the top
 * document as well because the vehicle window is a frame inside the map's own
 * lightbox. No function of the game's is called by name: nothing here has seen
 * one, and a wrong guess would be a dead button rather than an honest one.
 */
function hfCloseWindow(ctx) {
    if (!HF_PICKED.test(location.pathname)) return;   // something moved us on after all
    const press = (doc) => {
        for (const type of ['keydown', 'keyup']) {
            doc.dispatchEvent(new KeyboardEvent(type, {
                key: 'Escape', code: 'Escape', keyCode: 27, which: 27,
                bubbles: true, cancelable: true,
            }));
        }
    };
    try {
        if (window.top !== window.self) press(window.top.document);
    } catch (e) { /* a frame from somewhere else is not ours to close */ }
    press(document);
    ctx.log.info('nothing left in status 5, pressed Escape');
}

/* Half of what it was. It waits only to be sure nothing navigated us on, and
 * every tenth of a second of that is one the player spends looking at a page
 * they are done with. The slider in the settings is how the right number gets
 * found; whatever comes back, a little is added back as a buffer. */
const HF_CLOSE_DEFAULT = 500;

function hfAfterPick(ctx) {
    if (!HF_PICKED.test(location.pathname)) return false;
    const next = document.querySelector(HF_NEXT);
    const href = next?.getAttribute('href');
    ctx.store.write('lastPick', {
        at: new Date().toISOString(),
        path: hfShape(location.pathname),
        inFrame: window.top !== window.self,
        namesNextVehicle: !!href,
        advance: hfCfg(ctx).advance !== false,
    });
    if (hfCfg(ctx).advance === false) {
        ctx.log.info('picked, but advancing is switched off');
        return true;
    }
    if (!href) {
        ctx.log.info('picked, and this page names no next vehicle');
        if (hfCfg(ctx).closeWhenDone !== false) {
            const wait = Number(hfCfg(ctx).closeAfter);
            setTimeout(() => hfCloseWindow(ctx),
                Number.isFinite(wait) && wait >= 0 ? wait : HF_CLOSE_DEFAULT);
        }
        return true;
    }
    if (new URL(href, location.origin).pathname === location.pathname) return true;
    ctx.log.info('picked, going to the next transport', href);
    location.href = href;
    return true;
}

/** The older route: a flag armed before the click, for a landing page that
 * carries no button of its own. Harmless where the page above answered. */
function hfFollowJump(ctx) {
    const jump = hfTakeJump();
    if (!jump) return;
    if (location.pathname === jump.path) {
        // The game landed there itself. Jumping again would skip a vehicle.
        ctx.log.info('already on the next vehicle, not jumping');
        return;
    }
    ctx.log.info('going to the next transport', jump.path);
    location.href = jump.href;
}

const HF_BUTTON_ID = 'ymca-hf-btn';

/**
 * On and off beside the game's own Alliance Radio.
 *
 * `#alliance_radio_on` sits in a `.flex-fixed-size` with its Off twin, and a
 * switch for "does it move me on by itself" belongs next to the other switch
 * about what happens without you. It is the same `advance` setting the panel
 * on the transport page carries — one thing, two places to reach it.
 */
function hfPaintButton(ctx) {
    const btn = document.getElementById(HF_BUTTON_ID);
    if (!btn) return;
    const on = hfCfg(ctx).advance !== false;
    btn.className = `btn btn-xs pull-right ${on ? 'btn-success' : 'btn-danger'}`;
    btn.textContent = `Status 5: ${on ? 'On' : 'Off'}`;
}

function hfMountButton(ctx) {
    if (document.getElementById(HF_BUTTON_ID)) return true;
    const radio = document.getElementById('alliance_radio_on')
        || document.getElementById('alliance_radio_off');
    if (!radio || !radio.parentElement) return false;

    const btn = document.createElement('a');
    btn.id = HF_BUTTON_ID;
    btn.href = '#';
    btn.setAttribute('role', 'button');
    btn.title = 'Go straight to the next transport after you pick a destination';
    btn.addEventListener('click', (e) => {
        e.preventDefault();
        ctx.store.write('cfg', { ...hfCfg(ctx), advance: hfCfg(ctx).advance === false });
        hfPaintButton(ctx);
        ctx.log.info(`advance ${hfCfg(ctx).advance === false ? 'off' : 'on'} from the radio row`);
    });
    radio.parentElement.append(btn);
    hfPaintButton(ctx);
    return true;
}

YMCA.register({
    /* The id stays `highfive`: it is the key every stored setting is filed
     * under, and renaming it would read as a fresh install to anybody who had
     * already set a range. Only what the player sees changed. */
    id: 'highfive',
    title: 'Status 5 Helper',
    tagline: 'Click through the transports',
    description: 'Sorts the hospitals and prisons a transporting vehicle can go to, nearest '
        + 'first, and marks the best one — treatment, then distance, then the free one. '
        + 'You click it; it then follows the game’s own link to the next transport.',

    /* An element tile, so it is never in the launcher: its work happens in the
     * game's own pages, and a tile on the front would open a panel that does
     * nothing. Off until it does something. */
    mainTile: false,
    optional: true,
    /* On. It stopped being a promise the moment the game's own
     * #next-vehicle-fms-5 turned out to exist. */
    defaultOn: true,

    onSwitch(on, ctx) {
        if (!on) document.getElementById(HF_BUTTON_ID)?.remove();
        else hfMountButton(ctx);
    },

    async mount(el, ctx) { hfPanel(el, ctx); },
    settings(el, ctx) { hfPanel(el, ctx); },
});

YMCA.inject('highfive', (ctx) => {
    /* The page a pick lands on is the first thing asked about, because it is
     * the one that proves a pick happened. */
    if (hfAfterPick(ctx)) return true;
    hfFollowJump(ctx);
    /* Falsy, not true: a page that is not a vehicle is not a job done. The
     * player can switch HighFive on while looking at the map and open a
     * transport a moment later, and marking it finished here would mean the
     * bar never appeared until the next reload. */
    /* WHEREVER THERE ARE DESTINATIONS, NOT ONLY ON A VEHICLE PAGE. A prisoner
     * can be sent from inside a mission window too, and that page's address is
     * not `/vehicles/<id>` — so the page is asked what it holds rather than
     * what it is called. `hfOnPickPage` answers falsy where there is no link,
     * so this stays a page that is not finished rather than one that is. */
    if (/^\/vehicles\/\d+/.test(location.pathname)
        || document.querySelector(HF_PICK_LINK)) return hfOnPickPage(ctx);
    /* Everywhere else the switch beside the radio is placed, but this is never
     * finished here: a page that is not a transport page is not a job done, and
     * the map can still become one without a fresh document. */
    hfMountButton(ctx);
    return false;
});

/* --------------------------------------------------------------------------
 * EasyEdit — the game's own settings, where you already are.
 *
 * A group rather than a tool. Everything under it takes a setting the game
 * keeps two or three clicks away and puts the game's own control for it on the
 * page you are already looking at. Nothing under it invents a request: the
 * control it offers is the game's own, moved, so what gets sent is what the
 * game would have sent.
 *
 * A module joins by declaring `group: 'easyedit'`. ElementFriend then lists it
 * inside this tile rather than beside it, and switching EasyEdit off takes
 * every one of them with it.
 * ------------------------------------------------------------------------ */

YMCA.register({
    id: 'easyedit',
    title: 'EasyEdit',
    tagline: 'Settings where you already are',
    description: 'Takes a setting the game keeps behind two or three clicks and puts its own '
        + 'control on the page you are already on. Every one of them moves the game’s own '
        + 'field rather than building a request, and every one asks before it saves.',

    mainTile: false,
    optional: true,
    defaultOn: true,

    settings(el, ctx) {
        efGroupTiles(el, ctx, 'easyedit',
            'Each of these moves one of the game’s own fields. Nothing is sent until you '
            + 'press the button that says what it will do.');
    },
});

/* --------------------------------------------------------------------------
 * SwitchDispatchCenter — which dispatch centre a station answers to, up top.
 *
 * The answer is already at the top of every building page, in the navigation
 * row — `#building-navigation-container`, Previous building, the centre's own
 * name as a button, Next building. Changing it is somewhere else entirely, and
 * moving a run of stations means going there and back once per station.
 *
 * TWO THINGS THE FIRST VERSION GOT WRONG, and one capture settled both.
 *
 * IT IS A FRAME. A building opens in the game's own lightbox —
 * `<iframe class="lightbox_iframe" src="/buildings/5685072">` — so ruling out
 * frames, which is right for the map's own modules, ruled out every building
 * page there is. What is asked now is what the page holds, never where it sits.
 *
 * AND THE FORM IS NOT ON IT. `/buildings/<id>` came back with
 * `forms: []` and no `#building_leitstelle_building_id` anywhere. The select
 * lives on the building's own EDIT page, which the building page only links to:
 *
 *   <select name="building[leitstelle_building_id]"
 *           id="building_leitstelle_building_id">
 *     <option value=""></option>
 *     <option value="5694841">EMSManiacs</option>
 *     <option selected="selected" value="5677680">NY</option>
 *   </select>
 *
 * So that page is fetched once, which hands over both halves at the same time:
 * the options to offer, and the real form to send. Nothing here is built —
 * the FormData comes out of the game's own form and one field is replaced, so
 * the CSRF token and every unrelated setting on that page go back exactly as
 * they came. That is the same route RelabelTable takes.
 *
 * AND IT LOOKS LIKE THE GAME, BECAUSE IT IS THE GAME'S OWN DROPDOWN. The row
 * is a `.btn-group`, so what goes in it is a nested `.btn-group`: a caret
 * button wearing `btn btn-default btn-xs`, the same as the button naming the
 * centre beside it, and a `.dropdown-menu` under it. The game's own Bootstrap
 * shows that menu on `.open`, which is a class rather than a script, so this
 * needs none of the game's JavaScript to work — and it is written to the menu's
 * own `display` as well, so it still opens on a page whose stylesheet is built
 * differently.
 *
 * EACH ENTRY CARRIES ITS OWN BUTTON, AND THAT BUTTON IS THE CONFIRMATION. The
 * name is inert; the tick beside it is the one thing that moves anything. So
 * choosing is one press rather than pick-then-confirm, and a stray click on a
 * list still moves nothing — which is the whole reason the arming step existed.
 * Nothing has to say "Move to LI" either: the row already names the centre.
 * The one it is in now is marked and carries no tick, because there is nowhere
 * to move it to.
 *
 * ------------------------------------------------------------------------ */

const SD_SELECT = '#building_leitstelle_building_id';
const SD_FIELD = 'building[leitstelle_building_id]';
const SD_NAV = '#building-navigation-container';
const SD_ID = 'ymca-sd-pick';

/** The building this page is, by its own address. Frame or not. */
function sdBuildingId() {
    return (/^\/buildings\/(\d+)(?:$|[/?#])/.exec(location.pathname) || [])[1] || '';
}

/**
 * The game's own edit page: the options to offer and the form to send.
 *
 * One request, because both answers are on it. A page that does not carry the
 * select is a building the game does not let you assign — a dispatch centre
 * itself, for one — and then nothing is offered rather than offered and dead.
 */
async function sdEditPage(id) {
    const res = await fetch(`/buildings/${id}/edit`, { credentials: 'include' });
    if (!res.ok) throw new Error(`the edit page answered ${res.status}`);
    const doc = new DOMParser().parseFromString(await res.text(), 'text/html');
    const select = doc.querySelector(SD_SELECT);
    if (!select) return null;
    const form = select.closest('form') || doc.querySelector('form');
    if (!form) return null;
    const chosen = select.options[select.selectedIndex] || null;
    return {
        doc,
        form,
        options: [...select.options].map((o) => ({
            value: o.value, name: (o.textContent || '').trim(),
        })),
        current: chosen && chosen.value
            ? { id: chosen.value, name: (chosen.textContent || '').trim() } : null,
    };
}

/**
 * Where it goes in the navigation row.
 *
 * Straight after the button that names the current centre, so the answer and
 * the way to change it are in the same place. With no centre set the game puts
 * no such button there at all, and then it goes before Next building, which is
 * where that button would have been.
 */
function sdSlot(nav, current) {
    const links = [...nav.querySelectorAll('a')];
    if (current) {
        const naming = links.find((a) => (a.textContent || '').trim() === current.name);
        if (naming) return { node: naming, where: 'after' };
    }
    const next = links.find((a) => a.classList.contains('btn-success'));
    if (next) return { node: next, where: 'before' };
    return { node: nav, where: 'append' };
}

async function sdSend(page, value, ctx) {
    /* THE GAME'S OWN FORM, ONE FIELD REPLACED. Building a request by hand would
     * drop the CSRF token and every setting on that page that is not this one. */
    const data = new FormData(page.form);
    if (!data.has(SD_FIELD)) throw new Error(`no ${SD_FIELD} on the edit form`);
    data.set(SD_FIELD, value);
    // A document from DOMParser has no base URL, so form.action can come back empty.
    const action = page.form.getAttribute('action') || `/buildings/${sdBuildingId()}`;
    const post = await fetch(new URL(action, location.origin).toString(), {
        method: (page.form.getAttribute('method') || 'POST').toUpperCase(),
        body: data,
        credentials: 'include',
    });
    if (!post.ok) throw new Error(`saving answered ${post.status}`);
    ctx.log.info('dispatch centre changed', `${page.current?.name || 'none'} → ${value}`);
}

/** The game's own Bootstrap opens a menu on `.open`; the style is the fallback. */
function sdOpen(group, menu, open) {
    group.classList.toggle('open', open);
    menu.style.display = open ? 'block' : 'none';
}

async function sdMount(ctx) {
    if (document.getElementById(SD_ID)) return true;
    const nav = document.querySelector(SD_NAV);
    const id = sdBuildingId();
    if (!nav || !id) return false;

    /* Marked before the fetch, so a second attempt from the same page growing
     * does not ask the game twice for the same page. */
    const group = document.createElement('span');
    group.id = SD_ID;
    group.className = 'btn-group';
    group.style.position = 'relative';
    nav.append(group);

    let page;
    try {
        page = await sdEditPage(id);
    } catch (err) {
        ctx.log.warn('could not read the edit page', err.message);
        group.remove();
        return true;
    }
    /* A building the game does not let you assign. Nothing to offer, and that
     * is the building rather than a breakage. */
    if (!page) { group.remove(); return true; }

    const current = page.current;

    /* THE SAME BUTTON AS THE ONE NAMING THE CENTRE, which is what makes it read
     * as part of the game's own row rather than as something stuck to it. */
    const toggle = document.createElement('a');
    toggle.className = 'btn btn-default btn-xs dropdown-toggle';
    toggle.href = '#';
    toggle.setAttribute('role', 'button');
    toggle.setAttribute('aria-haspopup', 'true');
    toggle.setAttribute('aria-expanded', 'false');
    toggle.title = current
        ? `In ${current.name}. Pick another dispatch centre.`
        : 'Not assigned to a dispatch centre. Pick one.';
    /* POINTING THE WAY IT OPENS. A `.caret` is the game's own down-arrow, and
     * turning it a quarter keeps its colour and size while saying "leftwards",
     * which is where the menu now goes. */
    toggle.innerHTML = '<span class="caret" style="transform:rotate(90deg)"></span>';

    const menu = document.createElement('ul');
    /* IT OPENS LEFTWARDS BECAUSE THE ROW IS ALREADY AT THE RIGHT-HAND EDGE.
     * Hung from the left, the menu ran off the screen and half the centres
     * could not be reached; `dropdown-menu-right` is Bootstrap's own word for
     * it, and the two properties say the same thing where that class is not
     * defined. */
    menu.className = 'dropdown-menu dropdown-menu-right';
    menu.style.display = 'none';
    menu.style.right = '0';
    menu.style.left = 'auto';
    /* A tick at the height of the text beside it, in whatever colour it lands
     * in: no colour of YMCA's own, on the game's own page. */
    const tick = '<svg viewBox="0 0 16 16" width="12" height="12" fill="none"'
        + ' stroke="currentColor" stroke-width="2.5" stroke-linecap="round"'
        + ' stroke-linejoin="round" aria-hidden="true"><path d="M3 8.5 L6.5 12 L13 4"/></svg>';
    menu.innerHTML = page.options.map((o) => {
        const here = o.value === (current?.id || '');
        const name = esc(o.name || '\u2014 not assigned \u2014');
        /* The one it is in now has nowhere to move to, so it is marked and
         * carries no tick. */
        return `<li class="${here ? 'active' : ''}"><a href="#" data-sd="${esc(o.value)}"
          style="display:flex;gap:14px;align-items:center;justify-content:space-between;
          ${here ? 'cursor:default' : ''}" ${here ? 'data-here="1"' : ''}>
          <span>${name}</span>
          ${here ? '<span style="opacity:.6;font-size:11px">here</span>'
        : `<span class="btn btn-xs btn-success" data-go="${esc(o.value)}"
              title="Move it to ${name}">${tick}</span>`}
        </a></li>`;
    }).join('');

    toggle.addEventListener('click', (e) => {
        e.preventDefault();
        sdOpen(group, menu, menu.style.display === 'none');
        toggle.setAttribute('aria-expanded', menu.style.display === 'block' ? 'true' : 'false');
    });

    /* THE NAME IS INERT AND THE TICK IS THE ACTION. A list where the whole row
     * moves a station is a list one stray click ruins, which is exactly what
     * the arming step was there to prevent. */
    menu.addEventListener('click', async (e) => {
        e.preventDefault();
        const go = e.target.closest('[data-go]');
        if (!go) return;
        const value = go.getAttribute('data-go');
        sdOpen(group, menu, false);
        toggle.className = 'btn btn-default btn-xs disabled';
        toggle.innerHTML = '<span style="opacity:.7">\u2026</span>';
        try {
            await sdSend(page, value, ctx);
            /* The page names the old centre in its own row and its own heading,
             * so the honest thing is to let the game redraw it rather than to
             * paint the new one over the top. */
            location.reload();
        } catch (err) {
            toggle.className = 'btn btn-danger btn-xs';
            toggle.innerHTML = '<span class="caret" style="transform:rotate(90deg)"></span>';
            toggle.title = `It did not move: ${err.message}`;
            ctx.log.error('dispatch centre not changed', err.message);
        }
    });

    /* Anywhere else, or Escape: the way every menu on the page closes. */
    document.addEventListener('click', (e) => {
        if (!group.contains(e.target)) sdOpen(group, menu, false);
    });
    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') sdOpen(group, menu, false);
    });

    group.append(toggle, menu);
    const slot = sdSlot(nav, current);
    if (slot.where === 'after') slot.node.after(group);
    else if (slot.where === 'before') slot.node.before(group);
    return true;
}

YMCA.register({
    id: 'switchdispatch',
    title: 'SwitchDispatchCenter',
    tagline: 'Move a station, from the top',
    description: 'Puts the building’s own “Assigned Dispatch Center” dropdown into the '
        + 'navigation row at the top of the page, beside the centre it is in now. Picking one '
        + 'arms a button that names the move; nothing is sent until you press it.',

    group: 'easyedit',
    mainTile: false,
    optional: true,
    defaultOn: true,

    onSwitch(on, ctx) {
        if (!on) document.getElementById(SD_ID)?.remove();
        else sdMount(ctx);
    },
});

YMCA.inject('switchdispatch', (ctx) => {
    /* A BUILDING PAGE IS A FRAME, and ruling frames out ruled out every one of
     * them: the game opens a building in its own lightbox, so the address is
     * `/buildings/<id>` inside an iframe. The page is asked what it holds
     * instead — the navigation row to put the control in. */
    if (!sdBuildingId() || !document.querySelector(SD_NAV)) return false;
    sdMount(ctx);
    /* The fetch finishes on its own; the row is here, so this attempt is done.
     * A second attempt would ask the game for the same page again. */
    return true;
});

/* --------------------------------------------------------------------------
 * EagleEye — what the game shows you, and how much of it.
 *
 * A group rather than a tool. Everything under it changes how the game's own
 * pages look and nothing under it changes what the game does, so they belong
 * together and they belong behind one master switch: switch EagleEye off and
 * every layout change goes with it, without having to remember which ones were
 * on.
 *
 * A module joins by declaring `group: 'eagleeye'`. ElementFriend then leaves it
 * out of its own list and shows it here instead, so the switchboard does not
 * grow a row per tweak.
 * ------------------------------------------------------------------------ */

YMCA.register({
    id: 'eagleeye',
    title: 'EagleEye',
    tagline: 'How much the game shows',
    description: 'Changes to the way the game’s own pages look. Switch this off and every '
        + 'one of them goes with it.',

    mainTile: false,
    optional: true,
    defaultOn: true,

    settings(el, ctx) {
        efGroupTiles(el, ctx, 'eagleeye',
            'Nothing in here changes what the game does \u2014 only how much of it you are '
            + 'looking at.');
    },
});

/* --------------------------------------------------------------------------
 * ShutEye — a mission list you can read at a glance.
 *
 * The map's mission panels carry everything the game knows: the missing
 * vehicles line, the patient summary, the prisoner row, the pump progress, the
 * countdown. All of it useful, and all of it at once, which is why a screen
 * with eighteen missions on it is a wall of red text. ShutEye leaves the
 * artwork and the progress bar and folds the rest away.
 *
 * IT IS A STYLESHEET, NOT A SWEEP. The game redraws these panels constantly —
 * they are driven by the same socket that announces a mission ending — so
 * hiding elements one at a time means hiding them again every few seconds, and
 * missing the ones that arrive in between. One rule in one stylesheet applies
 * to a panel the game has not drawn yet.
 *
 * HIDE EVERYTHING, THEN PUT BACK WHAT IS WANTED. Naming the parts to hide means
 * a part the game adds next month is one nobody hid. The column is emptied and
 * the progress bar named back in, so anything new is quiet by default — which
 * is the way round that stays true.
 *
 * The panel is `#mission_panel_<id>`; inside its `.panel-body` the artwork sits
 * in `.col-xs-1` and everything else in `.col-xs-11`, one `<div>` per thing:
 * `mission_overview_countdown_<id>`, `mission_bar_outer_<id>` (the progress
 * bar), `mission_missing_<id>`, `mission_missing_short_<id>`,
 * `mission_pump_progress_<id>`, `mission_patients_<id>` and
 * `mission_prisoners_<id>`.
 * ------------------------------------------------------------------------ */

const SE_STYLE_ID = 'ymca-shuteye';
const SE_BUTTON_ID = 'ymca-shuteye-btn';

/** The three states the game paints a mission panel in. */
const SE_STATES = ['red', 'yellow', 'green'];

/**
 * THE GRADIENT CAME OFF WITH THE BOX.
 *
 * `display: contents` is what lets the heading's children lay out in the panel,
 * and the price is the heading's own box — its gradient, its text colour and
 * its bottom rule all go with it, which left a flat white strip where the
 * game had something worth looking at. Worse, the gradient is how a panel says
 * red, yellow or green, so losing it lost the state as well.
 *
 * So it is read back off the game, the way the palette in the shell was:
 * `getComputedStyle` on one heading of each state, moved onto the panel itself.
 * Nothing is invented and the three colours keep meaning what they meant. A
 * state that is not on screen right now is simply not sampled this time, and
 * what was learnt before is remembered — so after a few page loads all three
 * are known, and a game update repaints them without anybody editing a hex.
 */
function seSample(ctx) {
    const looks = ctx.store.read('looks', {});
    let changed = false;
    for (const state of SE_STATES) {
        const head = document.querySelector(`.panel.mission_panel_${state} > .panel-heading`);
        if (!head) continue;
        const cs = getComputedStyle(head);
        const look = {
            color: cs.color,
            background: cs.backgroundColor,
            image: cs.backgroundImage,
            border: `${cs.borderBottomWidth} ${cs.borderBottomStyle} ${cs.borderBottomColor}`,
        };
        if (JSON.stringify(looks[state]) !== JSON.stringify(look)) {
            looks[state] = look;
            changed = true;
        }
    }
    if (changed) ctx.store.write('looks', looks);
    return looks;
}

/** What can be put back, by the id the game gives it. */
const SE_PARTS = [
    { key: 'missing', prefix: 'mission_missing_', label: 'Missing vehicles' },
    { key: 'patients', prefix: 'mission_patients_', label: 'Patients' },
    { key: 'prisoners', prefix: 'mission_prisoners_', label: 'Prisoners' },
    { key: 'countdown', prefix: 'mission_overview_countdown_', label: 'Countdown' },
    { key: 'pump', prefix: 'mission_pump_progress_', label: 'Pump progress' },
];

function seCfg(ctx) {
    return ctx.store.read('cfg', {});
}

/**
 * ONE LINE, AND THE BOXES IN BETWEEN STEP OUT OF THE WAY.
 *
 * The artwork and the progress bar live in `.panel-body`; the Dispatch button
 * and the mission's name live in `.panel-heading`. They are in different
 * containers, so no amount of flex on either one will interleave them — and
 * moving the nodes with script would have to be done again every time the
 * socket redraws the panel.
 *
 * `display: contents` is what makes it a stylesheet job: it takes away a box
 * and lets its children lay out in the grandparent. Heading, body, the row and
 * both columns all step out, the panel itself becomes the flex row, and then
 * `order` puts them in the line the player asked for — icon, Dispatch, name,
 * bar. Anything put back takes a full line under it rather than squeezing the
 * name, which is what `flex: 1 1 100%` is for.
 *
 * The name is one line with an ellipsis rather than a word count: a word count
 * gives a ragged right edge, and the bar is what wants a predictable width.
 * The address is a second sentence inside the name and goes by default — it is
 * what made the name unreadable in the space left.
 */
/**
 * WHAT THE CALL IS LISTED AT, ON THE PANEL ITSELF.
 *
 * A panel carries `mission_type_id` as a plain attribute, and that is the key
 * straight into `/einsaetze.json`, where `average_credits` is the game's own
 * figure. So the number is a reading rather than anything measured here — it
 * is what TrackOps calls **Listed**, and it is marked `≈` on the panel for
 * exactly that reason.
 *
 * IT IS STILL A STYLESHEET. The game redraws a panel's insides constantly, so
 * writing the figure into the markup would mean writing it again every few
 * seconds. The panel element itself survives those redraws, so the figure goes
 * on the panel as an attribute and a `::after` rule shows it: one rule, and
 * the redraw underneath cannot take it off. Only a panel the game has newly
 * added needs stamping, which is what the observer is for and all it does.
 */
const SE_CREDITS_ATTR = 'data-ymca-credits';
let SE_LISTED = null;
let SE_WATCHER = null;

async function seListed(ctx) {
    if (SE_LISTED) return SE_LISTED;
    SE_LISTED = (async () => {
        const list = await ctx.game('/einsaetze.json');
        const by = {};
        for (const m of Array.isArray(list) ? list : []) {
            const paid = Number(m.average_credits);
            if (Number.isFinite(paid) && paid > 0) by[String(m.id)] = paid;
        }
        return by;
    })().catch(() => ({}));
    return SE_LISTED;
}

/** Stamp whatever the game has drawn and nothing else knows about yet. */
function seStamp(ctx, listed) {
    for (const panel of document.querySelectorAll('.panel[id^="mission_panel_"]')) {
        if (panel.hasAttribute(SE_CREDITS_ATTR)) continue;
        /* A plain attribute, not `data-` — the game writes it that way. */
        const type = panel.getAttribute('mission_type_id');
        const paid = type === null ? undefined : listed[String(type)];
        /* A mission type the catalogue does not carry gets no figure rather
         * than a nought: `/einsaetze.json` lists only what this player can
         * generate, so an alliance call from somebody else's building is
         * simply absent and inventing a zero would read as "pays nothing". */
        panel.setAttribute(SE_CREDITS_ATTR, paid ? `\u2248\u2009${ctx.fmt(paid)}` : '');
    }
}

/** Take back what was written, because an attribute outlives a stylesheet. */
function seUnstamp() {
    SE_WATCHER?.disconnect();
    SE_WATCHER = null;
    for (const panel of document.querySelectorAll(`[${SE_CREDITS_ATTR}]`)) {
        panel.removeAttribute(SE_CREDITS_ATTR);
    }
}

async function seWatch(ctx) {
    const listed = await seListed(ctx);
    seStamp(ctx, listed);
    if (SE_WATCHER) return;
    const list = document.getElementById('mission_list') || document.body;
    if (!list) return;
    let due = null;
    SE_WATCHER = new MutationObserver(() => {
        /* The socket redraws these panels several times a second, so the sweep
         * is debounced to the next frame's worth rather than run per mutation. */
        if (due) return;
        due = setTimeout(() => { due = null; seStamp(ctx, listed); }, 250);
    });
    SE_WATCHER.observe(list, { childList: true, subtree: true });
}

function seCss(cfg, looks) {
    const P = '.panel[id^="mission_panel_"]';
    const col = `${P} .panel-body .col-xs-11`;
    const bar = `${col} > div[id^="mission_bar_outer_"]`;
    const back = SE_PARTS.filter((p) => cfg[p.key]).map((p) => `${col} > div[id^="${p.prefix}"]`);

    const count = `${col} > div[id^="mission_overview_countdown_"]`;
    const rules = [
        `${col} > *{display:none !important}`,
        `${[bar, ...back].join(',')}{display:block !important}`,
    ];

    /* GREEN IS THE ONE STATE WHERE THE CLOCK IS THE WHOLE STORY. Every vehicle
     * is there, nothing is missing to read, and what is left to know is how
     * long it still runs. So the countdown comes back on a green panel whatever
     * it is set to elsewhere — one rule, and it follows a panel into green and
     * out again without anything here watching for it. */
    if (cfg.greenClock !== false) {
        rules.push(`${P}.mission_panel_green ${count}{display:inline-block !important}`);
    }
    if (!cfg.address) rules.push(`${P} small[id^="mission_address_"]{display:none}`);

    if (cfg.line !== false) {
        const width = Number(cfg.bar) || 30;
        rules.push(`${P}{display:flex;flex-wrap:wrap;align-items:center;gap:6px;padding:2px 8px}`,
            `${P} > .panel-heading,${P} > .panel-body,${P} .panel-body > .row,`
            + `${P} .panel-body > .row > .col-xs-1,`
            + `${P} .panel-body > .row > .col-xs-11{display:contents}`,
            `${P} .col-xs-1 img{order:1;flex:none;height:20px;width:auto}`,
            `${P} a[id^="alarm_button_"]{order:2;flex:none}`,
            `${P} span[id^="mission_participant"]{order:3;flex:none}`,
            `${P} a[id^="mission_caption_"]{order:4;flex:1 1 40px;min-width:0;`
            + 'overflow:hidden;text-overflow:ellipsis;white-space:nowrap}',
            `${bar}{order:6;flex:0 0 ${width}%;margin:0;height:14px}`);
        if (back.length) rules.push(`${back.join(',')}{flex:1 1 100%;order:10}`);
        /* The figure sits between the name and the bar, where the eye already
         * is. It is only drawn where there is one: an empty attribute is no
         * figure, and `content` of nothing draws nothing. */
        if (cfg.credits !== false) {
            rules.push(`${P}[${SE_CREDITS_ATTR}]::after{content:attr(${SE_CREDITS_ATTR});`
                + 'order:5;flex:none;opacity:.75;font-size:12px;white-space:nowrap}');
        }
        /* On one line the countdown is a word beside the bar rather than a row
         * of its own, so it goes after it rather than under it. */
        if (cfg.greenClock !== false) {
            rules.push(`${P}.mission_panel_green ${count}{order:7;flex:none;`
                + 'font-size:12px;white-space:nowrap}');
        }

        /* The heading's own look, put back on the panel now that the heading
         * has no box of its own to wear it. */
        for (const state of SE_STATES) {
            const look = looks?.[state];
            if (!look) continue;
            rules.push(`${P}.mission_panel_${state}{background-color:${look.background};`
                + `background-image:${look.image};color:${look.color};`
                + `border-bottom:${look.border}}`);
        }
    }
    return rules.join('\n');
}

/** Write the rule, or take it away. Both are one element. */
function seApply(ctx) {
    const cfg = seCfg(ctx);
    /* Two switches, and they mean different things: ElementFriend decides
     * whether ShutEye is part of this install at all, and the button on the
     * map decides whether it is folded right now. The first one gates the
     * second, so switching it off takes the button with it. */
    const available = YMCA.isOn('shuteye');
    const folded = available && cfg.on !== false;

    /* An attribute cannot be un-written by a stylesheet going away, so the two
     * edges are both handled here: stamped while it is folded, taken off when
     * it is not. */
    if (folded && cfg.credits !== false) {
        seWatch(ctx).catch((err) => ctx.log.warn('shuteye credits', err.message));
    } else {
        seUnstamp();
    }

    let style = document.getElementById(SE_STYLE_ID);
    if (!folded) style?.remove();
    else {
        if (!style) {
            style = document.createElement('style');
            style.id = SE_STYLE_ID;
            (document.head || document.documentElement).append(style);
        }
        // Sampled before the rule lands, so it reads the game and not itself.
        style.textContent = seCss(cfg, seSample(ctx));
    }

    if (!available) document.getElementById(SE_BUTTON_ID)?.remove();
    sePaintButton(ctx);
}

/**
 * The button, among the game's own mission filters.
 *
 * `#missions-panel-main` is the row that holds Emergency, Patient transports
 * and the rest, so a switch for how that list reads belongs in it rather than
 * two clicks away in a lightbox. It uses the game's own button classes, green
 * for on and plain for off, exactly as the filters beside it do.
 */
function seMountButton(ctx) {
    if (!YMCA.isOn('shuteye')) return false;
    if (document.getElementById(SE_BUTTON_ID)) return true;
    const row = document.getElementById('missions-panel-main');
    if (!row) return false;

    const btn = document.createElement('a');
    btn.id = SE_BUTTON_ID;
    btn.setAttribute('role', 'button');
    btn.href = '';
    btn.title = 'ShutEye — fold the mission list into one line';
    btn.addEventListener('click', (e) => {
        e.preventDefault();
        ctx.store.write('cfg', { ...seCfg(ctx), on: seCfg(ctx).on === false });
        seApply(ctx);
        ctx.log.info(`folded ${seCfg(ctx).on === false ? 'off' : 'on'} from the map`);
    });
    row.append(btn);
    sePaintButton(ctx);
    return true;
}

function sePaintButton(ctx) {
    const btn = document.getElementById(SE_BUTTON_ID);
    if (!btn) return;
    const on = seCfg(ctx).on !== false;
    btn.className = `btn btn-xs mission_selection ${on ? 'btn-success' : 'btn-default'}`;
    btn.innerHTML = `<span class="glyphicon glyphicon-eye-${on ? 'close' : 'open'}"></span>
    ShutEye`;
}

YMCA.register({
    id: 'shuteye',
    title: 'ShutEye',
    tagline: 'A quieter mission list',
    description: 'Folds every mission panel into one line \u2014 artwork, Dispatch, the name and '
        + 'the progress bar \u2014 and puts the rest away, so a screen full of calls reads at a '
        + 'glance.',

    group: 'eagleeye',
    mainTile: false,
    optional: true,
    defaultOn: false,

    /* Switching it off has to take the rule back out, and no reload should be
     * needed for that. */
    onSwitch(on, ctx) { seApply(ctx); },

    settings(el, ctx) {
        const cfg = seCfg(ctx);
        el.innerHTML = `
      <div class="ymca-note">The artwork and the progress bar always stay. Everything else is
        hidden unless you put it back here &mdash; that way round, a panel the game starts
        drawing next month is quiet without anybody having to notice it.</div>
      <div class="ymca-card">
        <b>Folded right now</b>
        <label style="display:block;margin-top:7px"><input type="checkbox" data-part="on"
          ${seCfg(ctx).on !== false ? 'checked' : ''}> Fold the mission list</label>
        <p class="ymca-dim" style="margin:6px 0 0;font-size:12px">The same switch sits on the map
          itself, with the game&rsquo;s own Emergency and Patient transport filters, so it can be
          turned off for a moment without opening this.</p>
      </div>

      <div class="ymca-card">
        <b>The one line</b>
        <label style="display:block;margin-top:7px"><input type="checkbox" data-part="line"
          ${cfg.line !== false ? 'checked' : ''}> Artwork, Dispatch, the name and the bar on one
          line</label>
        <label style="display:block;margin-top:7px"><input type="checkbox" data-part="address"
          ${cfg.address ? 'checked' : ''}> Keep the address after the mission name</label>
        <label style="display:block;margin-top:9px">Progress bar
          <select data-width style="margin-left:6px">
            ${[20, 30, 40, 50].map((n) => `<option value="${n}"${n === (Number(cfg.bar) || 30)
        ? ' selected' : ''}>${n}% of the line</option>`).join('')}
          </select></label>
        <p class="ymca-dim" style="margin:8px 0 0;font-size:12px">The name is cut with an
          ellipsis rather than after a set number of words, so the bar keeps the same width on
          every call.</p>
      </div>
      <div class="ymca-card">
        <b>Keep showing</b>
        <p class="ymca-dim" style="margin:4px 0 8px;font-size:12px">Each of these takes a line of
          its own under the mission rather than squeezing the name.</p>
        <div class="ymca-pick">
          ${SE_PARTS.map((p) => `<label><input type="checkbox" data-part="${ctx.esc(p.key)}"
            ${cfg[p.key] ? 'checked' : ''}> ${ctx.esc(p.label)}</label>`).join('')}
        </div>
      </div>

      <div class="ymca-card">
        <b>On the line itself</b>
        <label style="display:block;margin-top:7px"><input type="checkbox" data-part="credits"
          ${cfg.credits !== false ? 'checked' : ''}> What the call is worth</label>
        <label style="display:block;margin-top:7px"><input type="checkbox" data-part="greenClock"
          ${cfg.greenClock !== false ? 'checked' : ''}> The countdown once every vehicle is
          there</label>
        <p class="ymca-dim" style="margin:8px 0 0;font-size:12px">The figure is the game's own
          average for that kind of call, marked &#8776; because it is what the catalogue lists
          rather than what this one paid. A call the catalogue does not carry &mdash; an alliance
          call from somebody else's building &mdash; simply has none.</p>
      </div>`;
        el.addEventListener('change', (e) => {
            const width = e.target.closest('[data-width]');
            if (width) {
                ctx.store.write('cfg', { ...seCfg(ctx), bar: Number(width.value) });
                seApply(ctx);
                ctx.status(`Bar is ${width.value}% of the line.`);
                return;
            }
            const box = e.target.closest('[data-part]');
            if (!box) return;
            ctx.store.write('cfg', { ...seCfg(ctx), [box.dataset.part]: box.checked });
            seApply(ctx);
            ctx.status(`${box.checked ? 'Showing' : 'Hiding'} ${box.dataset.part}.`);
        });
    },
});

YMCA.inject('shuteye', (ctx) => {
    /* Only where there are mission panels to quieten. A mission window is not
     * the list, and a stylesheet in there would hide nothing and confuse the
     * next person reading the page. */
    if (window.top !== window.self) return true;
    seApply(ctx);
    /* The rule is written straight away; the button waits for the row that
     * holds the game's own filters, which arrives with the mission list. */
    return seMountButton(ctx);
});

/* --------------------------------------------------------------------------
 * StationFascination — the station list, one dispatch centre at a time.
 *
 * The map's station list is every building the account owns, in one column,
 * and on an account with three dispatch centres that is three regions of
 * stations scrolled past each other. The game filters by *kind* of building —
 * its own Firehouse / Rescue / Police buttons — and not by which centre a
 * station answers to. This adds that.
 *
 * THE GAME ALREADY WROTE THE ANSWER ON EVERY ROW. A station is
 * `li#building_list_<id>` carrying `building_type_id` and
 * `leitstelle_building_id` — the id of the dispatch centre it belongs to, as a
 * plain attribute. A dispatch centre is `building_type_id="1"` and its own
 * `leitstelle_building_id` is the string `"null"`. So the grouping is read
 * rather than fetched, and `/api/buildings` is never asked.
 *
 * IT IS A STYLESHEET, FOR THE SAME REASON SHUTEYE IS. The list is rebuilt
 * whenever the game refetches buildings and the vehicles under each station
 * load lazily on scroll, so anything written onto a row is gone by the next
 * redraw. One rule keyed on the game's own attribute survives all of it.
 *
 * IT ONLY EVER HIDES. The game's own search marks rows with
 * `building-filtered-by-search`, so a rule that forced rows visible would
 * fight it. Hiding what is not in the chosen centre and leaving everything
 * else alone means the two filters simply add up.
 * ------------------------------------------------------------------------ */

const SF_STYLE_ID = 'ymca-stationfascination';
const SF_PICK_ID = 'ymca-sf-pick';
const SF_LIST = '#building_list';

function sfCfg(ctx) {
    return ctx.store.read('cfg', { centre: '' });
}

/** The dispatch centres, named by the row the game drew for each of them. */
function sfCentres() {
    return [...document.querySelectorAll(`${SF_LIST} > li[building_type_id="1"]`)].map((li) => ({
        id: (li.id || '').replace('building_list_', ''),
        // The row's own link carries the name; `search_attribute` is the same text.
        name: li.getAttribute('search_attribute')
            || li.querySelector('.map_position_mover')?.textContent.trim()
            || li.id,
    })).filter((c) => c.id);
}

/** How many stations answer to each centre, so the list can say. */
function sfCounts() {
    const counts = {};
    for (const li of document.querySelectorAll(`${SF_LIST} > li[leitstelle_building_id]`)) {
        const key = li.getAttribute('leitstelle_building_id');
        counts[key] = (counts[key] || 0) + 1;
    }
    return counts;
}

/**
 * The picker's own look.
 *
 * A `<select>` is a native control and the game's `.btn-default` is white on
 * white in the probe, which between them made it unreadable — dark, light, and
 * worse again with an option highlighted. So it wears the browser's own form
 * pair, `Field` on `FieldText`, which is always legible against itself and
 * follows whatever theme the page is in. That is not a colour of YMCA's own:
 * it is the one the system uses for every other dropdown on the machine.
 */
const SF_LOOK = `#${SF_PICK_ID}{color-scheme:light dark;background-color:Field;color:FieldText;
  border:1px solid;border-color:rgba(128,128,128,.6);border-radius:3px;
  font:inherit;font-size:12px;line-height:1.4;padding:1px 4px;max-width:160px;height:auto}
#${SF_PICK_ID} option{background-color:Field;color:FieldText}`;

function sfCss(centre) {
    if (!centre) return SF_LOOK;
    return `${SF_LOOK}
/* Hide, never show: the game's own station search is the other half of this,
   and a forced display would override it rather than add up with it. */
${SF_LIST} > li[leitstelle_building_id]:not([leitstelle_building_id="${centre}"])`
        + `:not(#building_list_${centre}){display:none !important}
/* The centre you picked belongs at the top of its own list. A flex column and
   one order is all that takes, and it survives every redraw because it is
   keyed on the id the game writes itself. */
${SF_LIST}{display:flex;flex-direction:column}
${SF_LIST} > li#building_list_${centre}{order:-1}`;
}

function sfApply(ctx) {
    const on = YMCA.isOn('stationfascination');
    let style = document.getElementById(SF_STYLE_ID);
    if (!on) {
        style?.remove();
        document.getElementById(SF_PICK_ID)?.remove();
        return;
    }
    if (!style) {
        style = document.createElement('style');
        style.id = SF_STYLE_ID;
        (document.head || document.documentElement).append(style);
    }
    style.textContent = sfCss(sfCfg(ctx).centre);
}

/** The dropdown, in the game's own row of filter buttons. */
function sfMount(ctx) {
    if (document.getElementById(SF_PICK_ID)) return true;
    const list = document.querySelector(SF_LIST);
    const centres = sfCentres();
    /* Wait for the list rather than for the page: buildings are fetched after
     * the map, and one dispatch centre is the least that makes this a choice. */
    if (!list || centres.length < 2) return false;

    const counts = sfCounts();
    const cfg = sfCfg(ctx);
    const pick = document.createElement('select');
    pick.id = SF_PICK_ID;
    pick.innerHTML = `<option value="">All dispatch centres</option>
    ${centres.map((c) => `<option value="${esc(c.id)}"${c.id === cfg.centre ? ' selected' : ''}
      >${esc(c.name)}${counts[c.id] ? ` (${counts[c.id]})` : ''}</option>`).join('')}`;

    pick.addEventListener('change', () => {
        ctx.store.write('cfg', { ...sfCfg(ctx), centre: pick.value });
        sfApply(ctx);
        ctx.log.info('filtered by dispatch centre', pick.value || 'all');
    });

    const row = document.getElementById('btn-group-building-select')
        || document.getElementById('building_panel_heading');
    if (!row) return false;
    row.prepend(pick);
    sfApply(ctx);
    return true;
}

